(window.GIM_TS=window.GIM_TS||{})["Chullin.11"]={"from":264,"a":[["\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: כהן המוכר בהמתו לישראל ואמר לו \u0003\"על מנת שהמתנות שלי\"\u0004 — אין הישראלי חייב לתיתן לו, אלא הריהו \u0003נותן\u0004 את המתנות \u0003לכל כהן שירצה.\u0004 שכיון שמכר לו את כל הבהמה, אינו יכול להתנות על מתנותיה, שאינן שייכות לו אלא לכל שבט הכהנים. ושלא כמשנתנו שפטור הקונה הישראלי מן המתנות!","ודוחים: וכי ממקרה (שהוא עניינה של הברייתא) שבו הכהן המוכר אומר \u0003\"על מנת\u0004 שהמתנות שלי\" על מקרה (שהוא עניינה של משנתנו) שבו הכהן המוכר אומר \u0003\"חוץ\u0004 מן המתנות\" \u0003קא רמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]?!\u0006 והרי לשון \u0003\"חוץ\"\u0004 משמעה \u0003שיורא\u0004 \u0005[שיור],\u0006 שהשאיר הכהן את המתנות אצלו, שלא מכרן לישראל, ולכן חייב הישראלי לתיתן לו. ואילו לשון \u0003\"על מנת\"\u0004 — \u0003לאו שיורא\u0004 \u0005[אין\u0006 משמעה \u0005שיור],\u0006 שאין הכהן משאיר לעצמו את המתנות, אלא עושה תנאי עם הקונה שתינתנה לו המתנות, ואין בכוחו להתנות תנאי כזה.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על ברייתא זו ממה ששנינו בברייתא אחרת: כהן המוכר לישראל את בהמתו ואמר לו \u0003\"על מנת שהמתנות שלי\"\u0004 — \u0003המתנות שלו,\u0004 שחייב הקונה לתיתן לכהן זה, ושלא כברייתא הקודמת שפטרה במקרה כזה את הקונה מלתת מתנותיו לכהן זה! ומסבירים: חלוקות ביניהן ברייתות אלה, ו\u0003בהא פליגי\u0004 \u0005[בזה נחלקו],\u0006 ש\u0003מר סבר\u0004 \u0005[חכם זה\u0006 שבברייתא השניה \u0005סבור]\u0006 כי אמירת \u0003\"על מנת\"\u0004 — לשון \u0003שיורא\u0004 \u0005[שיור]\u0006 \u0003הוא,\u0004 ולכך המתנות הינן של הכהן המוכר. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה\u0006 שבברייתא הראשונה \u0005סבור]\u0006 כי אמירת \u0003\"על מנת\"\u0004 — \u0003לאו שיורא\u0004 \u0005[לא\u0006 לשון \u0005שיור]\u0006 \u0003הוא,\u0004 אלא לשון תנאי וכיון שאין הכהן יכול להתנות כך, אין \u0003הקונה הישראלי חייב לתת לו את מתנותיה.\u0004","שנינו במשנתנו: \u0003אמר לו\u0004 לטבח: \u0003מכור לי בני מעיה\u0004 (ובכללן הקיבה שהיא ממתנות הכהונה) של פרה ששחטת \u0003—\u0004 נותן הקונה את הקיבה לכהן, ואינו מנכה למוכר את דמי הקיבה. ואולם אם קנה את בני המעיים לפי משקל ושקל לו אף את הקיבה — נותן הקונה לכהן את הקיבה, ואולם מנכה מהכסף הניתן למוכר את דמי משקלה של הקיבה. ובענין זה \u0003אמר רב: לא שנו\u0004 שצריך הקונה לתת את הקיבה לכהן, \u0003אלא\u0004 כ\u0003ש\u0004הקונה \u0003שקל לעצמו\u0004 את בני המעיים שקנה. שבמקרה כזה הכהן דורש את מתנות כהונה מן הקונה ולא מן הטבח. \u0003אבל\u0004 כש\u0003שקל לו\u0004 ה\u0003טבח\u0004 — \u0003הדין\u0004 של הכהן אף \u0003עם הטבח,\u0004 שיכול הכהן להתדיין עם זה או עם זה. \u0003ו\u0004אילו \u0003רב אסי אמר: אפילו\u0004 כאשר \u0003שקל לו\u0004 ה\u0003טבח\u0004 — \u0003הדין עמו,\u0004 עם הקונה בלבד.","ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003ב\u0004שיטתו של \u0003רב חסדא קא מיפלגי\u0004 \u0005[הם חלוקים].\u0006 שכן \u0003אמר רב חסדא:\u0004 אדם ש\u0003גזל\u0004 מאדם אחר, \u0003ולא נתייאשו הבעלים\u0004 מן הגזילה שתשוב אליהם, \u0003ובא\u0004 אדם \u0003אחר ואכלו\u0004 את הדבר הגזול — אם \u0003רצה\u0004 הבעלים לגבות את דמי גזילתו \u0003מזה,\u0004 מן הגזלן הראשון — \u0003גובה. רצה\u0004 לגבות \u0003מזה\u0004 שאכל את הגזילה — \u0003גובה.\u0004 ולענייננו יש לומר ש\u0003מר\u0004 \u0005[חכם זה,\u0006 רב\u0005],\u0006 \u0003אית ליה\u0004 \u0005[יש לו,\u0006 סבור הוא\u0005]\u0006 כשיטת \u0003רב חסדא,\u0004 שיכול הנגזל לגבות ממי שירצה, וכמו כן יכול הכהן לגבות את מתנותיו ממי שירצה, אם מהקונה או מהטבח. \u0003ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה,\u0006 רב אסי\u0005],\u0006 \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 כשיטת \u0003רב חסדא,\u0004 ולכך הכהן תובע מתנותיו מן הקונה בלבד. ודוחים:","\u0003לא,\u0004 אלא \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 שניהם סבורים\u0005]\u0006 כשיטתו של \u0003רב חסדא, ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003מתנות כהונה נגזלות קא מיפלגי\u0004 \u0005[הם חלוקים].\u0006 ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב \u0005סבור]\u0006 כי מתנות כהונה \u0003נגזלות,\u0004 והריהן ברשות הגזלן ויכול לגבות ממנו אף שאחר אכלן, ואף בענייננו יכול הכהן להתדיין גם עם המוכר. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב אסי \u0005סבור]\u0006 כי מתנות כהונה \u0003אין נגזלות,\u0004 שאין כח בידי אדם לגוזלן, וכל עוד הן קיימות מוטל חוב נתינתן על המחזיק בהן, ולכך יכול הכהן להתדיין על מתנותיו רק עם הקונה המחזיק עתה בהן.","ומעירים: \u0003איכא דמתני לה להא שמעתא\u0004 \u0005[יש ששונה הלכה זו,\u0006 מחלוקת זו של רב ורב אסי בשאלת גזילת מתנות כהונה\u0005]\u0006 לא כהסבר למחלוקתם בדין מתנות כהונה, אלא כהלכה \u0003בפני עצמה, רב אמר: מתנות כהונה נגזלות, ורב אסי אמר: מתנות כהונה אין נגזלות.\u0004","\u0003גר שנתגייר והיתה לו פרה,\u0004 אם \u0003נשחטה\u0004 פרה זו על ידי אדם מישראל \u0003עד שלא\u0004 (בטרם) \u0003נתגייר\u0004 — הריהו \u0003פטור\u0004 ממתנות כהונה, שכן בשעת שחיטתה היתה הפרה עדיין של גוי. ואם נשחטה \u0003משנתגייר\u0004 — הריהו \u0003חייב\u0004 בנתינת מתנות מפרה זו, ככל אדם מישראל. \u0003ספק\u0004 אם נשחטה קודם שהתגייר או לאחר שהתגייר — \u0003פטור\u0004 מלתת את מתנותיה לכהן, \u0003ש\u0004כלל הוא כי \u0003המוציא מחבירו עליו הראיה,\u0004 וכל עוד לא יביא הכהן \u0003הוכחה שנשחטה הפרה לאחר שהתגייר, אין הגר חייב לתת את מתנותיה.\u0004","שנינו במשנתנו שבספק אם התחייב האדם במתנות כהונה, הריהו פטור מלתיתן. ובענין זה מסופר \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 ש\u0003רמי ליה\u0004 \u0005[השליך,\u0006 הראה סתירה בדברי תנאים במקומות שונים\u0005]\u0006 \u0003ר' שמעון בן לקיש לר' יוחנן.\u0004 שכן במשנתנו \u0003תנן\u0004 \u0005[שנינו]\u0006 שב\u0003ספק\u0004 — \u0003פטור\u0004 מלתת מתנות כהונה, \u0003אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003ספיקא\u0004 \u0005[ספק]\u0006 — נדון \u0003לקולא\u0004 \u0005[להקל].\u0006","\u0003ו\u0004על כך \u0003רמינהו\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 ממה ששנינו בדין לקט (התבואה הנושרת מתחת ידי הקוצרים בשעת קצירה, ממתנות עניים), כי התבואה הנמצאת ב\u0003חורי הנמלים שבתוך הקמה\u0004 שבשדה שטרם הגיעו הקוצרים אליה — \u0003הרי אלו של בעל הבית,\u0004 שאין בתבואה זו דין לקט. \u0003ו\u0004אילו הנמצאת בחורי הנמלים שבתוך הקמה \u0003שלאחר הקוצרים,\u0004 החיטים \u0003העליונים,\u0004 אלה של פי החור — שייכות \u0003לעניים,\u0004 שיש לומר שלקט הן שנשרו מן השיבולים בשעת הקצירה. \u0003ו\u0004אילו \u0003התחתונים,\u0004 אלה שבקרקעית חור — \u0003של בעל הבית,\u0004 שייתכן שקודם הקצירה אספו אותן נמלים לשם, ואין הן של \u0003לקט.\u0004","\u0003ר' מאיר אומר: הכל לעניים, שספק לקט\u0004 — \u0003לקט.\u0004 הרי שלדעת ר' מאיר בספק מתנות עניים מכריעים להחמיר, ושלא כשיטת משנתנו במתנות כהונה, וסתם משנה (שלא צויין בה במפורש מי אמר את הדברים) הריהי דעת ר' מאיר. ונמצא שלפנינו סתירה בדברי ר' מאיר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש בתשובה: \u0003אל תקניטני\u0004 בשאלה זו, \u0003ש\u0004הרי אין דברי ר' מאיר שנויים בברייתא זו כדרך שאמרת (\"ר' מאיר אומר\"), שמשמע שזו היא דעת ר' מאיר בוודאות. אלא \u0003בלשון\u0004 שלפיה חכם \u0003יחיד\u0004 הוא שאמר שכן היא דעת ר' מאיר, \u0003אני שונה אותה\u0004 ברייתא שהבאת כסתירה בדברי ר' מאיר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה בן אגרא אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' מאיר: ספק לקט\u0004 — \u0003לקט, ספק שכחה\u0004 — \u0003שכחה, ספק פאה\u0004 — \u0003פאה.\u0004 ואין להקשות מדברי חכם אחד (הסבור שכך היא דעתו של ר' מאיר) על דברי משנתנו.","\u0003אמר לו\u0004 ר' שמעון בן לקיש לר' יוחנן בדחיית דבריו: והרי אפילו אם \u0003אל\u0004 (לא) \u0003תשנה אותה\u0004 ברייתא \u0003אלא בלשון\u0004 שלפיה אותו שוטה נודע הנקרא בשם \u0003בן תדל\u0004 אמר שזו היא דעת ר' מאיר, עדיין הריהי קושיה על דברי משנתנו, \u0003והא טעמא קאמר\u0004 \u0005[והרי טעם,\u0006 נימוק לדבר \u0005הוא אומר]\u0006 מדוע יש לנהוג בספק מתנות עניים להחמיר ולתיתן לעניים, שכן \u0003אמר ר' שמעון בן לקיש: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש מקרא זה \u0005שנאמר]\u0006 \u0003\"עני ורש הצדיקו\"\u0004 (תהלים פב, ג)? \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"הצדיקו\"?\u0004","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה \u0003בדינים,\u0004 שיש לדיינים להשתדל למצוא לו זכות בדין — \u0003והא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ודל לא תהדר בריבו\"\u0004 (שמות כג, ג), שאין לדיין לנהוג כן. \u0003אלא\u0004 הכוונה לומר שהמסופק אם עליו לתת מתנות עניים אם לאו, אף שספק הוא, מכל מקום \u0003צדק משלך, ותן לו.\u0004 ומעתה מובן מדוע במשנתנו נקבע שבספק מתנות כהונה נוהגים להקל, ואילו בספק מתנות עניים נוהגים להחמיר!","\u0003אמר רבא\u0004 בתשובה: \u0003הכא\u0004 \u0005[כאן,\u0006 בספק מתנות כהונה בזה שהתגייר\u0005]\u0006 נוהגים להקל, משום שה\u0003פרה\u0004 שלו \u0003בחזקת פטורה קיימא\u0004 \u0005[עומדת],\u0006 שבעודו גוי היתה הפרה פטורה ממתנות כהונה. מה שאין כן בספק מתנות עניים שה\u0003קמה\u0004 — \u0003בחזקת חיובא קיימא\u0004 \u0005[חיוב\u0006 לקט \u0005עומדת].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא בקושיה על הסברו זה: \u0003והרי\u0004 גם בדין חיוב חלה ב\u0003עיסה\u0004 של גר, אומרים אנו כי אם העיסה \u0003נעשית עד שלא\u0004 (בטרם) \u0003נתגייר\u0004 — הריהו \u0003פטור מן\u0004 הפרשת \u0003החלה\u0004 מעיסה זו. ואם נעשתה העיסה \u0003משנתגייר\u0004 — הריהו \u0003חייב\u0004 להפריש ממנה חלה. \u0003וב\u0004\u0003ספק\u0004 אם נעשתה העיסה לפני שהתגייר או לאחר שהתגייר — הריהו \u0003חייב,\u0004 שספק חלה — חלה, אף שעיסת הגוי בחזקת פטור היא, שהרי היתה בחזקתו בעודו גוי, ועיסה שגולגלה בידי גוי פטורה מן החלה. ומדוע לא יהא דינה כדין ספק מתנות כהונה שפוטרים את הגר מלתיתן משום שהפרה היתה בחזקת פטור?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאביי: אין להשוות ספק חלה לספק מתנות כהונה, שכן בחלה אף שיש לה חזקת פטור, יש בה ספק איסור, שיש עונש מיתה באכילתה, וכלל הוא כי ב\u0003ספק איסורא\u0004 \u0005[איסור]\u0006 הולכים אנו \u0003לחומרא\u0004 \u0005[להחמיר].\u0006 ואילו ספק מתנות כהונה אינו אלא ספק ממוני, וכלל הוא כי ב\u0003ספק ממונא\u0004 \u0005[ממון]\u0006 הולכים \u0003לקולא\u0004 \u0005[להקל],\u0006 ולכן סומכים על חזקת הפטור של הפרה, לפטור את הגר ממתנות כהונה.","שכן \u0003אמר רב חסדא, וכן תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: שמונה\u0004 מקרים של \u0003ספקות נאמרו בגר,\u0004 ב\u0003ארבע\u0004 נקבע דינו של הספק \u0003לחיוב, ו\u0004ב\u0003ארבע\u0004 \u0003לפטור.\u0004","ומפרטים: בענין \u0003קרבן אשתו\u0004 שילדה, שספק אם ילדה לפני \u0003שהתגיירה, וחייבת בקרבן, או שמא ילדה לאחר מכן ואינה חייבת —\u0004 הרי זה ספק איסור כרת, שכל שלא התכפרה בקרבן הריהי ענושה כרת על אכילת קדשים. \u0003ו\u0004כן בספק אם עיסת הגר חייבת בהפרשת \u0003חלה\u0004 — הרי זה ספק איסור מיתה, שבאכילת חלה יש עונש מיתה. \u0003ו\u0004כן בספק הנוגע ל\u0003בכור בהמה טמאה\u0004 (פטר חמור) של הגר, שאסור בהנאה קודם שנפדה שספק אם נולד קודם שנתגייר או לאחר מכן. \u0003ו\u0004כן בספק הנוגע ל\u0003בכור בהמה טהורה\u0004 של הגר, שיש בדבר איסור כרת לענין שחיטתו מחוץ לעזרה — באלה הולכים אנו \u0003לחיוב.\u0004"],["ובענין ספק אם התחייב בנתינת \u0003ראשית הגז,\u0004 שספק אם נגזז צאנו לפני שהתגייר או לאחר מכן. \u0003ו\u0004כן אם התחייב בנתינת \u0003המתנות\u0004 לכהן, (זרוע לחיים וקיבה), שספק הוא מתי נשחטה בהמתו. \u0003ו\u0004כן אם הוא חייב בתשלום חמש סלעים הניתנים בדמי \u0003פדיון הבן,\u0004 \u0003ו\u0004כן בספק אם הוא חייב ב\u0003פדיון פטר חמור\u0004 בשה — כל אלה הריהם ספק ממון בלבד, ולכך נקבע בהם \u0003לפטור,\u0004 שאין הוא חייב לתת אותם לכהן.","ובענין המשא ומתן שבין ר' שמעון בן לקיש ור' יוחנן מוסרים ש\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, ומסר לחכמי בבל מתורת חכמי ארץ ישראל, \u0003אמר\u0004 כי ממה ששנינו בברייתא אחרת שר' מאיר פוטר מנתינת לקט ב\u0003קמה\u0004 של הגר שספק אם נקצרה לפני התגיירותו או לאחר מכן, על מה ששנינו בדברי ר' מאיר בדין \u0003קמה\u0004 שספק לקט לקט הוא, ר' שמעון בן לקיש \u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה לר' יוחנן סתירה בין השיטות\u0005],\u0006 והשיב לו ר' יוחנן שאין להקשות מאותה ברייתא, שכן היא דעתו של חכם יחיד, בן אגרא.","ועוד בענין מתנות עניים, מסופר כי החכם \u0003לוי זרע\u0004 תבואה \u0003ב\u0004מקום הנקרא \u0003כישר, ולא הוו\u0004 \u0005[היו]\u0006 \u0003עניים\u0004 באותו מקום \u0003למשקל\u0004 \u0005[לקחת]\u0006 \u0003לקט\u0004 משדהו. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 לוי \u0005לפני]\u0006 \u0003רב ששת\u0004 לשאול כיצד עליו לנהוג בלקט שבשדהו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: נאמר במצוות פאה ולקט \u0003\"לעני ולגר תעזוב אותם\"\u0004 (ויקרא כג, כב), \u0003ו\u0004אמרו חכמים שאם אין שם עניים — לא ישאיר את הפאה והלקט \u0003לא לעורבים ולא לעטלפים,\u0004 אלא יקחם לעצמו. ואף אתה קחם לעצמך.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו כי \u0003אין\u0004 הבעלים צריכים להטריח עצמם שיהיו \u0003מביאין\u0004 את ה\u0003תרומה לא מ\u0004ה\u0003גורן\u0004 (מקום ערימת התבואה בשדה) \u0003לעיר\u0004 לידי \u0003הכהן,\u0004 \u0003ולא ממדבר לישוב.\u0004 אלא הדבר מוטל על הכהן מקבל התרומה. \u0003ואם אין שם\u0004 בגורן או במדבר \u0003כהן\u0004 שיתנו לו את התרומה — הבעלים \u0003שוכר פרה ומביאה\u0004 את התרומה לעיר ולמקום ישוב, וטעם הדבר: \u0003מפני הפסד תרומה,\u0004 אם תושאר במקומה. ומדוע אין אומרים אף בלקט במקום שאין בו עניים, שיביאו אותו הבעלים למקום שיש בו עניים!","ומשיבים: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד הוא דין\u0005]\u0006 \u0003תרומה\u0004 — \u0003דטבלה\u0004 \u0005[ש\u0006כן \u0005היא טובלת,\u0006 גורמת לכל הפירות שיהיו באיסור טבל\u0005],\u0006 כל עוד לא הופרשה מהם התרומה, \u0003ו\u0004לכן \u0003לא סגיא דלא מפריש לה\u0004 \u0005[אין\u0006 זה \u0005מספיק\u0006 להתיר את התבואה כל עוד \u0005שלא הפריש אותה].\u0006 מה שאין כן לקט, שאינו אוסר את התבואה.","ומקשים: \u0003והרי\u0004 אף \u0003מתנות\u0004 כהונה (זרוע לחיים וקיבה) \u0003דלא טבלי\u0004 \u0005[שאין\u0006 הן \u0005טובלות],\u0006 שאין הן אוסרות באכילה את כל בשר הבהמה שלא ניתנו ממנה המתנות, \u0003ו\u0004בכל זאת \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 כי ב\u0003מקום שנהגו למלוג\u0004 (להטיל אל תוך מים רותחים) \u0003ב\u0004בשרם (עם עורם עליהם) של \u0003עגלים\u0004 הנשחטים כדי להסיר מהם את השער, שאוכלים אותם עם העור שעליהם — \u0003לא יפשיט את הזרוע\u0004 מעורו, אלא יתן לכהן את הזרוע עם העור שעליה.","וכן במקום שבו נוהגים \u0003להפשיט את הראש\u0004 של הבהמה מעורה — הנותן מתנות כהונה \u0003לא יפשיט את הלחי,\u0004 אלא יתן אותה עם העור שעליה. \u0003ואם אין שם כהן\u0004 שיקבל מתנות כהונה — \u0003מעלין\u0004 (שמים, מעריכים את השווי הכספי) \u0003אותן בדמים, ואוכלן\u0004 הבעלים, ולאחר מכן יתן את דמיהן לכהן. ונהגו כן \u0003מפני הפסד כהן.\u0004 הרי שאף במתנה שאינה אוסרת באכילה את השאר (\"אינה טובלת\") צריכים הבעלים לטרוח שתגיע המתנה לידי הכהן. ומדוע לא נקבע כן אף בלקט?","ומשיבים: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד הוא דין\u0005]\u0006 \u0003מתנות כהונה,\u0004 שכן לשון \u0003נתינה כתיבא ביה\u0004 \u0005[נאמרה בו],\u0006 ככתוב \"ונתן לכהן הזרוע והלחיים והקבה\" (דברים יח, ג). מה שאין כן בלקט. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שבאת לכך,\u0006 להסבר זה\u0005],\u0006 שוב אין צורך לומר שבתרומה צריכים הבעלים להביא אותה למקום שיש בו כהן, משום שהריהי טובלת את הפירות, אלא ההסבר ב\u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 משום שלשון \u0003\"נתינה\" כתיבא ביה\u0004 \u0005[נאמרה בה],\u0006 ככתוב \"ראשית דגנך תירושך ויצהרך... תתן לו\" (שם פסוק ד). \u0003ו\u0004שואלים: \u0003אלא\u0004 הלשון \u0003\"תעזוב\" יתירא\u0004 \u0005[היתירה]\u0006 שנאמרה בלקט (שנאמר \"ולקט קצירך לא תלקט... לעני ולגר תעזוב אותם\", ויקרא יט, ט—י. ושוב נאמר \"ולקט קצירך לא תלקט לעני ולגר תעזוב אותם\", שם כג, כב) \u0003למה לי,\u0004 מה היא באה ללמדנו, האם לא ללמדנו שאף במקום שאין בו עניים, על הבעלים לאסוף את הלקט, ולשומרו עבור העניים?","","ומשיבים: לשון יתירה זו באה ללמדנו \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003המפקיר את כרמו, ול\u0004מחרת ב\u0003שחר\u0004 (בבוקר) \u0003השכים\u0004 וזכה בכרם מן ההפקר \u0003ובצרו\u0004 — אף שכרם של הפקר פטור ממתנות עניים, כרם זה \u0003חייב בפרט ובעוללות ובשכחה ובפאה,\u0004 שכן בכל המתנות הללו נאמר לשון \"תעזוב\" נוספת, ללמדנו שיש לתיתן אף באופן זה. \u0003ו\u0004מכל מקום הפקר זה (כשאר הפקר) \u0003פטור מן המעשרות.\u0004","ומתוך שנדון למעלה אופן בו בעל שדה זוכה לעצמו במתנות עניים, מביאים ענין דומה. מסופר: \u0003ההוא שקא דדינרי דאתא לבי מדרשא\u0004 \u0005[שק אחד של דינרי\u0006 זהב \u0005ש\u0006נשלח עבור בני בית המדרש ו\u0005הובא לבית המדרש],\u0006 \u0003קדים\u0004 \u0005[הקדים,\u0006 הזדרז\u0005]\u0006 \u0003ר' אמי וזכה בהן,\u0004 ושואלים: \u0003והיכי עביד הכי\u0004 \u0005[וכיצד עשה כן],\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 במתנות כהונה \u0003\"ונתן\u0004 לכהן\" (דברים יח, ג), ולמדנו מכאן הוראה שדווקא כך יש לקבל מתנות כהונה, \u0003ולא שיטול מעצמו,\u0004 וכמו כן במתנות \u0003עניים, אין על המקבל לקחת מעצמו!\u0004 ומשיבים: \u0003ר' אמי נמי\u0004 \u0005[גם כן]\u0006 לא לעצמו לקח, \u0003אלא\u0004 \u0003לעניים זכה בהן. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003אדם חשוב\u0004 כראש ישיבה, וכר' אמי, \u0003שאני\u0004 \u0005[שונה]\u0006 הוא, שהריהו יכול לקחת לעצמו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא על הכתוב \u0003\"והכהן הגדול\u0004 \u0003מאחיו\"\u0004 (ויקרא כא, י) — צריך \u0003שיהא\u0004 הכהן הגדול \u0003גדול מאחיו בנוי בחכמה ובעושר.\u0004","","\u0003אחרים אומרים: מנין שאם אין לו,\u0004 לכהן הגדול עושר משל עצמו, \u0003שאחיו הכהנים מגדלין\u0004 (מעשירים) \u0003אותו\u0004 עד שיהא עשיר מהם — \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"והכהן הגדול מאחיו\"\u0004 — \u0003גדלהו משל אחיו.\u0004 וכיון שהיו צריכים בני בית המדרש להעשיר את \u0003ר' אמי מכספם, כל שכן הוא שרשאי ר' אמי לקחת לעצמו כדי לזכות עבורם.\u0004","לאחר שנשנו דיניהן של מתנות הזרוע והלחיים והקיבה מגדירים מהם הזרוע והלחיים שבבהמה: \u0003איזהו הזרוע\u0004 — זה חלק הבהמה ש\u0003מן הפרק של\u0004 ה\u0003ארכובה\u0004 (הברך התחתונה), \u0003עד כף\u0004 הירך \u0003של יד\u0004 (הרגל הקדמית, הם השוק והקולית של הרגל הקדמית הימנית), \u0003ו\u0004זה \u0003הוא\u0004 ה\"זרוע\" הנזכר בתורה בדינו \u0003של\u0004 ה\u0003נזיר\u0004 (\"ולקח הכהן את הזרוע בשלה מן האיל\", במדבר ו,יט). \u0003וכנגדו ברגל\u0004 האחורית הימנית, באותם החלקים (מן הברך התחתונה ועד כף הירך), היא ה\u0003שוק\u0004 והקולית, שהרי מבהמת קרבן שלמים נותנים לכהן את השוק. \u0003ר' יהודה אומר:\u0004 ה\u0003שוק\u0004 הניתן לכהן בקרבן השלמים אינו כולל את הקולית, אלא הוא \u0003מן הפרק של ארכובה עד סובך של רגל,\u0004 הוא הברך העליונה המחברת את החלק האמצעי של הרגל עם החלק העליון. \u0003אי זהו לחי\u0004 — זה חלק הבהמה ש\u0003מן הפרק של לחי\u0004 (הלחי התחתונה, לאחר הצדעיים, ולמטה) \u0003עד פיקה\u0004 (הטבעת העליונה) \u0003של גרגרת\u0004 (הקנה). שנינו במשנתנו מהו חלק הבהמה הנקרא \"זרוע\" שניתן לכהן. ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר במצות מתנות כהונה \"וזה יהיה משפט הכהנים מאת העם מאת זובחי הזבח אם שור אם שה ונתן לכהן הזרוע והלחיים והקבה\" (דברים יח, ג): \u0003\"הזרוע\"\u0004 — \u0003זה זרוע ימין\u0004 של הבהמה. ודנים בדבר: \u0003אתה אומר\u0004 ש\u0003זה זרוע ימין, או\u0004 אולי \u0003אינו אלא זרוע שמאל?\u0004 ומשיבים: לכך \u0003תלמוד לומר\u0004 \u0003\"הזרוע\"\u0004 בה\"א הידיעה, הזרוע הימנית.","","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה, הלימוד],\u0006 כיצד נלמד הדבר מתוספת ה\"א הידיעה שבמלה? ומשיבים: הרי זה \u0003כ\u0004דרך ש\u0003אמר רבא\u0004 בדרשת הכתוב האמור \u0003\"על כן לא יאכלו בני ישראל את גיד הנשה אשר על כף הירך\"\u0004 (בראשית לב,לב) — באה ה\"א הידיעה שבמלה \u0003\"הירך\"\u0004 ללמדנו שזו \u0003המיומנת\u0004 (החשובה) \u0003שבירך. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 למדים אנו מן ה\"א הידיעה שבמלה \u0003\"הזרוע\"\u0004 — זה \u0003המיומן שבזרוע,\u0004 שהיא הזרוע הימנית.","וממשיכים בדרשת הנאמר במתנות כהונה, הכתוב \u0003\"והלחיים\" למאי אתא\u0004 \u0005[למה בא,\u0006 מה הוא מלמדנו\u0005]?\u0006 \u0003להביא\u0004 (לרבות) אף את ה\u0003צמר שבראש\u0004 \u0003כבשים, ו\u0004ה\u0003שער שבזקן\u0004 ה\u0003תיישים,\u0004 שאף הם ניתנים לכהן. והכתוב \u0003\"והקבה\" למאי אתא\u0004 \u0005[למה בא,\u0006 מה הוא מלמדנו\u0005]?\u0006 \u0003להביא\u0004 \u0003אף את ה\u0004\u0003חלב שעל גבי הקבה, ו\u0004את ה\u0003חלב שבתוך הקבה,\u0004 שאף אלה ניתנים לכהן. שכן \u0003אמר ר' יהושע: כהנים נהגו בו\u0004 (בחלב, זה שעל גבי הקיבה וזה שבתוך הקיבה) \u0003עין יפה ונתנוהו\u0004 (הסכימו שלא לקבלו, וויתרו עליו) \u0003לבעלים,\u0004 ויש לדייק בדברים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאין החלב ניתן לכהנים — משום שכך \u0003נהגו\u0004 הכהנים משום עין יפה שלהם, \u0003הא\u0004 \u0005[הרי]\u0006 נסיק מכאן כי אם הכהנים \u0003לא נהגו\u0004 כן — \u0003דידיה\u0004 \u0005[שלו,\u0006 של הכהן\u0005]\u0006 \u0003הוא\u0004 החלב.","ומביאים עוד מדרשת חכמים במצות נתינת זרוע הלחיים והקיבה: \u0003דורשי חמורות היו אומרים\u0004 בטעמה של מצות נתינת זרוע ולחיים וקיבה: \u0003הזרוע\u0004 — \u0003כנגד היד\u0004 של פינחס בן אלעזר הכהן, שהרג את זמרי בן סלוא, ועצר בכך את המגיפה מעל בני ישראל, \u0003וכן הוא,\u0004 הכתוב, \u0003אומר \"ויקח רומח בידו\"\u0004 (במדבר כה, ז).","\u0003ולחיים\u0004 — \u0003כנגד\u0004 ה\u0003תפלה\u0004 שהתפלל פינחס באותה עת, \u0003וכן הוא אומר \"ויעמוד פנחס ויפלל\u0004 ותעצר המגפה. ותחשב לו לצדקה לדור ודור עד עולם\" (תהלים קו,ל-לא). ה\u0003קבה\u0004 לכהנים — זו הקיבה \u0003כמשמעה,\u0004 כדרך שהיא נזכרת בתיאור מעשה פינחס, \u0003וכן הוא אומר\u0004 \u0003\"וידקור את שניהם את איש ישראל\u0004 \u0003ואת האשה אל קבתה\u0004 ותעצר המגפה מעל בני ישראל\" (במדבר שם,ח). למעלה הובא מאין למדים אנו כי מתנת הזרוע היא מזרוע ימין של הבהמה, \u0003ו\u0004מעירים כי ה\u0003תנא\u0004 של הברייתא הבאה \u0003מייתי לה\u0004 \u0005[מביא,\u0006 למד \u0005אותה\u0006 הלכה שהזרוע הניתנת לכהן היא של ימין\u0005]\u0006 \u0003מהכא\u0004 \u0005[מכאן],\u0006 מן האמור בנתינה לכהן מקרבן השלמים: \"ואת שוק הימין תתנו תרומה לכהן מזבחי שלמיכם\". ודנים בכתוב: \u0003\"שוק הימין\"\u0004 — \u0003אין לי אלא שוק הימין\u0004 של קרבן השלמים, ואולם \u0003זרוע מוקדשין\u0004 של איל נזיר \u0003מנין\u0004 לנו שאף היא של ימין — \u0003תלמוד לומר\u0004 \"תתנו \u0003תרומה\u0004 לכהן\". ואף \u0003זרוע\u0004 של בהמת \u0003חולין\u0004 הניתנת לכהן במתנותיו \u0003מנין\u0004 לנו שהיא של ימין — \u0003תלמוד לומר \"תתנו\".\u0004","","שנינו במשנתנו: \u0003איזהו לחי\u0004 — \u0003מן הפרק של לחי ועד פיקה של גרגרת.\u0004 ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בענין נתינת לחי לכהן ש\u0003נוטלה\u0004 מן הבהמה הנשחטת \u0003ובית שחיטה עמה,\u0004 והרי בית השחיטה הוא מעבר לפיקה של הגרגרת!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן הן המשנה והן הברייתא סבורות כי הכהן מקבל את הלחי שעד הפיקה של הגרגרת, ואולם \u0003הא\u0004 \u0005[זו]\u0006 ששנינו במשנתנו שמקבל הכהן עד הפיקה של הגרגרת — הריהי כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ו\u0004אילו \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בברייתא שנוטלה הכהן עם בית השחיטה — הריהי כשיטת \u0003ר' חנינא בן אנטיגנוס.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 שחיטה שנעשית בה הבהמה \u0003מוגרמת,\u0004 שהחיתוך נעשה גבוה מן המקום הראוי בצואר, למעלה מבית הבליעה — הריהי שחיטה \u0003פסולה\u0004 לדעת חכמים. ואולם \u0003העיד ר' חנינא בן אנטיגנוס על מוגרמת שהיא כשרה.\u0004 שלשיטתו הכהן מקבל עד פיקה של הגרגרת שלדעתו אף היא מקום שחיטה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: \u0003הא והא\u0004 \u0005[זו וזו,\u0006 המשנה והברייתא\u0005]\u0006 — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש הנאמר \u0003\"עמה\"\u0004 — \u0003עמה\u0004 של ה\u0003בהמה,\u0004 שבית השחיטה נשאר עם גוף הבהמה אצל הבעלים, שאין הכהן נוטלה.",""],["דין \u0003ראשית הגז\u0004 שצריך כל אדם מישראל הגוזז את צאנו לתת לכהן כמתנת כהונה, \u0003נוהג\u0004 (קיים) בכל המקומות, הן \u0003בארץ\u0004 ישראל \u0003ו\u0004הן \u0003בחוץ לארץ.\u0004 וכן בכל הזמנים, הן \u0003בפני הבית,\u0004 בזמן שבית המקדש קיים \u0003ו\u0004הן \u0003שלא בפני הבית,\u0004 מאז נחרב בית המקדש. והריהו נוהג רק \u0003ב\u0004צאן של \u0003חולין, אבל לא ב\u0004צאן \u0003ה\u0004\u0003מוקדשים.\u0004","ומשווים הלכה זו להלכה הנידונה בפרק הקודם, מתנות הכהונה, הזרוע הלחיים והקבה: יש צד \u0003חומר\u0004 (חומרה) \u0003ב\u0004מצות \u0003זרוע ולחיים ובקבה\u0004 יותר \u0003מ\u0004מצות \u0003ראשית הגז\u0004 — \u0003ש\u0004כן \u0003הזרוע והלחיים והקבה נוהגין בבקר\u0004 (הבהמות הגסות) \u0003ובצאן\u0004 (הבהמות הדקות), שכן נאמר במצוה זו \"אם שור אם שה\". ובין \u0003במרובה\u0004 (בהרבה) בהמות שנשחטו, \u0003ו\u0004בין \u0003במועט\u0004 (במעט). \u0003ו\u0004אילו דין \u0003ראשית הגז אינו נוהג אלא ברחלות\u0004 (כבשים) בלבד, ולא בעיזים. \u0003ואינו נוהג אלא במרובה\u0004 (הרבה) כבשים שנגזזו.","\u0003וכמה הוא מרובה,\u0004 בכמה כבשים שנגזזו חלה מצות ראשית הגז? \u0003בית שמאי אומרים:\u0004 \u0003מ\u0004\u0003שתי רחלות, ש\u0004כן \u0003נאמר \"יחיה איש עגלת בקר ושתי צאן\"\u0004 (ישעיהו ז, כא) — הרי ששתי בהמות דקות נקראות בשם \"צאן\", והן בכלל הציווי \"ראשית גז צאנך\" (דברים יח, ד). \u0003ובית הלל אומרים:\u0004 מ\u0003חמש\u0004 רחלות, \u0003ש\u0004כן \u0003נאמר\u0004 בנתינתה של אביגיל אשת נבל הכרמלי לדוד ואנשיו \"ו \u0003חמש צאן עשויות\"\u0004 (שמואל א כה, יח) — הרי שחמש בהמות דקות נקראות \"צאן\", ובהם חלה מצוה זו.","\u0003ר' דוסא בן הרכינס אומר:\u0004 רק \u0003חמש רחלות\u0004 ה\u0003גוזזות\u0004 (שגיזת) כל אחת מהן לפחות \u0003מנה, מנה ופרס\u0004 (וחצי מנה), כלומר, כל אחת מהן מנה וחצי. הן ה\u0003חייבות ב\u0004נתינת \u0003ראשית הגז\u0004 מהן. \u0003וחכמים אומרים:\u0004 כל \u0003חמש רחלות\u0004 חייבות בנתינת ראשית הגז מהן, אף שהן \u0003גוזזות כל שהן.\u0004","ודנים עוד בפרטי הלכה זו: \u0003וכמה\u0004 מן הגיזה \u0003נותנין לו\u0004 לכהן? \u0003משקל חמש סלעים\u0004 ש\u0003ביהודה, שהן\u0004 משקל \u0003עשר סלעים\u0004 לפי החשבון ש\u0003בגליל,\u0004 שמשקל הסלע הגלילי הוא מחצית ממשקל הסלע שביהודה. ומשקל זה של צמר הניתן לכהן הריהו אמור דווקא בצמר ה\u0003מלובן\u0004 (נקי ורחוץ) \u0003ולא\u0004 בצמר \u0003צואי\u0004 (מלוכלך, כצמר בשעת גזיזתו). ואם נותן לכהן צמר צואי, צריך שיהיה בו כשיעור זה לאחר ליבונו. ונקבע שיעור זה, שזה הוא השיעור שיש בו \u0003כדי לעשות ממנו בגד קטן\u0004 שזו נחשבת מתנה ראויה. \u0003ש\u0004כן \u0003נאמר\u0004 \"וראשית גז צאנך \u0003תתן לו\"\u0004 — \u0003שיהא בו כדי מתנה\u0004 של ממש.","ועוד מדיני ראשית הגז: \u0003אם\u0004 \u0003לא הספיק\u0004 גוזז הצאן \u0003ליתנו\u0004 את ראשית הגז \u0003לו\u0004 לכהן \u0003עד\u0004 (טרם) \u0003שצבעו\u0004 את הצמר — הריהו \u0003פטור\u0004 מלתת, שנקנה לו הצמר בשינוי זה. ואם רק \u0003לבנו\u0004 (ניקה אותו) \u0003ולא צבעו\u0004 — אין זה שינוי שיקנה בו את הצמר, והריהו \u0003חייב\u0004 לתיתו לכהן.","ועוד הלכה: ישראל \u0003הלוקח\u0004 (הקונה) \u0003גז צאנו של גוי\u0004 — \u0003פטור מראשית הגז. הלוקח גז צאנו של חבירו, אם שייר המוכר\u0004 לעצמו חלק מצאנו לגזיזה — המוכר \u0003חייב\u0004 לתת לכהן את ראשית הגז מחלקו על הגיזה כולה. ואולם אם המוכר \u0003לא שייר\u0004 לעצמו מן הגיזה — \u0003הלוקח חייב\u0004 בנתינת ראשית הגז על כולן. ועוד הלכה: \u0003היו לו\u0004 למוכר \u0003שני מינים\u0004 של רחלות, \u0003שחופות\u0004 (לא שחורות ולא לבנות) \u0003ולבנות,\u0004 וגזזן ו\u0003מכר לו\u0004 את גיזת ה\u0003שחופות אבל לא\u0004 את גיזתן של ה\u0003לבנות,\u0004 או שהיו למוכר שני מיני כבשים, זכרים ונקבות, ועמד ומכר לו את גיזת \u0003ה\u0004\u0003זכרים אבל לא\u0004 את גיזת ה\u0003נקבות\u0004 — הרי \u0003זה\u0004 המוכר \u0003נותן\u0004 ראשית הגז מן הגיזה ששייר \u0003לעצמו, וזה\u0004 הקונה \u0003נותן\u0004 ראשית הגז מן הגיזה ששייר \u0003לעצמו.\u0004","שנינו במשנתנו כי דין ראשית הגז נוהג רק בצאן \u0003חולין אבל לא\u0004 \u0003במוקדשין,\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 חל חיוב זה אף במוקדשים? ומשיבים: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין ראשית הגז \u0003\"צאנך\"\u0004 (דברים יח, ד) — להורות כי דוקא בצאן שלך, של חולין, אתה חייב בנתינה לכהן, \u0003ולא\u0004 ב\u0003צאן הקדש.\u0004","ושואלים: \u0003טעמא דכתב רחמנא\u0004 \u0005[\u0006כל \u0005הטעם\u0006 לפטור צאן קדשים הינו משום \u0005שאמרה התורה]\u0006 \u0003\"צאנך\", הא לאו הכי הוה אמינא\u0004 \u0005[הרי בלא כן הייתי אומר]\u0006 שאף צאן \u0003קדשים חייבים בראשית הגז?\u0004 ו\u0003הא לאו\u0004 \u0005[והרי לא]\u0006 \u0003בני גיזה נינהו\u0004 \u0005[הם],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בקדשים \u0003\"ולא תגוז בכור צאנך\"\u0004 (שם טו, יט)!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 המדובר \u0003בקדשי מזבח, הכי נמי\u0004 \u0005[כך גם כן]\u0006 שאין צורך בפסוק ללמד שאינם חייבים בראשית הגז, ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנתנו \u0005במה אנו עוסקים],\u0006 \u0003בקדשי בדק הבית\u0004 שמותרים בגיזה, ובא הכתוב ללמד שהם פטורים מראשית הגז.","ומקשים על הסבר זה: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר\u0004 כי אף \u0003קדשי בדק הבית אסורים בגיזה ועבודה,\u0004 ואין צורך ללמד שהם פטורים מראשית הגז! ומשיבים: איסור גיזה בקדשי בדק הבית הוא רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 ולא מן התורה. ומעתה, \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006היה מקום ש\u0005יעלה על דעתך לומר]:\u0006 \u0003הואיל ומדאורייתא\u0004 \u0005[ומן התורה]\u0006 קדשי בדק הבית \u0003בני גיזה נינהו\u0004 \u0005[הם],\u0006 ו\u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 שעבר על דברי חכמים, ו\u0003גזז ליה\u0004 \u0005[אותו,\u0006 את זו שהוקדשה לבדק הבית\u0005],\u0006 \u0003ליתיב ליה\u0004 \u0005[שיתן לו\u0006 לכהן\u0005]\u0006 את ראשית הגז. לכך בא הפסוק לפוטרו.","ושבים ושואלים: \u0003והא קדיש לה\u0004 \u0005[והרי\u0006 צמר זה \u0005קדוש הוא],\u0006 ואינו יכול להינתן לכהן, ואין צורך בפסוק מיוחד לפוטרו מראשית הגז! ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003לפרוק וליתיב ליה\u0004 \u0005[שיפדה\u0006 הישראלי המקדיש, את צמר הצאן \u0005ושיתן אותו]\u0006 לכהן, ודמי הפדיון ילכו לבדק הבית.","ושואלים על הסבר זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0005כל דבר הקדש הנפדה\u0006 \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003העמדה והערכה\u0004 (שיעמוד לפני הכהן ויעריכנו הכהן את שוויו, ככתוב \"והעמיד את הבהמה לפני הכהן. והעריך אותה הכהן בין טוב ובין רע כערכך הכהן כן יהיה\" ויקרא כז, יא—יב), ואילו הצמר המוקדש אינו בכלל זה, ואין צריך איפוא לפסוק! ומוסיפים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח,\u0006 אין זו שאלה, \u0005ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003קדשי בדק הבית לא היו בכלל\u0004 חיוב \u0003העמדה והערכה.\u0004 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי אף \u0003קדשי בדק הבית\u0004 \u0003היו\u0004 בכלל זה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע נצרך הכתוב?","\u0003אמר ר' מני בר פטיש משום\u0004 \u0005[בשם]\u0006 \u0005ר' ינאי:\u0006 \u0003הכא\u0004 \u0005[כאן,\u0006 במשנתנו\u0005]\u0006 מדובר \u0003במקדיש\u0004 את \u0003בהמתו לבדק הבית, חוץ מגיזותיה,\u0004 שאותן שייר לעצמו. ומעתה \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003ליגזוז וליתיב ליה\u0004 \u0005[שיגזוז\u0006 את הצמר, שלא התקדש, \u0005ויתן לו\u0006 לכהן\u0005],\u0006 לכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"צאנך\"\u0004 — \u0003ולא צאן של הקדש.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבאופן כזה מדברת משנתנו, מעתה אפשר לומר שהיא מדברת ב\u0003קדשי מזבח נמי\u0004 \u0005[גם כן],\u0006 שהקדישם חוץ מגיזתם! ומשיבים: אין לומר כן בקדשי מזבח, משום שאסור לגזוז אותם, אף כשלא הוקדש צמרם, משום שעל ידי הגזיזה \u0003כחשי\u0004 \u0005[נכחשים,\u0006 מרזים ונחלשים\u0005]\u0006 הצאן, ונמצא שהוא מפסיד את הקדשים.","ותוהים: אם כן אמור אף ב\u0003קדשי בדק הבית\u0004 ששייר לעצמו את צמרם, שיהו אלה אסורים בגזיזה, \u0003נמי\u0004 \u0005[גם כן],\u0006 ומשום \u0003ש\u0004\u0003כחשי\u0004 \u0005[נכחשים]\u0006 בכך, ואף בהם הדבר אסור! ומשיבים: מדובר במשנתנו ש\u0003אמר\u0004 בהקדשו \u0003שהריהו מקדיש\u0004","\u0003את הצאן\u0004 \u0003חוץ מגיזה וכחישה\u0004 (מה שיחסר בבהמה כתוצאה מהכחשתה). ומקשים על כך: אם כך, אפשר להעמיד את משנתנו ב\u0003קדשי מזבח נמי\u0004 \u0005[גם כן],\u0006 ובאופן זה ש\u0003אמר \"חוץ מגיזה וכחישה\"!\u0004 ומשיבים: בקדשי המזבח אי אפשר לומר כן, כי \u0003אפילו\u0004 אם \u0003הכי\u0004 \u0005[כך]\u0006 יאמר בהקדשו, אסור הוא בגיזת הצאן, כי \u0003פשטה קדושה בכולה.\u0004","\u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר]\u0006 סברה זו? שכך \u0003אמר ר' יוסי: והלא במוקדשין\u0004 למזבח, אפילו \u0003האומר \"רגלה של\u0004 בהמה \u0003זו\u0004 מוקדשת לקרבן \u0003עולה\"\u0004 — הבהמה \u0003כולה\u0004 נעשית \u0003עולה. ואפילו לר' מאיר\u0004 ש\u0003אמר\u0004 כי \u0003אין\u0004 הבהמה \u0003כולה\u0004 נעשית \u0003עולה, הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 רק בזה ש\u0003אקדיש\u0004 \u0005[שהקדיש]\u0006 \u0003דבר\u0004 (איבר בגוף הבהמה) \u0003שאין הנשמה תלויה בו, אבל\u0004 אם \u0003הקדיש דבר שהנשמה תלויה בו\u0004 — הבהמה כולה \u0003קדשה\u0004 בכך.","\u0003רבא אמר\u0004 הסבר אחר מדוע צריך לפסוק מיוחד ללמד כי גיזת המוקדשים פטורה מראשית הגז: משום שכאן מדובר \u0003במקדיש\u0004 את ה\u0003גיזה עצמה\u0004 לקדשי בדק הבית, ולא במקדיש את הצאן. ומעתה \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003ליגזוז וליפרוק וליתיב ליה\u0004 \u0005[שיגזוז\u0006 את הצמר, \u0005ושיפדה\u0006 אותו, \u0005ושיתן לו\u0006 לכהן את הצמר\u0005]\u0006 ויתן למקדש את דמי הפדיון, לכך","\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"גז צאנך תתן לו\"\u0004 (דברים יח, ד) — מצות ראשית הגז נאמרה רק ב\u0003מי\u0004 (בצאן זה) \u0003שאין\u0004 הוא \u0003מחוסר אלא גזיזה ונתינה. יצא\u0004 (התמעט) מכלל החיוב צאן \u0003זה שמחוסר גזיזה\u0004 ו\u0003פדייה ונתינה.\u0004","ושואלים: \u0003אלא\u0004 לפי הסבר זה של רבא, שנלמד פטור המוקדשים ממקרא זה, מעתה הכתוב \u0003\"צאנך\"\u0004 שמשמעו למעט \u0003למאי אתא\u0004 \u0005[למה בא,\u0006 מה הוא מלמדנו\u0005]?\u0006 ומשיבים: \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003בהמת השותפים חייב בראשית הגז, ור' אלעאי פוטר. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעאי?\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"צאנך\"\u0004 — \u0003ולא של שותפות.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים שאף בהמת השותפים חייבת בראשית הגז, הכתוב \"צאנך\" מה בא למעט? ומשיבים: הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 ממצות ראשית הגז צאן של \u0003שותפות\u0004 יהודי ו\u0003גוי.\u0004 ושואלים לצד האחר: \u0003ור' אלעאי,\u0004 שלמד מכתוב זה לענין פטור צאן השותפים, פטור צאן של \u0003שותפות גוי מנא ליה\u0004 \u0005[מנין לו]?\u0006","ומשיבים: \u0003נפקא ליה מרישא דקרא\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר, \u0005מראשו של הכתוב],\u0006 \u0003\"ראשית דגנך\"\u0004 — \u0003ולא\u0004 כשהוא לך ב\u0003שותפות\u0004 עם \u0003גוי.\u0004","ושואלים לצד האחר: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו את הפטור בשותפות הגוי מן הכתוב \"צאנך\", מדוע לא למדו כן מ\"ראשית דגנך\"? ומשיבים: לדעת חכמים אין ללמוד כן, שכן במלה \u0003\"ראשית\"\u0004 החוזרת ונאמרת בדין ראשית הגז (\"ראשית דגנך תירושך ויצהרך וראשית גז צאנך\") \u0003הפסיק הענין,\u0004 לומר שהן שתי הלכות נפרדות, דין התרומה ודין ראשית הגז, ואין ללמוד מן האמור בתרומה על דין ראשית הגז.","ושבים ושואלים: \u0003ור' אלעאי\u0004 שדרש לדין ראשית הגז מן הכתוב \"ראשית דגנך\" האמור בתרומה, מה הוא משיב לטענתם זו של חכמים? ומשיבים: לדעתו האות \u0003וי\"ו\u0004 שבכתוב \"וראשית צאנך\" \u0003הדר ערביה\u0004 \u0005[חזרה לערבו]\u0006 לעשותו ענין אחד עם התרומה."],["ושואלים: \u0003ורבנן\u0004 \u0005[ו\u0006ל\u0005חכמים],\u0006 אף שהכתוב \"ראשית\" מפסיק בין התרומה לראשית הגז, הרי וי\"ו החיבור שבביטוי \"וראשית הגז\" מחבר ביניהם! ומשיבים: לדעתם אין לומר שבאה הוי\"ו לחבר בין העניינים, שאם לכך נועדה, מוטב היה ש\u0003לא נכתוב רחמנא\u0004 \u0005[שלא תכתוב התורה]\u0006 \u0003לא וי\"ו\u0004 המחבר בין העניינים, \u0003ולא \"ראשית\"\u0004 המפסיקה ביניהם!","ושואלים: \u0003ור' אלעאי\u0004 מה הוא משיב לטענת חכמים? ומשיבים: \u0003איידי דהאי\u0004 \u0005[מתוך שזו,\u0006 ראשית הגז\u0005]\u0006 קדושה ב\u0003קדושת דמים,\u0004 שהריהי חובת ממון בלבד של הישראל לכהן, ואין זו קדושה ממש. \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זו,\u0006 תרומה\u0005]\u0006 קדושה ב\u0003קדושת הגוף,\u0004 שאסורה באכילה למי שאינו כהן. לכך הכתוב \u0003פסיק להו\u0004 \u0005[קטע אותן],\u0006 את ראשית הגז מן התרומה, \u0003והדר ערבי להו\u0004 \u0005[ו\u0006אולם לאחר מכן \u0005חזר\u0006 ו\u0005עירב אותן]\u0006 לדמות את דיניהם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר לשאלה שנשאלה לחכמים מדוע אין למדים ששותפות גוי פוטרת את הבהמה מהשוואתה לדין תרומה: שכן ב\u0003שותפות גוי ב\u0004תבואה, לענין דין \u0003תרומה רבנן חיובי מחייבי\u0004 \u0005[חכמים מחייבים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ישראל וגוי שלקחו\u0004 (שקנו) \u0003שדה בשותפות\u0004 — בכל תבואת שדה זו \u0003טבל\u0004 (פירות החייבים בהפרשת תרומה) \u0003וחולין מעורבים זה בזה,\u0004 אלו \u0003דברי רבי.\u0004 שחלקו של הישראלי בתבואה אינו נפטר מחיוב תרומה בשל שותפותו עם הגוי, ולכך הריהו טבל המעורב עם חולין (חלקו של הגוי בתבואת השדה). \u0003רבן שמעון בן גמליאל אומר:\u0004 אינו כן, אלא חלקו \u0003של ישראל\u0004 בתבואה — \u0003חייב\u0004 בתרומה, \u0003ו\u0004אילו חלקו \u0003של גוי\u0004 בתבואה — \u0003פטור\u0004 מן התרומה.","ו\u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 רבי ורבן שמעון בן גמליאל \u0003אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבן שמעון בן גמליאל \u0005סבור]\u0006 ש\u0003יש ברירה,\u0004 ולכך כאשר כל אחד מן השותפים קיבל את חלקו, הוברר שזה היה חלקו מעיקרו, ומעתה חלקו של הישראל חייב בתרומה, ושל הגוי פטור ממנה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, \u0005סבור]\u0006 ש\u0003אין ברירה,\u0004 שאף אחר שחלקו ביניהם את תבואות השדה, עדיין בחלקו של הישראלי טבל וחולין מעורבים זה בזה. \u0003אבל שותפות\u0004 של \u0003גוי\u0004 — \u0003דברי הכל חייבת\u0004 בתרומה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר בשיטת ר' אלעאי, שאין הוא למד את פטור בהמת השותפים מהכתוב \"צאנך\" ואת פטור בהמת שותפות גוי מהכתוב \"דגנך\", אלא \u0003תרוייהו\u0004 \u0005[שתיהן]\u0006 \u0003ל\u0004דעת \u0003ר' אלעאי מ\"צאנך\" נפקא\u0004 \u0005[יוצאות,\u0006 נלמדות\u0005],\u0006 שהרי","\u0003שותפות\u0004 של \u0003גוי מאי טעמא\u0004 \u0005[מה טעם]\u0006 היא פוטרת מראשית הגז? משום \u0003דלא מייחדא ליה\u0004 \u0005[שאין\u0006 הבהמה \u0005מיוחדת לו\u0006 לישראל\u0005],\u0006 מעתה \u0003בשותפות\u0004 \u0003לישראל נמי\u0004 \u0005[גם כן]\u0006 הריהי פוטרת משום ש\u0003לא מייחדא ליה\u0004 \u0005[אינה מיוחדת לו,\u0006 לאחד מהם\u0005].\u0006 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם אומרים על כך? ומשיבים: אין ללמוד משותפות גוי לשותפות ישראל, שכן ה\u0003גוי לאו בר חיובא\u0004 \u0005[לא בן חיוב]\u0006 \u0003הוא,\u0004 ואילו \u0003ישראל בר חיובא\u0004 \u0005[בן חיוב]\u0006 \u0003הוא.\u0004","למעלה הובאה מחלוקתם של חכמים ור' אלעאי בדין חיוב ראשית הגז בבהמת השותפים, שחכמים מחייבים ור' אלעאי פוטר. וביחס למחלוקת זו \u0003אמר רבא:\u0004 אף שנחלק ר' אלעאי על חכמים בחיוב בהמת השותפים בראשית הגז, \u0003מודה ר' אלעאי\u0004 לחכמים \u0003ב\u0004דין ה\u0003תרומה,\u0004 שתבואת השותפים חייבת בתרומה. \u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 בחיוב התרומה \u0003\"דגנך\"\u0004 שמשמעה — תבואה \u0003דידך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חייבת בתרומה, ואולם של \u0003שותפות\u0004 — \u0003לא\u0004 חייבת בתרומה.","בכל זאת כיון ש\u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"תרומותיכם\"\u0004 (\"אדרוש את תרומותיכם\". יחזקאל כ, מ) להורות שאף תבואת השותפים חייבת בתרומה. ושואלים: \u0003אלא\u0004 מעתה הכתוב \u0003\"דגנך\"\u0004 הנאמר בלשון יחיד, \u0003למה לי\u0004 (מה הוא מלמדנו)? ומשיבים: הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שותפות גוי.\u0004","וכיוצא בדבר לענין חיוב הפרשת \u0003חלה\u0004 מעיסת השותפים, מודה ר' אלעאי ש\u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 בדין החלה \u0003\"ראשית\"\u0004 (\"ראשית עריסותיכם חלה תרימו תרומה\". במדבר טו, כ), \u0003ו\u0004מעתה \u0003איכא למימר\u0004 \u0005[יש\u0006 מקום \u0005לומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה של המלים \u0003\"ראשית\" \"ראשית\" מ\u0004דין \u0003ראשית הגז,\u0004 ונאמר: \u0003מה להלן\u0004 בראשית הגז, צאן של \u0003שותפות\u0004 — \u0003לא\u0004 חייב בנתינת ראשית הגז לכהן, \u0003אף כאן\u0004 בדין הפרשת חלה, עיסת \u0003שותפות\u0004 — \u0003לא\u0004 חייבת בהפרשה. לכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"עריסותיכם\"\u0004 בלשון רבים — לרבות שותפים.","ושואלים: \u0003אלא טעמא דכתיב\u0004 \u0005[הטעם\u0006 לחיוב עיסת השותפים בחלה הוא רק משום \u0005שנאמר]\u0006 \u0003\"עריסותיכם\", הא לאו הכי הוה אמינא\u0004 \u0005[הרי לולא כן הייתי אומר]\u0006 ש\u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003\"ראשית\" \"ראשית\" מראשית הגז?\u0004 אולם \u0003אדרבה\u0004 \u0005[להיפך]\u0006 יש לומר כי \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה \"ראשית\" \"ראשית\" \u0003מתרומה\u0004 שהיא דומה יותר לחלה, וכשם שתבואת השותפים חייבת בתרומה כן עיסת השותפים חייבת בחלה, ואין צורך בדרשת \"עריסותיכם\"!","ומשיבים: \u0003הכי נמי\u0004 \u0005[\u0006אכן \u0005כך הוא גם כן],\u0006 שדין חלה בעיסת השותפים נלמד מתרומה, \u0003אלא \"עריסותיכם\" למה לי?\u0004 ומשיבים: הרי זה בא ללמד ששיעור העיסה החייבת בהפרשת חלה הוא \u0003כדי\u0004 (כשיעור זה) של \u0003עריסותיכם\u0004 (עיסות של בני ישראל) בהיותם במדבר סיני, בזמן שנאמרה מצוה זו. וכיוצא בדבר לענין מצות נתינת","\u0003פאה\u0004 בשדה, מודה ר' אלעאי ש\u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 במצוה זו \u0003\"שדך\"\u0004 (\"ובקוצרכם את קציר ארצכם לא תכלה פאת שדך לקצור\". ויקרא יט, ט), בא להורות כי שדה \u0003דידך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חייבת בפאה, אבל של \u0003שותפות\u0004 — \u0003לא\u0004 חייבת בפאה. ואולם כיון ש\u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ובקצרכם את קציר ארצכם\"\u0004 בלשון רבים, הרי זה בא ללמד שאף שדה שותפים חייבת בפאה. ושואלים: \u0003אלא\u0004 מעתה המלה \u0003\"שדך\"\u0004 הנאמרת בלשון יחיד, \u0003למה לי?\u0004 ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 שדה של \u0003שותפות גוי,\u0004 שאין היא חייבת בפאה.","וכיוצא בדבר לענין \u0003בכורה\u0004 (בכור בהמה טהורה שהריהו קדוש), מודה ר' אלעאי ש\u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 \u0003\"כל הבכור אשר יולד בבקרך ובצאנך\u0004 הזכר תקדיש לה' \" (דברים טו, יט), שמכאן היה מקום ללמוד כי דווקא בכור \u0003דידך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חלה בו קדושה, ואולם בכור של \u0003שותפות\u0004 — \u0003לא\u0004 חלה בו קדושה.","ואולם כיון ש\u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ובכורות בקרכם וצאנכם\"\u0004 (שם יב, ו) בלשון רבים, הרי זה בא ללמד שאף בכור השותפים מתקדש. ושואלים: \u0003אלא\u0004 מעתה הכתוב \u0003\"בקרך וצאנך\",\u0004 הנאמר בלשון יחיד, \u0003למה לי?\u0004 ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 בכור של \u0003שותפות גוי,\u0004 שאין הוא מתקדש.","וכיוצא בדבר לענין מצות \u0003מזוזה,\u0004 מודה ר' אלעאי ש\u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 בה \"וכתבתם על מזוזות \u0003ביתך\"\u0004 (שם ו, ט), שאפשר ללמוד מכאן כי דווקא בבית \u0003דידך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חלה חובת קביעת מזוזה, ואולם בבית של \u0003שותפות\u0004 — \u0003לא\u0004 חלה חובה זו. ואולם כיון ש\u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 עוד במצות מזוזה: \u0003\"למען ירבו ימיכם וימי בניכם\"\u0004 (שם יא, כא) בלשון רבים, הרי זה בא ללמד שאף בית השותפים חייב במזוזה. \u0003ו\u0004שואלים: \u0003אלא\u0004 מעתה הכתוב \u0003\"ביתך\"\u0004 הנאמר בלשון יחיד, \u0003למאי אתא\u0004 \u0005[למה\u0006 הוא \u0005בא]?\u0006 ומשיבים: \u0003לכ\u0004 דרך שדרש \u0003רבה,\u0004 שכן \u0003אמר רבה:\u0004"],["הכתוב \"ביתך\" הריהו נקרא כ\"ביאתך\", ובא להורות שהמזוזה נקבעת על פי \u0003דרך ביאתך\u0004 לביתך. שכפי שדרך אדם שבכניסתו לבית הוא מציב בתחילה את הרגל ש\u0003מן הימין,\u0004 אף המזוזה נקבעת מימינו של הנכנס לבית.","וממשיכים באותו ענין: כיוצא בדבר לענין חובת ה\u0003מעשר\u0004 מודה ר' אלעאי ש\u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 \u0003\"מעשר דגנך\"\u0004 (דברים יב, יז ועוד), והיה מקום לומר כי דווקא בתבואה \u0003דילך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 אתה מחויב במעשר, ואולם התבואה של \u0003שותפות\u0004 — \u0003לא\u0004 חייבת במעשר. לכך \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"מעשרותיכם\"\u0004 (במדבר יח, כח ועוד), בלשון רבים, להורות כי אף תבואת השותפים חייבת במעשרות. ושואלים: \u0003אלא\u0004 מעתה, הכתוב \u0003\"מעשר דגנך\"\u0004 הנאמר בלשון יחיד \u0003למאי אתא\u0004 \u0005[למה בא,\u0006 מה הוא מלמדנו\u0005]?\u0006 ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שותפות\u0004 של \u0003גוי.\u0004","וכיוצא בדבר לענין \u0003מתנות\u0004 כהונה (זרוע, לחיים וקיבה), מודה ר' אלעאי ש\u0003אף על גב דכתב רחמנא\u0004 \u0005[אף על פי שאמרה התורה]\u0006 \"וזה יהיה משפט הכהנים מאת העם מאת זובחי הזבח אם שור אם שה\u0003ונתן לכהן\u0004 הזרוע והלחיים והקיבה\".","דברים יח, ג), ובא הכתוב \u0003\"ונתן\"\u0004 בלשון יחיד, ו\u0003איכא למימר\u0004 \u0005[יש\u0006 מקום \u0005לומר]\u0006 כי \u0003יליף\u0004 \u0005[למד]\u0006 גזירה שווה של המלים השוות \u0003\"נתינה\"\u0004 האמורה במתנות כהונה מ\u0003\"נתינה\" מראשית הגז\u0004 (\"וראשית גז צאנך תתן לו\". שם, ד). ונלמד כי \u0003מה להלן\u0004 (בראשית הגז) צאן \u0003של\u0004 \u0003שותפות\u0004 — \u0003לא\u0004 חייב בנתינה לכהן (כדעת ר' אלעאי הנזכרת בעמוד הקודם), \u0003אף כאן\u0004 בדין מתנות כהונה, בהמה של \u0003שותפות\u0004 — \u0003לא\u0004 חייבת בנתינת מתנות. לכך \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 בדין מתנות כהונה \u0003\"מאת זובחי הזבח\"\u0004 בלשון רבים, ללמד שגם בהמת שותפים חייבת במתנות. ושואלים: \u0003אלא\u0004","\u0003טעמא\u0004 \u0005[הטעם]\u0006 שבהמת השותפים חייבת במתנות הוא רק משום \u0003דכתב רחמנא\u0004 \u0005[שאמרה התורה]\u0006 \u0003\"מאת זובחי הזבח\", הא לאו הכי, הוה אמינא\u0004 \u0005[הרי לולי כן, הייתי אומר]:\u0006 \u0003לילף\u0004 \u0005[שילמד]\u0006 דין מתנות כהונה בבהמת השותפים \u0003מ\u0004דין צאן שותפים ב\u0003ראשית הגז,\u0004 שפטור? ואולם \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003נילף\u0004 \u0005[שילמד]\u0006 דין מתנות כהונה בבהמת השותפים \u0003מ\u0004דין תבואה השותפים ב\u0003תרומה,\u0004 שחייבת בהפרשה, ואין צורך בדרשה מיוחדת ללמדנו כן!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך הוא גם כן]\u0006 ובאמת למדים דין מתנות כהונה מדין תרומה. ואם כן \u0003\"מאת זובחי הזבח\" למה לי\u0004 (מה בא ללמדנו)? \u0003לכ\u0004 דרך שאמר \u0003רבא,\u0004 שכן \u0003אמר רבא: הדין\u0004 (התדיינותו, תביעתו) של הכהן לקבל מתנות כהונה הינה \u0003עם הטבח,\u0004 עם זה ששחט את הבהמה, ולא עם הקונה אותה.","וממשיכים באותו אופן, כיוצא בדבר לענין חובת נתינת \u0003בכורים, אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006 בדין הבכורים \"ולקחת מראשית כל פרי האדמה אשר תביא מארצך\" (דברים כו, ב), ויש בלשון \u0003\"ארצך\"\u0004 האמור בלשון יחיד ללמד כי דווקא שדה שהיא \u0003דידך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חייבת בהבאת ביכורים, ואולם שדה שהיא של \u0003שותפות\u0004 — \u0003לא\u0004 חייבת בביכורים.","לכך \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"בכורי כל אשר (בארצך) [בארצם]\u0004 אשר יביאו לה' לך יהיה\" (במדבר יח, יג), בלשון רבים, להורות כי אף שדה השותפים חייבת בביכורים. ושואלים: \u0003אלא\u0004 מעתה שאף שדה השותפים חייבת בביכורים, הכתוב \u0003\"ארצך\"\u0004 האמור בלשון יחיד, \u0003למה לי\u0004 (מה הוא מלמדנו)? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חוצה לארץ,\u0004 שאין מצות ביכורים נוהגת בפירותיה.","ועוד: כיוצא בדבר לענין מצות \u0003ציצית, אף על גב דכתב רחמנא\u0004 \u0005[אף על פי שאמרה התורה]\u0006 \"גדילים תעשה לך על ארבע כנפות כסותך אשר תכסה בה\" (דברים כב, יב), ובכתוב \u0003\"כסותך\"\u0004 האמור בלשון יחיד יש ללמד כי דווקא בגד שהוא \u0003דידך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חייב בציצית, ואולם בגד של \u0003שותפות\u0004 — \u0003לא\u0004 חייב בציצית.","לכך \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \"ועשו להם ציצית \u0003על כנפי בגדיהם לדורותם\u0004 ונתנו על ציצית הכנף פתיל תכלת\" (במדבר טו, לח), בלשון רבים, להורות שאף בגד השותפים חייב בציצית. \u0003ו\u0004שואלים: \u0003אלא\u0004 מעתה שאף בגד שותפים חייב בציצית, הכתוב \u0003\"כסותך\"\u0004 האמור בלשון יחיד, \u0003למה לי\u0004 (מה בא ללמדנו)? ומשיבים: \u0003לכ\u0004 דרך שדרש \u0003רב יהודה,\u0004 שכן \u0003אמר רב יהודה: טלית שאולה\u0004 — \u0003פטורה מן הציצית כל שלשים יום\u0004 ראשונים של שאילה.","ועוד כיוצא בדבר לענין מצות עשיית \u0003מעקה\u0004 לגג הבית, ש\u0003אף על גב דכתב רחמנא\u0004 \u0005[אף על פי שאמרה התורה]\u0006 \"כי תבנה בית חדש ועשית מעקה לגגך ולא תשים דמים בביתך כי יפול הנופל ממנו\" (דברים כב, ח), ובכתוב \u0003\"לגגך\"\u0004 שנאמר בלשון יחיד יש ללמד כי דווקא בית \u0003דידך\u0004 \u0005[שלך]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 חייב בעשיית מעקה, ואולם בית של \u0003שותפות\u0004 — \u0003לא\u0004 חייב בעשיית מעקה.","לכך \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"כי יפול הנופל ממנו\"\u0004 — להורות כי כל בית שעלול אדם ליפול מגגו, ובכלל זה של שותפים, חייב במעקה. ושואלים: \u0003אלא\u0004 עתה שלמדנו שאף בית השותפים חייב במעקה, הכתוב \u0003\"גגך\"\u0004 האמור בלשון יחיד, \u0003למאי אתא\u0004 \u0005[למה בא,\u0006 מה הוא מלמדנו\u0005]?\u0006 ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003בתי כנסיות ובתי מדרשות\u0004 שאינם בכלל חיוב זה. ונמצינו למדים, לדעת רבא כי בכל אלה ההלכות, מודה ר' אלעאי שיש בהן חיוב אף בשל שותפים.","למעלה הובאו דברי רבא, ולשיטתו אף ר' אלעאי הסבור שצאן של שותפות פטור מראשית הגז, מכל מקום הריהו מודה בעשרה חיובים אחרים (הפרשת תרומה, וחלה, ופאה, קדושת בכור, קביעת מזוזה, הנזכרים בעמוד הקודם. וכן בהפרשת מעשר, ונתינת מתנות כהונה, הבאת ביכורים, הטלת ציצית בבגד, ועשיית מעקה לגג הבית, בעמוד זה) שבכל אלה חייבים אף בדבר של שותפות. ובענין זה \u0003אמר רב ביבי בר אביי\u0004 כי \u0003ליתנהו להני כללי\u0004 \u0005[אין קיום לכללים הללו,\u0006 שאמרם רבא כי מודה בהם ר' אלעאי\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא מפורשת\u0005]\u0006 בדין \u0003בהמת השותפין,\u0004 שלדעת חכמים הריהי \u0003חייבת בבכורה, ו\u0004אילו \u0003ר' אלעאי פוטרה\u0004 מן הבכורה. הרי שאין ר' אלעאי מודה לחכמים בענין זה.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעאי\u0004 הפוטר מבכורה את בהמת השותפים? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ובכורות \u0003בקרך וצאנך\"\u0004 (דברים יב, יז) בלשון יחיד, להורות כי רק בהמתו של יחיד מתקדשת בקדושת בכור, ולא של השותפים. ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 גם \"ובכורות \u0003בקרכם וצאנכם\"\u0004 (שם יב, ו) בלשון רבים, ויש ללמוד מכאן שאף בהמת השותפים מתקדשת בבכורה! ומשיבים: לשון רבים זו באה רק כדי ללמדנו \u0003דכולהו\u0004 \u0005[ש\u0006הבהמות של \u0005כל]\u0006 \u0003ישראל\u0004 מתקדשות בבכורה, ואולם אין המדובר אלא בבהמתו של אדם יחיד, ולא בשל השותפים. וכדרך שאמר רב ביבי בר אביי כן","\u0003אמר רב חנינא מסורא\u0004 כי \u0003ליתנהו להני כללי\u0004 \u0005[אין קיום לאלה הכללים\u0006 שאמרם רבא\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינה של \u0003בהמת השותפין\u0004 שלדעת חכמים הריהי \u0003חייבת במתנות\u0004 כהונה, \u0003ו\u0004אילו \u0003ר' אלעאי פוטר\u0004 אותה ממתנות כהונה. הרי איפוא שאין ר' אלעאי מודה לחכמים בענין זה! ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ר' אלעאי הפוטר את בהמת השותפים מן המתנות? שכן הוא \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה של המלים \u0003\"נתינה\"\u0004 (האמורה במתנות כהונה, \"ונתן לכהן הזרוע והלחיים והקיבה\". דברים יח, ג) \u0003\"נתינה\" מראשית הגז\u0004 (\"וראשית גז צאנך תתן לו\". שם, ד). \u0003מה להלן\u0004 (בראשית הגז) צאן של \u0003שותפות\u0004 — \u0003לא\u0004 חייב בנתינה לכהן, וכשיטת ר' אלעאי, \u0003אף כאן\u0004 (בזרוע לחיים וקיבה) בהמה של \u0003שותפות\u0004 — \u0003לא\u0004 חייבת בנתינת מתנות לכהן.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר, כדברי רבא, שר' אלעאי \u0003בתרומה מיחייב\u0004 \u0005[מחייב]\u0006 בתבואה של שותפות — במקום גזירה שווה \"נתינה\" \"נתינה\" מראשית הגז, שממנה למדנו לחייב את בהמת השותפים, \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003\"נתינה\" \"נתינה\" מתרומה\u0004 (שנאמר בה \"ראשית דגנך ותירושך ויצהרך... תתן לו\". שם, ד), ונלמד ממנה לפטור את בהמת השותפים מנתינה. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בתרומה נמי\u0004 \u0005[גם כן]\u0006 \u0003פוטר\u0004 ר' אלעאי את תבואת השותפים, ושלא כדברי רבא.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כך הוא, שישנה גזירה שווה \"נתינה\" (במתנות כהונה) \"נתינה\" (בתרומה), מעתה נוסיף ונאמר: \u0003מה תרומה, בארץ\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 נוהגת, ואילו \u0003בחוצה לארץ\u0004 — \u0003לא\u0004 נוהגת, מעתה \u0003אף מתנות\u0004 כהונה, \u0003בארץ\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נוהגות, ואילו \u0003בחוצה לארץ\u0004 — \u0003לא\u0004 נוהגות! \u0003אמר ר' יוסי מנהרביל: אין\u0004 \u0005[כן]\u0006 הוא באמת, שאין מתנות כהונה נוהגות בחוצה לארץ. \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעאי אומר: מתנות\u0004 כהונה \u0003אין נוהגין אלא בארץ,\u0004 ולא בחוצה לארץ. \u0003וכן היה ר' אלעאי אומר: ראשית הגז אין נוהג אלא בארץ,\u0004 ולא בחוצה לארץ.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעאי? אמר רבא\u0004 בהסבר הדברים: ר' אלעאי \u0003יליף\u0004 \u0005[לומד]\u0006 גזירה שווה של המלים \u0003\"נתינה\"\u0004 האמורה בראשית הגז, ו\u0003\"נתינה\" מ\u0004הנאמר \u0003ב\u0004\u0003תרומה, מה תרומה, בארץ\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נוהגת, ואילו \u0003בחוצה לארץ\u0004 — \u0003לא, אף ראשית הגז, בארץ\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נוהג, ואילו \u0003בחוצה לארץ\u0004 — \u0003לא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: אם אנו עושים השוואה זו, \u0003אי\u0004 \u0005[אם]\u0006 כן יש מקום להוסיף ולומר כי \u0003מה תרומה טובלת\u0004 את כל התבואה שבה היא נמצאת, שאם לא מפריש אותה — השאר הוא טבל ואסור. \u0003אף ראשית הגז,\u0004 אם לא ניתנה לכהן תהיה \u0003טובלת\u0004 את כל הגיזה לאוסרה בשימוש! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בתשובה: אין לומר כן, כיון ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וראשית גז צאנך תתן לו\"\u0004 \u0003—\u0004 \u0003אין לך\u0004 (לכהן) \u0003בו אלא מ\u0004זמן שהופרשה \u0003ראשיתו\u0004 של הגז \u0003ואילך,\u0004 ואולם קודם לכן אין ראשית הגיזה שייכת לכהן, ואין טעם שתאסור את כל הגיזה.","חזר ושאל אביי את רבא: \u0003אי\u0004 \u0005[אם]\u0006 כדבריך, שיש גזירה שווה בין ראשית הגז לתרומה, מעתה נאמר כי \u0003מה תרומה חייבים עליה\u0004 אלה שאינם כהנים שאכלוה, \u0003מיתה\u0004 אם אכלוה במזיד, \u0003ו\u0004תשלום \u0003חומש\u0004 (חמישית, הנוסף על תשלום הקרן) לאלה שאכלוה בשוגג, \u0003אף\u0004 ב\u0003ראשית הגז\u0004 נאמר ש\u0003חייבים עליו מיתה וחומש!\u0004","השיב לו רבא: אין לומר כן כיון ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי אכילת תרומה של הזר: \u0003\"ומתו בו\u0004 כי יחללוהו... ואיש כי יאכל קדש בשגגה \u0003ויסף\u0004 חמישיתו \u0003עליו\u0004 ונתן לכהן את הקודש\" (ויקרא כב, ט— יד), והרי אלה לשונות מיעוטים: \u0003\"עליו\"\u0004 — דווקא על אכילת תרומה בשוגג נענשים בתשלום קרן ובחומש, \u0003ולא על ראשית הגז, \"בו\"\u0004 — דווקא על אכילת תרומה במזיד נענשים במיתה, \u0003ולא בראשית הגז.\u0004","ועוד שאל אביי את רבא, בדומה לכך: \u0003אי\u0004 \u0005[אם]\u0006 כדבריך, שישנה גזירה שווה בין ראשית הגז לתרומה, מעתה נאמר כי \u0003מה\u0004 הפרשת \u0003תרומה\u0004 באה הפרשת מעשר \u0003ראשון ושני אחריה, אף ראשית הגז\u0004 יהיו מעשר \u0003ראשון ושני\u0004 באים \u0003אחריה!\u0004 אמר לו בתשובה: אין לומר כן, שכבר \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין ראשית הגז: \u0003\"ראשית\"\u0004 — \u0003אין לך בו אלא\u0004 נתינת \u0003ראשית\u0004 הגז \u0003בלבד.\u0004","ועוד הוסיף ושאל בדומה לכך: \u0003אי\u0004 \u0005[אם]\u0006 כדבריך הוא שישנה גזירה שווה בין ראשית הגז לתרומה, מעתה נאמר כי \u0003מה תרומה, מ\u0004יבול ה\u0003חדש\u0004 של שנה זו \u0003על\u0004 היבול \u0003הישן\u0004 של שנה שעברה — \u0003לא\u0004 מפרישים. \u0003אף ראשית הגז מ\u0004גז \u0003חדש\u0004 של שנה זו \u0003על\u0004 הגז \u0003הישן\u0004 של שנה שעברה — \u0003לא\u0004 נותנים! השיב לו רבא: \u0003אין\u0004 \u0005[כן],\u0006 כך הוא,","\u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינו של מי ש\u0003היו לו שתי רחלות, גזז\u0004 את שתיהן \u0003והניח\u0004 את צמר הגיזה אצלו, שלא נתנו לכהן. וחזר בשנה הבאה ו\u0003גזז\u0004 אותן \u0003ו\u0004שוב \u0003הניח\u0004 את הגיזה אצלו, שלא נתנה לכהן. וכן עשה \u0003שנים ושלשה שנים\u0004 עד שהצטברה אצלו גיזה מאותן שתי רחלות כגיזתן של חמש רחלות (שהוא השיעור המחייב מתן ראשית הגז) — \u0003אין\u0004 הגיזות \u0003מצטרפות\u0004 לחיוב נתינה לכהן, שכן לא היתה גזיזתן מחמש רחלות אלא משתים בלבד. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אילו אירע מקרה דומה, שגזז והניח אצלו, ואולם לא היתה זו גיזתן של שתי רחלות אלא \u0003של\u0004 \u0003חמש\u0004 רחלות, ובאופן שגזז שתים מהן בשנה זו ושלוש מהן בשנה האחרת — היו אלה \u0003מצטרפות. ו\u0004","אולם על כך יש להקשות שכן \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא אחרת\u0005]\u0006 האומרת שאף באופן זה של גיזת חמש רחלות \u0003אין\u0004 הגיזות \u0003מצטרפות,\u0004 והרי לפנינו סתירה בין ברייתות, \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האומרת שאין הגיזות מצטרפות, הריהי כשיטת \u0003ר' אלעאי,\u0004 הסבור שיש לגזור גזירה שווה בין ראשית הגז לתרומה, ולכך לדעתו אין מצרפים גיזה ישנה לגיזה חדשה. \u0003ו\u0004אילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 הריהי כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שאינם סבורים כר' אילעאי לגזור גזירה שווה בין ראשית הגז לתרומה, ולדעתם בתרומה אמנם אין תורמים משנה זו לשנה אחרת, ואילו בראשית הגז מצטרפות גיזות של שנים שונות.","חזר ושאל עוד, באותו אופן: \u0003אי\u0004 \u0005[אם]\u0006 כדבריך שגוזר ר' אלעאי גזירה שווה בין ראשית הגז לתרומה, מעתה נאמר גם כי \u0003מה תרומה,\u0004 מה ש\u0003גדל בחיוב\u0004 (בבעלות ישראל) — \u0003חייב,\u0004 ומה ש\u0003גדל בפטור\u0004 (בבעלות הגוי) — הריהו \u0003פטור.\u0004 שכך הוא הדין בישראל שקנה שדה מידי הגוי, והיתה בה תבואה שהחלה לגדול אצל הגוי (בפטור), ונוספה בה תבואה שגדלה אצל הישראלי (בחיוב). מעתה \u0003אף\u0004 ב\u0003ראשית הגז נמי\u0004 \u0005[גם כן]\u0006 נאמר שהצמר ש\u0003גדל בחיוב\u0004 — הריהו \u0003חייב,\u0004 ואילו זה שגדל \u0003בפטור\u0004 — הריהו \u0003פטור!\u0004","\u0003וגבי\u0004 \u0005[ואצל]\u0006 \u0003תרומה מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הדין? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ישראל שלקח\u0004 (שקנה) \u0003שדה בסוריא מגוי,\u0004 אם קנה אותה \u0003עד שלא\u0004 (בטרם) \u0003הביאה שליש\u0004 משיעור גידולה — הריהו \u0003חייב\u0004 בתרומות ומעשרות, ואם קנה אותה \u0003משהביאה\u0004 כבר \u0003שליש\u0004 גידולה, \u0003ר' עקיבא מחייב\u0004 בהפרשת תרומות ומעשרות \u0003בתוספת\u0004 (בחלק הנוסף לאחר שנקנה על ידי הישראלי), \u0003וחכמים פוטרין.\u0004","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 כי \u0005כך גם כן],\u0006 גם לגבי ראשית הגז, שלדעת ר' אלעאי הצמר הגדל בפטור הריהו פטור, \u0003ו\u0004אולם \u0003התנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]\u0006 כי \u0003הלוקח\u0004 (הקונה) את \u0003גז צאן גוי\u0004 הריהו \u0003פטור מראשית הגז,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם קנה את \u0003צאנו\u0004 של הגוי כאשר הרחל עומדת \u0003לגזוז\u0004 — הריהו \u0003חייב!\u0004"],["ומשיבים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' אלעאי,\u0004 שלשיטתו גם בראשית הגז הריהו חייב בנתינה לכהן.","ועוד שב ושאל: \u0003אי\u0004 \u0005[אם]\u0006 כדבריך שר' אלעאי גוזר גזירה שווה בין ראשית הגז לתרומה, מעתה יש מקום לומר: \u0003מה תרומה,\u0004 יבול הבא \u0003מ\u0004צמח של \u0003מין\u0004 זה \u0003על\u0004 יבול הבא מצמח \u0003שאינו מינו\u0004 — \u0003לא\u0004 יתן. מעתה \u0003אף\u0004 ב\u0003ראשית הגז\u0004 נאמר כי צמר הבא \u0003ממין\u0004 זה של צאן \u0003על\u0004 צמר הבא מצאן \u0003שאינו מינו\u0004 — \u0003לא\u0004 יתן!","\u0003וגבי\u0004 \u0005[ואצל]\u0006 \u0003תרומה מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הדין? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינו של מי ש\u0003היו לו שני מיני תאנים, שחורות ולבנות, וכן\u0004 מי שהיו לו \u0003שני מיני חטין\u0004 — \u0003אין תורמים ומעשרים מזה על זה. ר' יצחק אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעאי: בית שמאי אומרים\u0004 כי \u0003אין תורמין\u0004 מתאנה או מחיטה זו על התאנה או על החיטה האחרת, \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 ש\u0003תורמין\u0004 מתאנה זו על התאנה האחרת, וכן מחיטה זו על החיטה האחרת, שלדעתם כל אלה מין אחד הן. ואולם הכל מודים שאין תורמים ומעשרים ממין זה על מין אחר. ואם כן \u0003אף\u0004 ב\u0003ראשית הגז\u0004 שנאמר שצמר הבא \u0003ממין\u0004 צאן זה \u0003על\u0004 צמר שבא מצאן \u0003שאינו מינו\u0004 — \u0003לא\u0004 יתן!","ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 הוא באמת, \u0003והתנן\u0004 \u0005[וכך שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003היו לו שני מינים\u0004 של צאן, \u0003שחופות\u0004 (לא שחורות ולא לבנות) \u0003ולבנות, מכר לו\u0004 לחבירו את ה\u0003שחופות אבל לא\u0004 את ה\u0003לבנות,\u0004 שהשאירן המוכר לעצמו — \u0003זה\u0004 המוכר \u0003נותן\u0004 מגיזתו מהצאן ששייר \u0003לעצמו,\u0004 \u0003וזה\u0004 הלוקח \u0003נותן\u0004 מגיזת הצאן שקיבל \u0003לעצמו.\u0004 והרי שאין נותנים מצמר של מין זה על צמר של מין אחר.","ותוהים על כך: \u0003אלא מעתה,\u0004 \u0003סיפא דקתני\u0004 \u0005[סוף\u0006 המשנה \u0005ששנינו\u0006 בה\u0005],\u0006 שאם מכר \u0003זכרים אבל לא נקבות\u0004 — \u0003זה נותן לעצמו וזה נותן לעצמו, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שנותנים מזה ומזה \u0003משום דתרי מיני נינהו\u0004 \u0005[ששני מינים הם]?!\u0006","\u0003אלא\u0004 הטעם הוא ש\u0003עצה טובה קא משמע לן\u0004 \u0005[הוא\u0006 התנא \u0005משמיע לנו],\u0006 שמאחר וגיזת הנקבות רכה בעוד שגיזת הזכרים היא קשה, לכך טוב למוכר שלא יתן לכהן מן הגיזה הרכה שאצלו הן על הנקבות שאצלו והן על הזכרים שמכר, אלא מוטב לו שיקנה מהקונה גיזת זכרים כשיעור שצריך לתת לכהן על הזכרים, ובאופן זה יצא \u0003דליתיב ליה מהאי דרכיך ומהאי דאשון\u0004 \u0005[שיתן לו\u0006 לכהן במתנתו \u0005מזה שהוא רך,\u0006 כגיזת הנקבות, \u0005וממה שקשה,\u0006 כגיזת הזכרים\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 לענין שחופות ולבנות, אין זו אלא \u0003עצה טובה קא משמע לן\u0004 \u0005[הוא\u0006 התנא \u0005משמיע לנו],\u0006 שמוטב למוכר שלא יתן כל מתנתו לכהן מן הלבנות שתחת ידו, ואף על השחופות, אלא יקנה מהקונה מגיזת השחופות בשיעור הנתינה לכהן, ובאופן זה \u0003דליתיב להו מתרוייהו\u0004 \u0005[שיתן לו\u0006 לכהן \u0005משניהם]!\u0006 ואולם לדעת המשנה מפרישים מגיזת צאן ממין זה על מין אחר, ומעתה חוזרת השאלה לשיטת ר' אלעאי הגוזר גזירה שווה מתרומה, מדוע לא נאמר אף בראשית הגז שאין מפרישים ממין על שאינו מינו!","ומשיבים: אכן לדעת ר' אילעאי אין מפרישים מגיזת מין על גיזת מין אחר, ואין להקשות עליו ממשנתנו, שכן \u0003הא אוקימנא למתניתין\u0004 \u0005[הרי כבר העמדנו את משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' אלעאי.\u0004","ועוד שבים ושואלים באופן דומה: \u0003אי\u0004 \u0005[אם]\u0006 כדבריך שר' אלעאי גוזר גזירה שווה מתרומה לראשית הגז, מעתה יש מקום לומר \u0003כי\u0004 \u0003מה תרומה, בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה התרומה נתינה \u0003ראשית,\u0004 שניתנת היא באופן \u0003ששיריה\u0004 (שמה שנשאר ביבול, לאחר שהופרשה ממנו התרומה) \u0003ניכרין\u0004 (ולכך העושה את כל \u0003גורנו תרומה\u0004 — אין זו תרומה), \u0003אף\u0004 ב\u0003ראשית הגז\u0004 נאמר שצריכה זו להיות \u0003נתינה\u0004 \u0003ששיריה ניכרין!\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 כך הוא דין ראשית הגז,","\u0003והתנן\u0004 \u0005[וכן שנינו]:\u0006 \u0003האומר \"כל גרני תרומה וכל עיסתי חלה\"\u0004 — \u0003לא אמר כלום, הא\u0004 \u0005[הרי]\u0006 נדייק מכאן, שדווקא באלה אין הפרשתו נחשבת, ואולם זה שאומר \u0003\"כל גזיי ראשית\"\u0004 — \u0003דבריו קיימין. ו\u0004אולם \u0003תניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 האומרת שהמפריש כל גיזת צאנו — \u0003לא אמר כלום.\u0004","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003הא\u0004 \u0005[\u0006משנה \u0005זו]\u0006 האומרת שאין זו הפרשה ראויה, הריהי כשיטת \u0003ר' אלעאי\u0004 הגוזר גזירה שווה לראשית הגז מן התרומה. \u0003ו\u0004אילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 ששנינו בה שהיא הפרשה ראויה, הריהי כ\u0003רבנן\u0004 \u0005[חכמים]\u0006 שאינם גוזרים גזירה שווה מתרומה לראשית הגז. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003אמר רב נחמן בר יצחק: האידנא נהוג עלמא כהני תלת סבי\u0004 \u0005[בימינו הכל נוהגים כ\u0006דעת \u0005שלושה זקנים,\u0006 חכמים \u0005אלה]\u0006 להקל. נוהגים \u0003כ\u0004דעת \u0003ר' אלעאי בראשית הגז, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אלעאי אומר\u0004 כי \u0003ראשית הגז אינו נוהג אלא בארץ. ו\u0004כן הכל נוהגים","\u0003כ\u0004דעת \u0003ר' יהודה בן בתירה\u0004 לענין \u0003דברי תורה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה בן בתירה אומר\u0004 כי \u0003אין דברי תורה מקבלין טומאה,\u0004 ולכן גם זה שהוא נטמא כבעל קרי ולא טבל, מותר בלימוד תורה.","\u0003ו\u0004כן הכל נוהגים \u0003כ\u0004דעת \u0003ר' יאשיה בכלאים, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יאשיה אומר\u0004 כי \u0003לעולם אין חייב\u0004 משום איסור כלאי הכרם אלא \u0003עד שיזרע חטה ושעורה וחרצן\u0004 (גרעין הענב) \u0003במפולת יד\u0004 (בתנועה אחת של זריעה).","שנינו במשנה כי יש צד \u0003חומר\u0004 (חומרה) \u0003ב\u0004מצות נתינת \u0003זרוע\u0004 לחיים וקיבה ממצות נתינת ראשית הגז, שכן מתנות הכהונה נוהגות הן בבקר והן בצאן, ואילו ראשית הגז נוהגת רק ברחלות. וכן שמתנות כהונה נוהגות הן במספר מרובה של בהמות שנשחטו והן במספר מועט ואפילו בבהמה אחת שנשחטה, ואילו ראשית הגז נוהגת רק ברחלות מרובות שנגזזו. ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 התנא צד \u0003חומר\u0004 שיש \u0003בראשית הגז\u0004 ואין במתנות כהונה, \u0003ש\u0004ראשית הגז \u0003נוהג\u0004 אף \u0003ב\u0004רחלות שהן \u0003טרפות\u0004 (העומדות למות בשל פגיעה או מחלה), \u0003מה שאין כן במתנות\u0004 כהונה שאינן ניתנות מבהמת טריפה שנשחטה!","\u0003אמר רבינא\u0004 בתשובה: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו,\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' שמעון היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון פוטר את\u0004 הרחלות \u0003הטרפות מראשית הגז. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון?\u0004 שכן \u0003יליף\u0004 \u0005[לומד]\u0006 הוא גזירה שווה של המלים \u0003\"נתינה\"\u0004 האמורה בראשית הגז (\"וראשית גז צאנך תתן לו\". דברים יח, ד) ו\u0003\"נתינה\" מ\u0004הנאמר ב\u0003מתנות\u0004 (\"ונתן לכהן הזרוע והלחיים והקיבה\". שם, ג). \u0003מה\u0004 ב\u0003מתנות\u0004 כהונה, בהמה \u0003טרפה\u0004 — \u0003לא\u0004 חייבת בנתינה, שכן אמר הכתוב \"ונתן לכהן\" שמשמע הדברים לתת לכהן עצמו, שהוא יאכלם, ואילו הטריפה אסורה באכילה. \u0003אף ראשית הגז נמי\u0004 \u0005[גם כן]\u0006 הרחלה ה\u0003טרפה\u0004 — \u0003לא\u0004 חייבים בנתינת גיזתה.","ושואלים: \u0003ואי יליף\u0004 \u0005[ואם למד]\u0006 ר' שמעון גזירה שווה זו \u0003של\u0004 \u0003\"נתינה\" \"נתינה\" ממתנות\u0004 לראשית הגז, מעתה \u0003לילף\u0004 \u0005[שילמד]\u0006 גם גזירה שווה של המלים \u0003\"נתינה\"\u0004 האמורה בראשית הגז, ו\u0003\"נתינה\" מ\u0004הנאמר ב\u0003תרומה\u0004 (\"ראשית דגנך ותירושך ויצהרך... תתן לו\". שם, ד), ומעתה נאמר: \u0003מה תרומה,\u0004 תבואה \u0003ש\u0004\u0003בארץ\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 היא חייבת בהפרשת תרומה, ואולם תבואה ש\u0003בחוצה לארץ\u0004 — \u0003לא\u0004 חייבת בהפרשה. \u0003אף ראשית הגז נמי\u0004 \u0005[גם כן],\u0006 גיזת צמר ש\u0003בארץ\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חיייבת בראשית הגז, ואילו גיזת צמר ש\u0003בחוצה לארץ\u0004 — \u0003לא\u0004 חייבת בראשית הגז. \u0003אלמה תנן\u0004 \u0005[מפני מה שנינו\u0006 במשנתנו\u0005]\u0006 כי \u0003ראשית הגז נוהג בארץ ובחוצה לארץ?\u0004","\u0003אלא,\u0004 כך צריך לומר: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' שמעון: דיליף\u0004 \u0005[שלומד]\u0006 הוא גזירה שווה של המלים \u0003\"צאן\"\u0004 האמור בראשית הגז (\"וראשית גז צאנך\") ו\u0003\"צאן\" מ\u0004הנאמר במצות \u0003מעשר\u0004 בהמה (שנאמר בה \"וכל מעשר בקר וצאן כל אשר יעבור תחת השבט העשירי יהיה קודש לה' \". ויקרא כז, לב). \u0003מה מעשר\u0004 בהמה, זו שהיא \u0003טרפה\u0004 — \u0003לא\u0004 חייבת במעשר בהמה, \u0003אף ראשית הגז,\u0004 זו שהיא \u0003טרפה\u0004 — \u0003לא\u0004 חייבת בנתינת גיזתה.","ושואלים: \u0003והתם\u0004 \u0005[ושם]\u0006 במעשר בהמה \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שאינו נוהג בטריפה? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"כל אשר יעבור תחת השבט\"\u0004 — דווקא הבהמה הבריאה, שיכולה לעבור בעצמה, \u0003פרט לטרפה שאינה עוברת\u0004 בעצמה תחת השבט, משום שהיא חולה מדי. ושואלים עוד: \u0003ולילף\u0004 \u0005[ושילמד]\u0006 ר' שמעון גזירה שווה מן המלים \u0003\"צאן\"\u0004 האמורה בראשית הגז (\"וראשית גז צאנך\") \u0003ו\u0004\u0003\"צאן\" מ\u0004הנאמר בקדושת \u0003בכור\u0004 (\"כל הבכור אשר יולד בבקרך ובצאנך הזכר תקדיש לה' אלהיך לא תעבוד בבכור שורך ולא תגוז בכור צאנך\". דברים טו, יט). \u0003מה\u0004 קדושת \u0003בכור\u0004 — נוהגת \u0003אפילו\u0004 בבהמה \u0003טרפה, אף ראשית הגז\u0004 — נוהגת \u0003אפילו\u0004 בבהמה \u0003טרפה!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 שראשית הגז מגזירה שווה \u0003ממעשר הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 ולא מדין בכור. \u0003שכן\u0004 דומה דין ראשית הגז לדין מעשר בהמה בדברים רבים, כמפורט: ששניהם נוהגים לא רק בבהמות \u0003זכרים\u0004 אלא גם בנקבות (ואילו הבכור נוהג רק בבהמה ממין זכר); ושניהם אינם נוהגים בבהמות","\u0003טמאין\u0004 (ואילו הבכור נוהג גם בבהמה טמאה, וכגון פטר חמור); ושניהם נוהגים דווקא \u0003ב\u0004בהמות \u0003מרובין\u0004 (מעשר בהמה — בעשר בהמות לפחות, וראשית הגז — בחמש רחלות לפחות (ואילו הבכור נוהג בבהמה יחידה); ושניהם אינם קדושים \u0003מרחם\u0004 (ואילו הבכור קדוש מרחם אמו); ושניהם נוהגים רק בבהמה ולא ב\u0003אדם\u0004 (ואילו קדושת בכור יש גם בבן הבכור באדם, הקדוש ונצרך לפדותו); ועוד","ששניהם נוהגים גם בבעל חיים ה\u0003פשוט\u0004 שאינו בכור (ואילו הבכור נוהג רק בבעל חיים הבכור); ושניהם לא נהגו \u0003לפני הדבור,\u0004 לפני מתן תורה (ואילו קדושת הבכור נהגה עוד במצרים לפני מתן תורה).","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מבכור הוה ליה למילף\u0004 \u0005[היה לו\u0006 לר' שמעון \u0005ללמוד]\u0006 גזירה שווה לענין ראשית הגז, ולא ממעשר בהמה, ומפני הצדדים המשותפים שבין ראשית הגז ובכור: \u0003שכן\u0004 שניהם נוהגים אף בבעל חיים ה\u0003יתום,\u0004 שמתה אמו קודם לידתו (ואילו מעשר בהמה אינו נוהג בבעל חיים שכזה); וכן שניהם נוהגים בבעל חיים \u0003שלקחו\u0004 (שנקנה, ואילו מעשר בהמה אינו נוהג בבהמה שנקנתה); וכן שניהם נוהגים","\u0003ב\u0004בהמה של \u0003שותפות\u0004 (ואילו מעשר בהמה אינו נוהג בבהמת השותפים); וכן נוהגים שניהם בבעל חיים ש\u0003נתנו\u0004 בעליו במתנה לחבירו (ואילו מעשר בהמה אינו נוהג בבהמה שניתנה במתנה); וכן שניהם נוהגים גם שלא \u0003בפני\u0004 הבית, בזמן שאין בית המקדש קיים (ואילו מעשר בהמה אינו נוהג אלא בזמן בית המקדש); וכן שניהם מתנות הניתנות ל\u0003כהן\u0004 (ואילו מעשר בהמה אינו ניתן לכהן, אלא נאכל לבעליו);"],["ועוד: ששניהם אינם מצווים \u0003בקדושה\u0004 (בהקדשתם), שאין צורך להקדיש אותם. שהרי הבכור קדושתו היא מרחם אמו, ואת ראשית הגז אין צורך להקדיש, שהרי אין בה כל קדושה (ואילו את מעשר בהמה הריהו מקדיש בהעברה תחת השבט); \u0003ו\u0004כן בשניהם מותרת ה\u0003מכירה,\u0004 שיכול הכהן למכור את הבכור וכן את ראשית הגז שניתן לו (ואילו מעשר אינו נמכר). \u0003ו\u0004מעתה יש להעדיף את הגזירה השווה שבין ראשית הגז ובכור מהגזירה השווה שבין ראשית הגז ומעשר בהמה, שכן \u0003הנך\u0004 \u0005[אלה]\u0006 הצדדים המשותפים שבין ראשית הגז ובכור הם \u0003נפישין\u0004 \u0005[מרובים]\u0006 מהצדדים המשותפים שבין ראשית הגז ומעשר בהמה!","ומשיבים: בכל זאת עדיפה היא הגזירה שווה שבין ראשית הגז ומעשר בהמה, כי דבר הנוהג בבעל חיים ה\u0003פשוט\u0004 (הרגיל, זה שאינו ולד ראשון לאמו), כראשית הגז, \u0003מ\u0004דבר ה\u0003פשוט\u0004 כמעשר בהמה, \u0003עדיף ליה\u0004 \u0005[לו]\u0006 ללמוד בגזירה שווה.","שנינו במשנתנו כי דין \u0003ראשית הגז אינו נוהג אלא ברחלים\u0004 בלבד. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב חסדא: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 מגזירה שווה של המילים \u0003\"גיזה\" \"גיזה\",\u0004 ומפרט את דבריו, \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בדין ראשית הגז\u0005]\u0006 \"ו \u0003ראשית גז צאנך תתן לו\"\u0004 (דברים יח, ד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם,\u0006 בדברי איוב\u0005]\u0006 \u0003\"ומגז כבשי יתחמם\"\u0004 (איוב לא, יט), \u0003מה\u0004 הגיזה האמורה \u0003להלן\u0004 באיוב, הריהי ב\u0003כבשים, אף\u0004 הגיזה האמורה \u0003כאן\u0004 בראשית הגז, הריהי זו שב\u0003כבשים.\u0004","ושואלים: \u0003ונילף\u0004 \u0005[ושנלמד]\u0006 גזירה שווה של המלים הללו \u0003\"גיזה\"\u0004 (שבראשית הגז) ו\u0003\"גיזה\" מ\u0004הנאמר בדין ה\u0003בכור\u0004 (\"לא תעבוד בבכור שורך ולא תגוז בכור צאנך\", דברים טו, יט). וכשם שבבכור לא רק גיזתו של הכבש אלא אף גיזתו של השור אסורה, כן יהא במצות ראשית הגז! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב \u0003\"לא תעבוד בבכור שורך ולא תגוז בכור צאנך\"\u0004 — \u0003אין לי\u0004 מתוך פסוק זה \u0003אלא\u0004 שבכור \u0003שור\u0004 אסור \u0003בעבודה ו\u0004בכור \u0003צאן\u0004 אסור \u0003בגיזה,\u0004","\u0003מנין ליתן האמור של זה בזה, ואת האמור של זה בזה,\u0004 שבכור השור אסור אף בגיזה ובכור הצאן אסור אף בעבודה? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"לא תעבוד ולא תגוז\",\u0004 בוי\"ו יתירה, שאסורה הגיזה גם בבכור השור. ומעתה נאמר שגם במצות ראשית הגז נכלל אף גיזתו של השור, ולא רק זה של השה בלבד! ומשיבים: אין לומר כן, כיון ש","\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במצות ראשית הגז לכהן \u0003\"תתן לו\"\u0004 — הרי זה מורה שצריכה היא להיות נתינה של ממש לכהן עצמו, באופן שיוכל הכהן ליהנות ממנה במלבושיו, \u0003ולא\u0004 נתינה שאינה מועילה \u0003אלא\u0004 \u0003לשקו.\u0004 ואף גיזת השור אינה ראויה למלבוש אדם, אלא לשק בלבד.","ומקשים: \u0003אלא מעתה\u0004 שטעם הפטור בגיזת השור אינו אלא משום שאין היא ראויה לעשיית בגד לכהן, מעתה ה\u0003נוצה\u0004 (שיער) \u0003של עזים ליחייב\u0004 \u0005[שתתחייב]\u0006 בראשית הגז, שהרי אפשר לעשות ממנה בגד! ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 בחיוב ראשית הגז דבר הבא מן הצאן על ידי מעשה \u0003גיזה, ו\u0004אילו בנוצה של עיזים \u0003ליכא\u0004 \u0005[אין כאן]\u0006 דבר הבא על ידי מעשה גיזה, שאין הנוצה נגזזת אלא נתלשת.","ושואלים על הסבר זה: \u0003מאן\u0004 \u0005[מי]\u0006 החכם ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 שאומר \u0003האי סברא\u0004 \u0005[סברה זו],\u0006 שאין מתחייב בראשית הגז אלא דבר הבא על ידי מעשה של גזיזה? הלא \u0003ר' יוסי\u0004 הוא (כמובא בהמשך הדברים), ו\u0003הא מודי\u0004 \u0005[הרי מודה]\u0006 \u0003ר' יוסי במידי דאורחיה\u0004 \u0005[בדבר שדרכו]\u0006 בהסרה מן הצאן שלא בדרך גזיזה, שאף הוא חייב בראשית הגז. ומעתה, גם נוצה של עיזים, שדרכה בתלישה, תהא חייבת בראשית הגז!","\u0003אלא\u0004 יש לפרש שטעם הדבר שראשית הגז נוהג ברחלות בלבד \u0003כ\u0004דרך ש\u0003אמר ר' יהושע בן לוי\u0004 על הכתוב (הנאמר מייד לאחר מצות נתינת ראשית הגז לכהן) \"כי בו בחר ה' אלהיך מכל שבטיך לעמוד לשרת בשם ה' הוא ובניו כל הימים\" (דברים יח, ה), ולמדים שמן הנאמר \u0003\"לעמוד לשרת\"\u0004 למדים אנו שתהא הגיזה הניתנת לכהן דווקא \u0003דבר הראוי\u0004 לעשות ממנו \u0003לשירות\u0004 במקדש, כתכלת לבגדי כהונה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בהסבר הטעם מדוע מצות ראשית הגז נוהגת רק ברחלות, שכן רק מהן ניתן להפיק צמר שיהא \u0003דבר הראוי לשירות,\u0004 בבגדי הכהנים. ושואלים: \u0003אלא\u0004 מעתה שלמדנו מכאן מקורה של ההלכה שראשית הגז באה דווקא מן הרחלות, גזירה שווה זו","\u0003\"גיזה\" \"גיזה\"\u0004 שהובאה למעלה, \u0003למאי אתא\u0004 \u0005[למה\u0006 היא \u0005באה]?\u0006 ומשיבים: \u0003לכדתנא דבי\u0004 \u0005[לכמו ששנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל. דתנא דבי\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כבשים שצמרן קשה פטורים מראשית הגז, שנאמר \"ומגז כבשי יתחמם\",\u0004 שגיזה היא זו שראויה לחמם, ומאחר וגיזת הצמר הקשה אינה מחממת — אין מצות ראשית הגז נוהגת בה.","ועוד בדיני ראשית הגז, \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 ה\u0003גוזז את\u0004 צמרן של \u0003העזים\u0004 או זה ש\u0003שוטף את הרחלים\u0004 במים, בלי לגזוז את צמרן, ואולם מתוך שטיפתן של הרחלים נתלש מהן צמר — הצמר היוצא מזה ומזה \u0003פטור\u0004 מראשית הגז. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הגוזז את העזים\u0004 — \u0003פטור\u0004 מראשית הגז, \u0003ו\u0004אולם ה\u0003שוטף את הרחלים\u0004 — הצמר הנתלש אגב שטיפה \u0003חייב\u0004 בראשית הגז! \u0003ו\u0004משיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המחייבת את הצמר הנשטף מהרחלים בראשית הגז, הריהי כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ו\u0004אילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 הפוטרת את הצמר הנשטף מראשית הגז הריהי כשיטתו של \u0003ר' יוסי.\u0004","ומסבירים מה היא מחלוקת זו שבין חכמים ור' יוסי, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הנאמר בדין הלקט \"ובקוצרכם את קציר ארצכם... ולקט קצירך לא תלקט\" (ויקרא כג, כב), \u0003\"לקט קצירך\"\u0004 \u0003— בא להדגיש\u0004 שדווקא התבואה הנקצרת היא שנוהג בה דין לקט, \u0003ולא\u0004 נוהג דין \u0003לקט\u0004 בתבואת \u0003קיטוף.\u0004 ו\u0003ר' יוסי אומר: אין לקט אלא הבא מחמת קציר.\u0004","והדברים תמוהים, שלכאורה שיטת \u0003ר' יוסי היינו\u0004 \u0005[זו]\u0006 שיטת \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 ומה בא ר' יוסי להשמיענו? ומשיבים: כל המשנה \u0003כולה\u0004 שיטת \u0003ר' יוסי היא, והכי קתני\u0004 \u0005[וכך היא שנויה]:\u0006 \"לקט קצירך\" \u0003—\u0004 ולא לקט קיטוף, \u0003ש\u0004כן \u0003ר' יוסי אומר אין לקט אלא הבא מחמת קציר.\u0004 ומעתה יש לומר כי כדרך שפטר ר' יוסי לקט הבא על ידי קיטוף, כן הוא פוטר מראשית הגז את הצמר הבא על ידי שטיפה. ואילו חכמים החולקים על ר' יוסי וסוברים שאף בתבואה הנקטפת נוהג דין לקט, הריהם סבורים כמו כן שאף ראשית הגז נוהג בצמר הנשטף. ובביאור שיטת ר' יוסי,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: מודה ר' יוסי\u0004 לחכמים \u0003במידי דאורחיה\u0004 \u0005[בדבר שדרכו]\u0006 לאוספו שלא על ידי קצירה אלא בקטיפה, שנוהג בו דין לקט, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 על הכתוב \"ובקוצרכם את קציר ארצכם לא תכלה פאת שדך בקוצרך ולקט קצירך לא תלקט\", \u0003ר' יוסי אומר:\u0004 מן הכתוב \u0003\"קציר\"\u0004 — \u0003אין לי\u0004 שחייבת בלקט \u0003אלא\u0004 התבואה הבאה על ידי \u0003קציר\u0004 בלבד, ואולם זה ה\u0003עוקר\u0004 את תבואתו \u0003מנין\u0004 שאף תבואה זו חייבת בלקט?","לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"לקצור\"\u0004 — בכל דרך שהוא קוצר. ואף זה ה\u0003תולש\u0004 את תבואתו \u0003מנין\u0004 שאף תבואה זו חייבת בלקט? לכך \u0003תלמוד לומר \"בקוצרך\"\u0004 — שבכל אופן אסיפה שכך הוא דרכו, נוהג בו דין לקט.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו\u0006 כן\u0005]:\u0006 \u0003מלבנות\u0004 (ערוגות) \u0003בצלים ש\u0004נמצאות \u0003בין הירק, ר' יוסי אומר:\u0004 מפריש \u0003פאה מכל אחד ואחד\u0004 מהמלבנות הללו. \u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 מניח פאה \u0003מאחת\u0004 המלבנות \u0003על הכל.\u0004","הרי איפוא שלדעת ר' יוסי חייבים הבצלים בלקט, אף שאין הם נקצרים, כיון שכך הוא דרך אסיפתם\u0003.\u0004 עוד שנינו במשנתנו כי דין ראשית הצאן נוהג רק במרובה, והוסיפו \u0003ו\u0004הסבירו \u0003כמה הוא מרובה?\u0004 ונחלקו בדבר בית שמאי ובית הלל, שלדעת בית שמאי הכוונה לשתי רחלות ויותר, ולדעת בית הלל הכוונה היא לחמש רחלות ויותר. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003בית שמאי\u0004 — כיון שמוצאים אנו כי \u0003תרתי נמי איקרו\u0004 \u0005[שתי\u0006 רחלות \u0005גם כן נקראו]\u0006 \u0003\"צאן\",\u0004 שכן הביאו בית שמאי את הפסוק \"יחיה איש עגלת בקר ושתי צאן\" (ישעיה ז, כא), יש לחייב בראשית הגז שתי רחלות. \u0003אלא לבית הלל,\u0004 אף שהביאו את הפסוק \"חמש צאן עשויות\" (שמואל א כה, יח), המלמד שגם חמש רחלות נקראות \"צאן\", מכל מקום \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין הם מחייבים אף בשתי רחלות?","\u0003אמר רב כהנא\u0004 בתשובה: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"חמש צאן עשויות\", ומשמעות המלה \u0003\"עשויות\"\u0004 — \u0003ש\u0004חמש צאן \u0003עושות שתי מצות,\u0004 והן: \u0003ראשית הגז\u0004 (שאין מתקיים אלא בחמש רחלות) \u0003ומתנות\u0004 כהונה (המתקיים אף באחת). ומקשים על הסבר זה: \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא לשתי מצוות אחרות, שהן \u0003בכורה ומתנות,\u0004 ואין מכאן ראיה לראשית הגז!","ומשיבים: אין לומר כן, שהרי לקיום מצות \u0003בכורה חדא מי לא מיחייבא\u0004 \u0005[האם\u0006 רחל \u0005אחת אינה מחוייבת],\u0006 ואין צורך לכך בחמש צאן. ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה אומר כי שתי המצוות עליהן רמז הכתוב הן ראשית הגז ו\u0003מתנות\u0004 — אף במתנות יש לומר באותו אופן, \u0003חדא מי לא מיחייבא\u0004 \u0005[האם\u0006 רחלה \u0005אחת אינה מחוייבת],\u0006 ולמה הצריך הכתוב בה חמש צאן? \u0003אלא אמר רב אשי:\u0004 כך נדרשת המלה \u0003\"עשויות\"\u0004 — \u0003שמעשות את בעליהן, ואומרות לו: \"קום עשה מצוה\",\u0004 שמשעה שיש לאדם חמש צאן, הריהו מחוייב בנתינת הגז מהן. ומכאן למדו בית הלל שאין חיוב ראשית הגז אלא בחמישה צאן.","למעלה נדונו שיטות בית שמאי ובית הלל באשר למספר הרחלות שיש בהן חיוב נתינת ראשית הגז, שאלה אומרים בשתי רחלות ואלה אומרים בחמש רחלות. ובענין זה מביאים עוד, \u0003תניא דבי\u0004 \u0005[שנויה\u0006 ברייתא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל בר' יוסי\u0004 ש\u0003אומר משום\u0004 \u0005[בשם]\u0006 \u0003אביו\u0004 כי \u0003ארבע\u0004 רחלות נגזזות הן המחייבות במתן ראשית הגז מהן. וראיה לדבר שארבע רחלות נקראות בשם \"צאן\", \u0003ש\u0004כן \u0003נאמר\u0004 בתשלומים שמשלם אדם הגונב שה וטבחו או מכרו \u0003\"וארבע צאן תחת השה\"\u0004 (שמות כא, לז).","ובענין מחלוקתם זו של תנאים \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 שכך \u0003אמר רבי:\u0004 גם \u0003אלמלא\u0004 (אילו) היה יסוד \u0003דבריהן\u0004 של בית הלל ובית שמאי נלמד מ\u0003דברי\u0004 ה\u0003תורה\u0004 (מן האמור בחמישה חומשי תורה), \u0003ו\u0004יסוד \u0003דברי בריבי\u0004 (כינויו של ר' יוסי) לא היה אלא מן ה\u0003קבלה\u0004 (מן הנביאים והכתובים) — גם אז, \u0003אנן\u0004 \u0005[אנו]\u0006 את \u0003דברי בריבי שומעין\u0004 (מקבלים). \u0003וכל שכן\u0004 עתה, \u0003ש\u0004יסוד \u0003דבריהם\u0004 של בית שמאי הינו מ\u0003דברי קבלה\u0004 (שכן בית שמאי למדו את שיטתם מן האמור בספר ישעיה, ובית הלל למדו את שיטתם מן האמור בספר שמואל), \u0003ו\u0004אילו יסוד \u0003דברי בריבי\u0004 הוא \u0003ב\u0004\u0003דברי תורה\u0004 (בכתוב שבספר שמות).","ומקשים על דברי רבי: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 כי \u0003אין הכרעה\u0004 של דעה \u0003שלישית\u0004 הבאה לפשר בין שתי דעות חלוקות \u0003מכרעת,\u0004 ואם כן אין לפסוק כדעת ר' יוסי האומר שחיוב ראשית הגז הינו בארבע רחלות, שזו דעה המפשרת בין דעת בית שמאי הסבורה שהחיוב הוא בשתי רחלות, ובין דעת בית הלל הסבורה שהחיוב הוא בחמש רחלות!"],["\u0003אמר ר' יוחנן\u0004 בתשובה: אף שהיא דעה מכרעת, רבי קיבל את דעתו של ר' יוסי כי \u0003מפי שמועה\u0004 (על פי מסורת) שהיתה בידו \u0003אמרה\u0004 ר' יוסי להלכה זו, מסורת שמקורה \u0003מפי\u0004 הנביאים \u0003חגי זכריה ומלאכי.\u0004","עוד שנינו במשנתנו ש\u0003ר' דוסא בן הרכינס אומר\u0004 בחיוב ראשית הגז שהוא בחמש רחלות הגוזזות כל אחת מהן מנה ופרס, ואילו חכמים אומרים שהחיוב הוא בחמש רחלות גוזזות כל שהן. \u0003ו\u0004שואלים: \u0003כמה\u0004 הוא שיעור \u0003\"כל שהן\"? אמר רב:\u0004 שתהא הגיזה כמשקל \u0003מנה\u0004 (משקל מאה דינרים) \u0003ו\u0004עוד \u0003פרס\u0004 (מחצית המנה, שהם חמשים דינרים), \u0003ובלבד שיהו\u0004 הגיזות שמשקלן מאה וחמשים דינרים \u0003מחומשות\u0004 (שמכל כבשה ניטלה חמישית משקל זה של הגיזות). \u0003ו\u0004אילו \u0003שמואל אמר\u0004 שהשיעור שאמרו חכמים \"כל שהן\" כוונתו, שאם היתה כלל הגיזה במשקל כולל של \u0003ששים\u0004 סלעים, חייב בראשית הגז, \u0003ו\u0004מתוכם \u0003נותן\u0004 גיזה שמשקלה \u0003סלע אחת לכהן.\u0004","\u0003רבה בר בר חנה אמר\u0004 בשם \u0003ר' יוחנן:\u0004 \"כל שהן\" כוונתו שאם היתה כלל הגיזה במשקל \u0003שש\u0004 סלעים — הריהו נותן ממנה \u0003לכהן חמשה\u0004 סלעים, \u0003ו\u0004גיזה שמשקלה סלע \u0003אחד\u0004 הריהו משאיר \u0003לו.\u0004 ואילו \u0003עולא אמר\u0004 בשם \u0003ר' אלעזר\u0004 כי \u0003\"כל שהן\" שנינו\u0004 בדברי חכמים, אף שכלל הגיזה הוא משקל של סלע אחד בלבד — חייב בראשית הגז. ודנים בדברי חכמים אלה,","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וכמה נותן לו? משקל חמש סלעים ביהודה, שהן עשר סלעים בגליל,\u0004 ומעתה יש לומר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 שאמר כמה הוא שיעור הגיזה המתחייב בנתינת ראשית הגז, ולא אמר כמה שיעור נתינה זו (ויש מקום לומר שאף לדעתו הנתינה היא בשיעור חמישה סלעים). \u0003ו\u0004כן לשיטתו של \u0003ר' יוחנן\u0004 שאמר כי שיעור הנתינה הוא חמישה סלעים — \u0003ניחא\u0004 \u0005[נוח,\u0006 אין קושי מדברי המשנה\u0005]\u0006 האומרת ששיעור הנתינה הוא חמישה סלעים. \u0003אלא ל\u0004שיטת \u0003שמואל\u0004 שאמר ששיעור הנתינה הוא סלע אחד בלבד, \u0003ו\u0004כן לשיטת \u0003ר' אלעזר\u0004 שאמר כי שיעור הנתינה הוא בכל שהוא. \u0003קשיא\u0004 \u0005[קשה]!\u0006","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה מקשה רק על דברי שמואל ולא על דברי רב, \u0003ו\u0004אולם \u0003ל\u0004שיטתו של \u0003רב מי ניחא\u0004 \u0005[האם נוח\u0006 הנאמר במשנתנו\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כי שיעור \u0003ראשית הגז\u0004 הניתן לכהן הוא \u0003ב\u0004אחד מ\u0003ששים\u0004 מכלל הגיזה. וכיון שסבור רב כי שיעור הגיזה המתחייבת בראשית הגז הוא מאה וחמישים סלעים, וחלק אחד מששים של כמות שכזו הריהו פחות מסלע אחד, ודאי ששיטת המשנה, ששיעור הנתינה הוא חמישה סלעים, אינה כשיטתו!","ומשיבים: אין זו קושיה על רב, כי \u0003הא איתמר עלה דההיא\u0004 \u0005[הרי נאמר עליה, על אותה\u0006 הלכה שבמשנתנו\u0005]\u0006 ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שאין המדובר (שנותנים לכהן חמישה סלעים בראשית הגז) אלא \u0003ב\u0004גיזתו של אדם מ\u0003ישראל שיש לו גיזין הרבה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ומבקש ליתנן לכהן\u0004 (לכהנים רבים), \u0003ואמרינן ליה\u0004 \u0005[ואומרים אנו לו],\u0006 \u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מהכהנים שתתן להם מגיזתך, \u0003לא תבצר ליה\u0004 \u0005[אל תפחית לו]\u0006 \u0003מ\u0004משקל \u0003חמשת סלעים.\u0004 ואולם בזמן שגיזתו של האדם מועטת \u0003— אינו נותן לכהן משקל חמישה סלעים, אלא חלק אחד מששים מכלל הגיזה. ואין מקום להקשות מדברי המשנה.\u0004","למעלה הובאה מחלוקת רב ושמואל בהסבר דברי חכמים במשנתנו, ועתה דנים בה \u0003גופא\u0004 \u0005[עצמה].\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כי שיעור הנתינה ב\u0003ראשית הגז\u0004 — הוא אחד \u0003בששים\u0004 מכלל הגיזה. וכן הוא לדעתם שיעור \u0003ה\u0004\u0003תרומה\u0004 (תרומה גדולה) הניתנת לכהן מן היבול — אחד \u0003בששים\u0004 מכלל הפירות. וכן הוא שיעור ה\u0003פאה\u0004 הנשארת לעניים בשדה — \u0003אחד\u0004 \u0003בששים\u0004 מן התבואה.","ושואלים על דבריהם: והאם שיעור \u0003ה\u0004\u0003תרומה\u0004 הוא אחד \u0003בששים? והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה שבמסכת תרומות\u0005]\u0006 בשיעור ה\u0003תרומה\u0004 כי זה הנותן את תרומתו ב\u0003עין יפה\u0004 — נותן \u0003אחד מארבעים\u0004 (שהוא אחוז וחצי)! ומשיבים: שיעור התרומה \u0003דאורייתא\u0004 \u0005[מדין תורה]\u0006 — אחד \u0003בששים\u0004 בלבד, ואילו שיעור התרומה \u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 שהוסיפו על שיעור זה, הוא אחד \u0003בארבעים.\u0004","ושואלים: האם שיעור תרומה \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא אחד \u0003בששים? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 כי \u0003חטה אחת\u0004 הניתנת כתרומה \u0003פוטרת את הכרי\u0004 (ערימת גרגרי החיטה) כולו! ומשיבים: אכן שיעור התרומה \u0003דאורייתא\u0004 \u0005[מדברי תורה]\u0006 הוא \u0003כ\u0004דברי \u0003שמואל,\u0004 שחיטה אחת פוטרת את הכרי כולו. ואולם תקנה \u0003דרבנן\u0004 \u0005[של חכמים]\u0006 \u0003ב\u0004תבואה שחיובה הוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — שיהא שיעורה הניתן לכהן \u0003אחת מארבעים.\u0004 וכן תקנה \u0003דרבנן\u0004 \u0005[של חכמים]\u0006 היא ש\u0003ב\u0004תבואה שחיובה רק \u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 — שיהא שיעורה הניתן אחד \u0003בששים\u0004 בלבד.","ועל ששנינו במשנה שהובאה למעלה כי שיעור ה\u0003פאה\u0004 הוא \u0003בששים,\u0004 תוהים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה שבמסכת פאה\u0005]\u0006 כי \u0003אלו דברים שאין להן שיעור: הפאה, והבכורים\u0004 \u0003והראיון\u0004 (קרבן עולת ראיה, הבא ברגלים). הרי שלפאה אין שיעור! ומשיבים: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 באמת \u0003אין לה שיעור,\u0004 ואולם \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 — שיעורה אחד \u0003בששים.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיעו לנו\u0006 רב ושמואל בדבריהם\u0005]?\u0006 והרי כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנה במסכת פאה שלאחרי המשנה הקודמת\u0005]\u0006 כי \u0003אין פוחתין לפאה מששים, אף על פי שאמרו הפאה אין לה שיעור!\u0004 ומשיבים: יש חידוש בדברי רב ושמואל, כי \u0003התם\u0004 \u0005[שם,\u0006 במסכת פאה\u0005]\u0006 מדובר \u0003בארץ\u0004 ישראל, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 בדברי רב ושמואל\u0005]\u0006 מדובר \u0003בחוצה לארץ.\u0004","למעלה הובאה דעת ר' יוחנן בשיעור הגיזה המתחייב בנתינת ראשית הגז, ומביאים עוד בענין זה: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003איסי בר היני\u0004 מבבל לארץ ישראל \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003ר' יוחנן דקא מתני ליה לבריה\u0004 \u0005[שהוא משנה,\u0006 מקריא משניות \u0005את בנו]\u0006 והיה שונה את משנתנו ואומר \"וראשית הגז אינו נוהג אלא ב\u0003רחלים\", אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לאיסי: \u0003אתנייה\u0004 \u0005[שנה לו]\u0006 \u0003\"רחלות\"! אמר ליה\u0004 \u0005[לו]\u0006 איסי: הריני שונה במשנה \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 במקרא: \u0003\"רחלים מאתים\"\u0004 (בראשית לב, יד). \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לאיסי: \u0003לשון תורה לעצמה\u0004 ו\u0003לשון חכמים לעצמן,\u0004 וחכמים קוראים להם \"רחלות\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לאיסי: \u0003מאן\u0004 \u0005[מיהו]\u0006 זה שמכהן עתה כ\u0003ריש סדרא\u0004 \u0005[ראש הסדר],\u0006 כלומר, ראש הישיבה, \u0003בבבל? אמר ליה\u0004 \u0005[לו]\u0006 איסי: \u0003אבא אריכא\u0004 \u0005[הארוך],\u0006 שהוא כינויו של האמורא רב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לאיסי: \u0003\"אבא אריכא\" קרית ליה\u0004 \u0005[\"אבא הארוך\" אתה קורא לו]?\u0006 בלשון קירבה?! והרי \u0003דכירנא כד הוה יתיבנא אחר\u0004 \u0005[זוכר אני כאשר הייתי יושב]\u0006 בבית המדרש \u0003שבע עשרה שורן אחוריה\u0004 \u0005[שורות אחרי]\u0006 \u0003רב,\u0004 שהיה יושב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבי, ונפקי זיקוקין דנור מפומיה\u0004 \u0005[והיו יוצאים זיקוקין של אש מפיו]\u0006 של \u0003רב לפומיה\u0004 \u0005[לפיו]\u0006 של \u0003רבי, ומפומיה\u0004 \u0005[ומפיו]\u0006 של \u0003רבי לפומיה\u0004 \u0005[לפיו]\u0006 של \u0003רב, ולית אנא ידע מה הן אמרין\u0004 \u0005[ולא ידעתי מה הם אומרים]\u0006 מתוך עומק הדברים, \u0003ואת \"אבא אריכא\" קרית ליה\u0004 \u0005[ואתה \"אבא הארוך\" אתה קורא לו]?!\u0006","\u0003אמר ליה איהו\u0004 \u0005[לו הוא,\u0006 איסי בר איני\u0005]:\u0006 \u0003ראשית הגז בכמה\u0004 הוא שיעור הגיזה המתחייב בה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: ב\u0004גיזה שיש בה כמשקל \u0003ששים\u0004 סלעים. הקשה לו איסי: \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"בכל שהן\" תנן\u0004 \u0005[שונים\u0006 במשנתנו\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אם כן,\u0004 שאתה מקשה עלי מלשון הדברים כפי שהם שנויים במשנה, \u0003מה\u0004 הוא ההבדל ש\u0003בין לי ולך,\u0004 שאתה יודע רק את דברי המשנה, ואילו אני יודע את מסקנת ההלכה בענין זה.","בעקבות המסופר למעלה, ששיטת ר' יוחנן היא כי שיעור הגיזה המתחייב בראשית הגז הוא ששים סלעים, מביאים עוד: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, והביא עמו מסורות חכמים, \u0003אמר\u0004 בדין \u0003ראשית הגז:\u0004 \u0003רב אמר\u0004 כי השיעור המתחייב הוא \u0003בששים\u0004 סלעים, \u0003ו\u0004אילו \u0003ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' ינאי אמר\u0004 שאף \u0003ב\u0004גיזה ששיעורה \u0003שש\u0004 מתחייבים בראשית הגז. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי:\u0004 בדבריך אלה, \u0003אנחת לן חדא, ואקשת לן חדא\u0004 \u0005[הנחת,\u0006 תרצת, \u0005לנו דבר אחד, והקשית לנו\u0006 ב\u0005דבר אחד],\u0006 ומפרט אביי את דבריו: יישבת","לנו את שיטתו של ר' יוחנן, שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 מדברי \u0003ר' יוחנן\u0004 שאמר למעלה במחלוקתו עם ר' אלעזר כי שיעור הגיזה המתחייבת הוא ששה סלעים, על דברי \u0003ר' יוחנן\u0004 שאמר לאיסי בר היני ששיעור הגיזה המתחייב הוא ששים סלעים, \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 שאמר בששים סלעים, היא שיטתו \u0003דידיה\u0004 \u0005[שלו],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר כי השיעור הוא ששה סלעים, היא שיטתו \u0003דרביה\u0004 \u0005[של רבו,\u0006 ר' ינאי\u0005],\u0006","\u0003אלא\u0004 מדברי \u0003רב\u0004 על דברי \u0003רב קשיא\u0004 \u0005[קשה],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רב\u0004 כי שיעור הגיזה המתחייב הוא \u0003מנה ופרס,\u0004 שהריהו שלושים ושבעה וחצי סלעים (שהרי \u0003המנה הוא עשרים וחמישה סלעים), ובדבריך נאמר ששיטת רב היא שיעור ששים סלעים!\u0004 ומשיבים: אף מדברי \u0003רב\u0004 על דברי \u0003רב נמי לא קשיא\u0004 \u0005[גם כן לא קשה],\u0006 שכן \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מנה\" דקאמר\u0004 \u0005[שהוא אומר]?\u0006 אין זה מנה בן עשרים וחמשה סלעים, אלא מנה \u0003בן ארבעים סלעים, דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 שיעור זה של מנה וחצי,"],["\u0003בששים\u0004 סלעים. ותוהים על הסבר זה: \u0003ותני תנא\u0004 \u0005[ו\u0006כי \u0005שונה התנא]\u0006 בדבריו \u0003מנה\u0004 שהוא \u0003בן ארבעים סלעים,\u0004 והרי סתם \"מנה\" הוא בן עשרים וחמישה סלעים? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 גם כך נוהג התנא, \u0003והתנן\u0004 \u0005[והרי\u0006 כך \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חמת חדשה\u0004 (נאד נוזלים העשוי מעור חדש), שעדיין לא הסתיימה מלאכת תפירתה, ואי אפשר לתת בתוכה נוזלים שישתמרו בתוכה. \u0003אף על פי ש\u0004היא \u0003מקבלת\u0004 (יכולה לקבל ולשמר בתוכה) דבר ים ששיעורם הוא כ\u0003רמונים,\u0004 שאין אלה נופלים החוצה מבעד לחלקים הפתוחים שבחמת — מכל מקום הריהי \u0003טהורה,\u0004 שאין היא מקבלת טומאה ככלי, כיון שעדיין לא נגמרה מלאכתה.","ואולם אם כבר \u0003תפרה\u0004 לחמת זו, והעמידה על תיקונה, \u0003ו\u0004לאחר מכן \u0003נקרעה\u0004 — \u0003שיעורה\u0004 להיחשב כדבר שאינו כלי, ולצאת בכך מידי טומאה, הוא \u0003כ\u0004שהקרע במידה כזו ש\u0003מוציא רמונים\u0004 הנמצאים בתוך החמת. \u0003ר' אליעזר בן יעקב אומר\u0004 שעל מנת שתיחשב החמת שנקרעה כמי שאינה עוד כלי, צריך שיהא נקב הקריעה \u0003כ\u0004שיעורן של \u0003פקעיות\u0004 (קבוצת חוטים) \u0003של שתי,\u0004 שמשקלן של אלה הוא \u0003אחת מארבע\u0004 (רביעית) של מנה, כשמדובר \u0003במנה בן ארבעים סלעים.\u0004 הרי איפוא שיש בדברי המשנה \"מנה\" שהוא בן ארבעים סלעים דווקא.","\u0003ו\u0004עוד שנינו במשנתנו בדין ראשית הגז באשר לשאלה \u0003כמה נותן לו\u0004 לכהן במתנתו — שיהא זה משקל חמש סלעים ביהודה שהן עשר סלעים בגליל. ועוד אמרו שיהא הצמר הניתן לכהן בשיעור זה כשהצמר כבר מלובן (מכובס ומנוקה מלכלוכים שבצמר), ולא כשהוא מלוכלך (\"צואי\"). ובפירוש הדברים הללו \u0003תנא\u0004 \u0005[שנה\u0006 החכם \u0005:\u0006 כי \u0003לא\u0004 התכוונו לומר בכך \u0003שילבננו\u0004 הבעלים את הצמר, \u0003ויתננו לו\u0004 לכהן בשיעור זה של סלעים. \u0003אלא\u0004 הכוונה היא שיתן הבעלים לכהן צמר בשיעור כזה, \u0003ש\u0004כאשר \u0003ילבננו\u0004 ה\u0003כהן ו\u0004אז הצמר \u0003יעמוד על\u0004 שיעור \u0003חמש סלעים.\u0004","ועוד אמרו במשנתנו כי שיעור זה של הצמר הניתן לכהן הריהו \u0003כדי\u0004 השיעור הנדרש \u0003לעשות\u0004 ממנו \u0003בגד קטן.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 שכך הוא שיעור הצמר הניתן לכהן? \u0003אמר ר' יהושע בן לוי:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בתחילה במצות נתינת ראשית הגז \"וראשית גז צאנך תתן לו\" (דברים יח, ד), ומיד לאחר מכן נאמר \"כי בו בחר ה' אלהיך מכל שבטיך לעמוד לשרת בשם ה' הוא ובניו כל הימים\". ולמדים אנו מן המלים \u0003\"לעמוד לשרת\"\u0004 — שתהא הנתינה כדי עשיית \u0003דבר שהוא ראוי לשירות, מאי ניהו\u0004 \u0005[מה הוא]\u0006 דבר זה? \u0003אבנט\u0004 שבבגדי כהונה, שכדי לעשותו נדרש צמר בשיעור חמש סלעים.","ומקשים: מנין לנו שדי בנתינת צמר בשיעור לעשיית אבנט, ואולי \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא לצמר שיש בו לעשיית \u0003מעיל\u0004 שבבגדי כהונה, שהוא שיעור הרבה יותר גדול! ומשיבים: כלל הוא שיש לאחוז בדרשת הכתובים לענין המועט יותר, שכן אם \u0003תפשת\u0004 (לקחת) ללמוד את ה\u0003מרובה,\u0004 שיהא זה שיעור גדול ביותר — \u0003לא תפשת\u0004 (לקחת לקיחה גמורה), שכן אפשר לשאול שמא הכוונה דווקא לשיעור המועט יותר. ואולם כאשר \u0003תפשת\u0004 (לקחת) ללמוד לענין ה\u0003מועט\u0004 — אכן \u0003תפשת\u0004 (לקחת) בכך. שהרי ברור לכל הוא שהתקיימה המצוה גם בשיעור זה (ששיעור זה הוא בכלל השיעור הגדול יותר).","ושואלים באופן אחר: מנין לנו שהכוונה לצמר שיש בו שיעור לעשיית אבנט שבבגדי כהנים, \u0003ואימא\u0004 \u0005[ו\u0006שמא \u0005תאמר]\u0006 שהכוונה לצמר בשיעור קטן יותר מזה שעושים ממנו אבנט, שהוא כדי לעשות \u0003כיפה של צמר\u0004 הניתנת בראש הכהן הגדול! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כיפה של צמר היתה מונחת בראש\u0004 ה\u0003כהן\u0004 ה\u0003גדול, ועליה\u0004 היה ה\u0003ציץ נתון,\u0004 שנוהגים כן בהנחת הציץ כדי \u0003לקיים מה שנאמר\u0004 בציץ: \u0003\"ושמת אותו על פתיל תכלת\"\u0004 (שמות כח, לז)!","ומשיבים: אין לומר כן, כי \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 בענין נתינת ראשית הגז לכהן \"כי בו בחר ה' אלהיך מכל שבטיך לעמוד לשרת בשם ה' הוא ובניו כל הימים\", ולמדים אנו מן הכתוב \u0003\"הוא ובניו\"\u0004 — שתהא זו נתינה לצורך עשיית דבר שירות במקדש, ב\u0003דבר השוה לאהרן ולבניו,\u0004 הן לכהן הגדול (\"אהרן\") והן לכהן הדיוט (\"ולבניו\"), והוא האבנט. מה שאין כן כיפה זו של צמר שנוהגת בכהן גדול בלבד.","ומקשים: והרי ה\u0003אבנט נמי לא שוי\u0004 \u0005[גם כן אינו שווה]\u0006 לכל הכהנים, לכהן גדול ולכהן הדיוט. שאכן \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטתו של \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003אבנטו של כהן גדול\u0004 בעבודת יום הכיפורים (שהיה של פשתן ולא של צמר) \u0003לא זהו\u0004 כ\u0003אבנטו של כהן הדיוט\u0004 וכהן גדול (בשאר ימות השנה) שהיה משל כלאיים, צמר ופשתים. ואולם בכל ימות השנה שווים היו כל הכהנים ובכללם הכהן הגדול, באבנט — \u0003שפיר\u0004 \u0005[יפה]\u0006 נדרש הכתוב בנתינת צמר ראשית הגז שתהא זו לדבר העשוי לכל הכהנים, שהוא אבנט זה.","\u0003אלא ל\u0004שיטתו של \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי אבנטו של הכהן הגדול ביום הכיפורים (שהיה עשוי פשתים) \u0003זהו אבנטו של כהן הדיוט\u0004 שאף הוא עשוי פשתים. ואילו האבנט שיש בו צמר (ופשתים) הוא אבנטו של הכהן הגדול כל ימות השנה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 שהרי צמר בשיעור עשיית אבנט, אינו משמש לדבר שהוא שווה לכל הכהנים? ומשיבים: אכן כן, ואולם מכל מקום \u0003שם אבנט בעולם\u0004 (ככלל) הריהו נוהג הן אצל הכהן הגדול (\"אהרן\"), והן אצל כלל הכהנים (\"ובניו\"). מה שאין כן בכיפה של צמר שאינה נוהגת אלא בכהן הגדול בלבד, ולכך עדיף הוא הלימוד כפי שהצענו, שיהא שיעור הנתינה כדי עשיית אבנט.","עוד שנינו במשנתנו שאם \u0003לא הספיק ליתנו\u0004 את ראשית גיזת צאנו לכהן עד שצבעו, הריהו פטור מליתנו עוד. ואם לבנו ולא צבעו, הריהו חייב. והקונה את גיזת צאנו של הגוי פטור מנתינת ראשית הגז. ובענין זה של הקונה גיזת צאנו של הגוי מביאים, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדינו של זה שיש לו חמש רחלות, ואולם לאחר ש\u0003גזז\u0004 אחת, עמד \u0003ומכר\u0004 את \u0003ה\u0004\u0003ראשונה\u0004 שנגזזה, וכן עשה בשאר כבשותיו, כך שלבסוף היו בידיו גיזותיהן של חמש כבשות, ואולם אין לו את הכבשות עצמן. \u0003רב חסדא אמר\u0004 שהריהו \u0003חייב\u0004 בנתינת ראשית הגז, ואילו \u0003ר' נתן בר הושעיא אמר\u0004 שהריהו \u0003פטור\u0004 מן הנתינה.","ומסבירים את דעותיהם: \u0003רב חסדא אמר\u0004 שהריהו \u0003חייב\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003גזז\u0004 חמש כבשות, ובשעה שנגזזו כל אחת מהכבשות הללו היתה זו כבשה שלו, והרי זה איפוא בכלל \"גז צאנך\". ואילו \u0003ר' נתן בר הושעיא אמר\u0004 שהריהו \u0003פטור\u0004 — \u0003כי\u0004 \u0003בעידנא דקא מלא שיעורא\u0004 \u0005[בזמן שמתמלא השיעור\u0006 הראוי\u0005]\u0006 לחיוב נתינת ראשית הגז, שהוא גיזת חמש רחלות, \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו הרחלות בגדר \u0003\"צאנך\",\u0004 ששייכות לו. \u0003ו\u0004במקרה זה \u0003ליכא\u0004 \u0005[אין כאן]\u0006 קיומו של תנאי זה.","ומקשים על דברי ר' נתן בר הושעיא: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003הלוקח\u0004 (הקונה) את \u0003גז צאנו של גוי,\u0004 \u0003פטור מראשית הגז,\u0004 שכן הצאן בשעה שנגזז לא היה שייך לו. ונדייק: \u0003הא\u0004 \u0005[הרי\u0006 נלמד מכאן שאם קנה מידי הגוי את \u0003צאנו לגזוז,\u0004 שהקנה לו הגוי את גוף הצאן עד לאחר שיגזזו — הקונה \u0003חייב\u0004 בנתינת ראשית הגז, שהרי זה בכלל \"צאנך\". ואולם על כך יש להקשות לשיטת ר' נתן בר הושעיא: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא חייב באופן מכירה זה, והרי \u0003כל חד וחד בתר\u0004 \u0005[אחת ואחת\u0006 מן הכבשות, \u0005לאחר]\u0006 ה\u0003גיזה\u0004 הריהי \u0003נפקא\u0004 \u0005[יוצאת]\u0006 \u0003לה מרשותיה\u0004 \u0005[מרשותו],\u0006 ושבה לרשות המוכר הגוי, ומעתה לאחר שסיים לגזוז את חמש הכבשות, לא היו לו כבשות, ואין מתקיים בכך \u0005\"צאנך\"!\u0006","\u0003תרגמא\u0004 \u0005[הסביר]\u0006 \u0003רב חסדא אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' נתן בר הושעיא:\u0004 מדובר \u0003כגון ש\u0004הגוי \u0003הקנן לו\u0004 לישראלי את הכבשים הללו לפרק זמן של \u0003כל שלשים יום\u0004 של עת הגזיזה, והריהן שלו אף לאחר שנגזזו, ולכך הריהו חייב בנתינת ראשית הגז, שכן התקיים התנאי של \"צאנך\".","עוד שנינו במשנתנו ש\u0003הלוקח גז צאנו של חבירו,\u0004 אם שייר המוכר לעצמו מעט מצאנו — המוכר חייב לתת את ראשית הגז מחלקו על כל הגיזה. ואם לא שייר המוכר מן הגיזה לעצמו — הקונה חייב לתת את ראשית הגז. ודנים בענין \u0003זה:\u0004 \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור \u0003דהיכא דאיכא שיורא גבי\u0004 \u0005[שבמקום שיש שיור אצל]\u0006 ה\u0003מוכר,\u0004 בענין המתנות \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מוכר אזלינן\u0004 \u0005[אנו הולכים]\u0006 ולא אחר הלוקח?","\u0003אמר רב חסדא:\u0004 שיטת \u0003ר' יהודה היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדינו של \u0003המוכר\u0004 את שדה תבואתו, והיו אף \u0003קלחי אילן בתוך שדהו\u0004 (שמכר את העצים בלבד, על מנת שהקונה יוכל לעקור אותם ולטעת אותם בתוך שדהו, והיו העצים הללו טעונים בפירות) — הקונה \u0003נותן פאה לכל אחד ואחד\u0004 מן העצים שקנה. שכיון שאין הקרקע שלו, אין העצים מצטרפים לנתינת פאה אחת.","\u0003אמר ר' יהודה: אימתי\u0004 נותן הקונה פאה? \u0003בזמן שלא שייר בעל השדה\u0004 עצים לעצמו, \u0003אבל\u0004 אם \u0003שייר בעל השדה\u0004 עצים לעצמו — בעל השדה \u0003נותן פאה\u0004 \u0003על הכל,\u0004 על כל העצים שהיו שם. הרי ששיטת ר' יהודה היא שבמקום ששייר המוכר לעצמו, הולכים אחריו לענין חיוב הנתינה, וכן הוא בדין ראשית הגז.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב חסדא: \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 זה ש\u0003אמר\u0004 בהסבר דעתו של ר' יהודה: \u0003ו\u0004דין זה שהפאה שנותן בעל השדה פוטרת את כל העצים \u0003הוא\u0004 רק כ\u0003שהתחיל בעל השדה לקצור\u0004 (ללקט) את הפירות קודם שמכר את העצים, שכיון שכבר חל עליו חיוב נתינת הפאה, הריהו נותן פאה מהעצים ששייר לעצמו על כל העצים שבשדה. ואולם אם בעל השדה לא התחיל ללקט פירות קודם המכירה — אף ששייר לעצמו מן העצים, חייב הקונה לתת פאה מהעצים שקנה. והרי זה איפוא שלא כדין ראשית הגז, שאין החיוב חל אלא לאחר שכבר מכר המוכר את צאנו!","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 כי \u0005כך גם כן]\u0006 במשנתנו מדובר \u0003והוא שהתחיל לגזוז\u0004 — אין לומר כן, \u0003כי\u0004 \u0003בשלמא התם\u0004 \u0005[נניח שם,\u0006 בפאה\u0005]\u0006 \u0003\"ובקצרכם את קציר ארצכם\"\u0004 (ויקרא יט, ט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 והרי זה לומר כי \u0003מעידנא דאתחיל\u0004 \u0005[מזמן שהתחיל]\u0006 \u0003לקצור מיחייב בכולה\u0004 \u0005[מתחייב בכל]\u0006 ה\u0003שדה, אלא הכא\u0004 \u0005[כאן,\u0006 בדין ראשית הגז\u0005]\u0006 \u0003מעידנא דאתחיל למיגז, לא מיחייב בכוליה עדריה\u0004 \u0005[מזמן שהתחיל לגזוז, אינו מתחייב בכל עדרו]!\u0006","\u0003אלא אמר רבא:\u0004 דברי משנתנו הריהם כשיטת \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכתנו בפרק \u0005הקודם\u0006\u0005]\u0006 לענין מתנות כהונה, שאם \u0003אמר לו\u0004 הקונה למוכר \u0003\"מכור לי בני מעיה של פרה זו\", והיה בהן\u0004 בתוך המעיים \u0003מתנות\u0004 כהונה (הקיבה) — הקונה \u0003נותנן לכהן, ואין\u0004 הוא \u0003מנכה\u0004 (מפחית) \u0003לו\u0004 למוכר בשל כך \u0003מן הדמים\u0004 שהתחייב לשלם על בני המעיים שקנה. ואולם אם \u0003לקח\u0004 (קנה) \u0003ממנו\u0004 את בני המעיים \u0003במשקל\u0004 — הרי הוא אמנם \u0003נותנן לכהן, ו\u0004אולם \u0003מנכה לו מן הדמים,\u0004"],["\u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מתנות\u0004 של \u0003כהן לא מזבין איניש\u0004 \u0005[אין אדם מוכר],\u0006 כלומר, אינו יכול למכור, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מתנות\u0004 של \u0003כהן לא מזבין איניש\u0004 \u0005[אין אדם יכול למכור].\u0006 \u0003הלכך\u0004 \u0005[על כן]:\u0006 אם \u0003שייר המוכר\u0004 — הרי ה\u0003מוכר חייב, דאמר ליה\u0004 \u0005[שאמר לו]\u0006 ה\u0003לוקח: מתנה\u0004 של ה\u0003כהן גבך\u0004 \u0005[אצלך]\u0006 \u0003היא,\u0004 אבל אם \u0003לא שייר\u0004 שום דבר לעצמו — \u0003לוקח חייב, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 ה\u0003מוכר: מתנה\u0004 של ה\u0003כהן לא זבני\u0004 \u0005[מכרתי]\u0006 \u0003לך,\u0004 אלא אתה צריך להפריש אותם משלך.","","דין \u0003שילוח הקן\u0004 האמור בתורה \u0003נוהג\u0004 בין \u0003בארץ ו\u0004בין \u0003בחוץ לארץ.\u0004 וכמו כן נוהג דין זה בין \u0003בפני הבית\u0004 (בזמן שבית המקדש קיים) \u0003ו\u0004בין \u0003שלא בפני הבית.\u0004 ואולם נוהג דין זה דווקא \u0003ב\u0004עופות של \u0003חולין אבל לא ב\u0004עופות ה\u0003מוקדשין.\u0004 ומציינים: יש \u0003חומר\u0004 (חומרה) \u0003ב\u0004דין \u0003כסוי הדם מ\u0004דין \u0003שילוח הקן, ש\u0004כן דין \u0003כסוי הדם נוהג\u0004 גם \u0003בחיה ו\u0004גם \u0003בעוף,\u0004 בין שהיה בעל חיים זה \u0003מזומן\u0004 לו, שגדל ברשותו, \u0003ו\u0004בין \u0003שאין מזומן\u0004 לו. \u0003ו\u0004אילו דין \u0003שילוח הקן אינו נוהג אלא בעוף\u0004 בלבד ולא בחיה, \u0003ו\u0004כן \u0003אינו נוהג אלא בשאינו מזומן.\u0004","ומפרטים: \u0003איזהו\u0004 (מיהו המוגדר) \u0003שאינו מזומן?\u0004 כל עופות, ואפילו אלה שהם עופות ביתיים \u0003כגון אווזין ותרנגולים ש\u0004ברחו מן הבית ו\u0003קננו בפרדס,\u0004 שנחשב כמי שאינו מזומן, שכן יכול הוא לפרוח משם. \u0003אבל אם קננו בבית, וכן יוני הרדסיאות\u0004 (סוג יונים הגדל בבתי אדם) — הרי אלה נחשבים כמזומנים, ולפיכך הריהו \u0003פטור משילוח\u0004 האם. וכן אם היה זה \u0003עוף טמא\u0004 — הוא \u0003פטור מלשלח\u0004 את האם. ואף אם היה זה \u0003עוף טמא\u0004 ה\u0003רובץ על ביצי עוף טהור, ו\u0004כן עוף \u0003טהור\u0004 ה\u0003רובץ על ביצי עוף טמא\u0004 — \u0003פטור מלשלח\u0004 את האם. סוג העוף הנקרא \u0003קורא,\u0004 שדרכו של ה\u0003זכר\u0004 שגם הוא דוגר על הביצים, כדרכה של הנקבה — \u0003ר' אליעזר מחייב\u0004 לשלח את הקורא הזכר, \u0003וחכמים פוטרין.\u0004 שנינו במשנתנו וכן בכמה פרקים קודמים ביטויים זהים בדינים אלה שהם נוהגים בכולם, \"בארץ ובחוצה לארץ\"; \"בפני הבית ושלא בפני הבית\"; \"בחולין ובמוקדשין\", ועל כך אמרו \u0003ר' אבין ור' מיישא, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 כי \u0003כל היכא דתנן\u0004 \u0005[מקום ששנינו]\u0006 במשניות הללו שנוהג הדין האמור בהם \u0003בארץ ובחוצה לארץ\u0004 — הרי זה \u0003שלא לצורך.\u0004 כיון שמצוות אלה אינן חובות הארץ אלא חובות הגוף, שברור שנוהגות אף בחוצה לארץ. \u0003לבד\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004מה ששנינו בענין \u0003ראשית הגז,\u0004 שהיה צורך לשנות כן, כדי \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005]\u0006 \u0003מ\u0004דעת \u0003ר' אלעאי,\u0004 ש\u0003אמר\u0004 כי דין \u0003ראשית הגז אינו נוהג אלא בארץ\u0004 בלבד.","","\u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר\u0004 כי \u0003כל היכא דתנן\u0004 \u0005[מקום ששנינו]\u0006 במשניות הללו את הלשון \u0003\"בפני הבית ושלא בפני הבית\"\u0004 — הרי זה \u0003שלא לצורך,\u0004 שהרי חובות הגוף הן, וברור שהן נוהגות אף לאחר החורבן. \u0003לבד\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004איסור \u0003\"אותו ואת בנו\",\u0004 שנצרכה לשון זו בעניינו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הואיל ובענינא\u0004 \u0005[ובענין,\u0006 בפרשת\u0005]\u0006 \u0003קדשים כתיב\u0004 \u0005[נאמר]\u0006 איסור זה (ויקרא פרק כב), מעתה יש לומר כי דווקא \u0003בזמן דאיכא\u0004 \u0005[שיש]\u0006 \u0003קדשים,\u0004 כשבית המקדש קיים — \u0003ננהוג\u0004 \u0005[ננהג]\u0006 באיסור זה, ואולם \u0003בזמן דליכא\u0004 \u0005[שאין]\u0006 \u0003קדשים,\u0004 בעת שאין בית המקדש קיים — \u0003לא ננהוג\u0004 \u0005[לא ננהג]\u0006 איסור זה, לכך \u0003קא משמע לן\u0004 \u0005[\u0006התנא \u0005משמיע לנו]\u0006 שנוהג איסור \"אותו ואת בנו\" אף בזמן שאין בית המקדש קיים.","\u0003ותרוייהו אמרי\u0004 \u0005[ושניהם אמרו]\u0006 כי \u0003כל היכא דתנן\u0004 \u0005[מקום ששנינו]\u0006 במשניות הללו \u0003\"בחולין ובמוקדשים\"\u0004 (בדין \"אותו ואת בנו\" ובדין גיד הנשה) — הרי זה \u0003לצורך,\u0004 שכן לא היינו יודעים כי נוהג דין זה אף במוקדשים אלמלא השמיעתנו כן המשנה, \u0003לבד מגיד הנשה,\u0004 שלא היה צורך להשמיענו שנוהג אף במוקדשים, שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! וכי \u0003משום דאיקדש פקע ליה\u0004 \u0005[שהוקדש פקע לו]\u0006 \u0003איסור גיד הנשה מיניה\u0004 \u0005[ממנו]?\u0006","ומקשים: \u0003ולאו אוקימנא\u0004 \u0005[והאם לא העמדנו]\u0006 (לעיל פט,ב) את דברי אותה משנה שבענין גיד הנשה שהריהי עוסקת \u0003בולדות קדשים,\u0004 ובאלה איסור מוקדשים קודם לאיסור גיד הנשה. והיה איפוא מקום לומר שאין נוהג בהם איסור גיד הנשה, שאין איסור חל על איסור, ונצרכה המשנה להשמיענו אף בגיד הנשה שהריהו נוהג במוקדשים! \u0003ו\u0004משיבים: \u0003מאי טעמא אוקימנא\u0004 \u0005[מה טעם העמדנו]\u0006 את דברי המשנה בולדות קדשים? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דקשיא לן\u0004 \u0005[שהיה קשה לנו]\u0006 על דברי המשנה ש\u0003לא ליתני\u0004 \u0005[שלא ישנה]\u0006 כלל דין זה שנוהג בחולין ובמוקדשים, שהרי זה שלא לצורך. לכך אמרו ר' אבין ור' מיישא כי קושיה זו שהיתה קשה לנו על דברי אותה משנה \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 כשסברנו שמדובר בה בבהמה שהוקדשה \u0003נמי לא תקשי\u0004 \u0005[גם כן לא יקשה]\u0006 \u0003לך,\u0004 שכן \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 התנא את הלשון \"בחולין ובמוקדשין\" \u0003לצורך\u0004 (לענין \"אותו ואת בנו\") \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 לשון זו \u0003שלא לצורך\u0004 (לענין גיד הנשה).","","שנינו במשנתנו כי מצות שילוח הקן נוהגת דווקא \u0003בחולין אבל לא במוקדשים,\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 נוהגת המצוה אף במוקדשים? ומשיבים: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"שלח תשלח את האם\"\u0004 (דברים כב, ז) — אין המדובר אלא \u0003במי\u0004 (בעוף) \u0003שאתה מצווה לשלחו,\u0004 \u0003יצא\u0004 (התמעט) \u0003זה\u0004 העוף המוקדש \u0003שאי\u0004 (שאין) \u0003אתה מצווה לשלחו אלא להביאו לידי גזבר.\u0004","\u0003אמר רבינא: הלכך\u0004 \u0005[משום כך],\u0006 לפי נימוק זה, \u0003עוף טהור\u0004 שהיה בבית ויש לו בעלים, \u0003שהרג את הנפש,\u0004 והריהו עתה חייב מיתה — \u0003פטור משלוח, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"שלח תשלח את האם\"\u0004 — דווקא \u0003במי שאתה מצווה לשלחו, יצא זה\u0004 העוף שהרג \u0003שאי אתה מצווה לשלחו אלא להביאו לבית דין.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה דבר זה]\u0006 לגבי העוף שהרג והיה רובץ על הביצים? \u0003אי דגמר דיניה\u0004 \u0005[אם ש\u0006כבר \u0005נגמר דינו\u0006 למיתה\u0005]\u0006 —"],["מהיכן נמלט העוף? שהרי \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא,\u0004 וצריך היה להרוג אותו מיד! \u0003אלא\u0004 מדובר בזמן שעדיין \u0003לא גמר דיניה, ובעי לאתוייה לבי דינא\u0004 \u0005[לא נגמר דינו, וצריך להביאו לבית הדין],\u0006 \u0003וקיומי ביה\u0004 \u0005[ולקיים בו]\u0006 את הכתוב \u0003\"ובערת הרע מקרבך\"\u0004 (דברים יג, ו).","ומבררים עתה את דברי המשנה הפוטרת את העופות המוקדשים משילוח הקן: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003מוקדשין\u0004 שהזכרנו \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 מדובר? \u0003אילימא דהוה ליה\u0004 \u0005[אם תאמר\u0006 שמדובר \u0005שהיה לו]\u0006 \u0003קן בתוך ביתו ואקדשיה\u0004 \u0005[והקדיש אותו]\u0006 — באופן זה \u0003מי מיחייב\u0004 \u0005[האם מתחייב]\u0006 הוא בשילוח? והרי בדין השילוח נאמר \u0003\"כי יקרא קן צפור\"\u0004 (דברים כב, ו) — \u0003פרט למזומן\u0004 לפניך, כגון קן זה שהיה בתוך ביתו!","\u0003אלא\u0004 תאמר שמדובר באופן \u0003דחזא\u0004 \u0005[שראה]\u0006 \u0003קן בעלמא\u0004 \u0005[סתם]\u0006 במקום שאינו שלו, \u0003ואקדשיה\u0004 \u0005[והקדישו]\u0006 — \u0003ו\u0004אף באופן זה אין להעמיד את משנתנו, שכן \u0003מי\u0004 \u0005[האם]\u0006 \u0003קדוש\u0004 הוא על ידי זה? והלא \"ו \u0003איש כי יקדיש את ביתו קדש\"\u0004 (ויקרא כז, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה].\u0006 ומכאן למדים: \u0003מה ביתו\u0004 שהוא \u0003ברשותו\u0004 של בעליו, הריהו יכול להקדישו, \u0003אף כל\u0004 דבר שהוא \u0003ברשותו\u0004 יכול אדם להקדישו. ואין הוא יכול להקדיש דבר שאינו ברשותו!","\u0003אלא\u0004 תאמר שמדובר באופן \u0003דאגבהינהו\u0004 \u0005[שהגביה אותם]\u0006 את ה\u0003אפרוחים,\u0004 וקנה אותם בכך, \u0003ו\u0004אחר כך \u0003אקדשינהו\u0004 \u0005[הקדיש אותם],\u0006 \u0003והדר הדרינהו\u0004 \u0005[ושב\u0006 ו\u0005החזיר אותם]\u0006 לקן — גם באופן זה אין להעמיד את דברי משנתנו, שכן \u0003האי\u0004 \u0005[\u0006באופן \u0005זה]\u0006 \u0003אפילו בחולין נמי לא מיחייב\u0004 \u0005[גם כן אינו חייב],\u0006 \u0003דתנא\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 החכם\u0005]\u0006 בדינו של מי ש\u0003נטל את הבנים והחזירן לקן, ואחר כך חזרה האם עליהן\u0004 בעצמה — כיון שכבר זכה בהם, הרי זה בכלל \"מזומן\", ולכך הוא \u0003פטור מלשלח!\u0004","\u0003אלא\u0004 תאמר שמדובר באופן \u0003דאגבהה\u0004 \u0005[שהגביה אותה]\u0006 את ה\u0003אם,\u0004 וזכה בה, ועמד \u0003ואקדשה\u0004 \u0005[והקדיש אותה],\u0006 \u0003והדרה\u0004 \u0005[והחזיר אותה]\u0006 לקן — גם באופן זה אין להעמיד את דברי משנתנו, שהרי כבר \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 בשעה שנזדמן לו הקן, \u0003איחייב ליה\u0004 \u0005[התחייב לו]\u0006 \u0003בשילוח,\u0004 והיה \u0003זה\u0004 \u0003מקמי דאקדשה\u0004 \u0005[לפני שהקדיש אותה].\u0006 ואין ההקדשה שנעשתה לאחר מכן מפקיעה את חיוב השילוח. וכגון זו \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוחנן בן יוסף אומר:\u0004 אדם ש\u0003הקדיש חיה, ואחר כך\u0004 עמד ו\u0003שחטה\u0004 — הריהו \u0003פטור מלכסות\u0004 את דמה. שאין דמה של חיה השייכת להקדש חייב בכיסוי הדם. ואולם אם \u0003שחטה\u0004 כאשר היא של חולין, \u0003ואחר כך\u0004 עמד ו\u0003הקדישה\u0004 — הריהו \u0003חייב לכסות\u0004 את דמה, \u0003ש\u0004כן \u0003כבר נתחייב בכסוי קודם שיבא לידי הקדש!\u0004 ואף כאן היה חיוב שילוח לפני ההקדש, ואין ההקדשה פוטרתו מחיוב זה. \u0003רב\u0004","\u0003אמר\u0004 בהסבר דברי משנתנו שמדובר בה \u0003במקדיש פירות\u0004 (גוזלות) \u0003שובכו\u0004 לקדשי מזבח (לעולת נדבה), \u0003ו\u0004אחר כך כשגדלו הגוזלות \u0003מרדו\u0004 וברחו מביתו למקום אחר, וקננו שם. ועתה שנמצאו אין הם בכלל \"מזומן\". ואילו היו של חולין, היו חייבים בשילוח. ואולם כיון שהם מוקדשים — אין הם חייבים בשילוח. \u0003ושמואל אמר\u0004 בהסבר דברי משנתנו שמדובר בה \u0003במקדיש תרנגולתו לבדק הבית,\u0004 ולאחר מכן ברחה התרנגולת מביתו, וקננה במקום אחר. והרי זו פטורה משילוח, כיון שמוקדשת היא. ואילו היתה זו של חולין, היתה חייבת בשילוח.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שמואל לא אמר כרב\u0004 בהסבר משנתנו — משום \u0003דקא מוקים לה\u0004 \u0005[שהוא מעמיד אותה,\u0006 מסביר את האופן המדובר בה\u0005]\u0006 לא רק במקדיש לקדשי מזבח אלא אפילו \u0003בקדשי בדק הבית,\u0004 שקדושת דמים היא, שאף היא פוטרת מן השילוח. \u0003אלא רב מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כשמואל?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך רב\u0004 \u0003דוקא קפטרי\u0004 \u0005[פטרתי]\u0006 \u0003משילוח כגון פירות שובכו\u0004 ש\u0003קדשי מזבח נינהו\u0004 \u0005[הם],\u0006 וטעם הדבר: ש\u0003כיון דקדשי\u0004 \u0005[שקדושים]\u0006 הם ב\u0003קדושת הגוף לא פקעה קדושתייהו מינייהו\u0004 \u0005[אין פוקעת קדושתם מהם]\u0006 אפילו כשהם בורחים. \u0003אבל במקדיש תרנגולתו לבדק הבית, דלאו\u0004 \u0005[שאין]\u0006 זו \u0003קדשי מזבח,\u0004 ש\u0003קדושת דמים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 שיש בדבר — \u0003כיון\u0004 ש\u0003מרדה פקעה קדושתייהו\u0004 \u0005[קדושתם],\u0006 \u0003וחייבת בשילוח.\u0004","\u0003ושמואל אמר:\u0004 אף על פי שברחה התרנגולת שהוקדשה לבדק הבית, הריהי עומדת בקדושתה, כי \u0003כל היכא דאיתיה\u0004 \u0005[מקום ש\u0006היא \u0005נמצאת]\u0006 בו — \u0003בבי גזא דרחמנא איתא\u0004 \u0005[בבית אוצרו של הקדוש ברוך הוא\u0006 היא \u0005נמצאת],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"לה' הארץ ומלואה\"\u0004 (תהלים כד, א). \u0003ו\u0004מעירים כי \u0003כן,\u0004 כדברי שמואל, \u0003אמר ר' יוחנן\u0004 בהסבר משנתנו שמדובר בה \u0003במקדיש תרנגולתו לבדק הבית, ומרדה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון בן לקיש\u0004 לר' יוחנן בשאלה: \u0003ו\u0004הלא \u0003כיון שמרדה, פקעה ליה\u0004 \u0005[לה]\u0006 \u0003קדושתה! אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש בתשובה: אין הקדושה פוקעת ממנה בכך, שכן \u0003בבי גזא דרחמנא איתא\u0004 \u0005[בבית האוצר של הקדוש ברוך הוא\u0006 היא \u0005נמצאת],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לה' הארץ ומלואה\".\u0004","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יוחנן\u0004 אלה על דברי \u0003ר' יוחנן\u0004 במקום אחר, \u0003ו\u0004כן \u0003רמי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' שמעון בן לקיש\u0004 אלה על דברי \u0003ר' שמעון בן לקיש\u0004 במקום אחר.","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו ר' יוחנן וריש לקיש בדינו של מי שאמר \u0003\"מנה זה לבדק הבית\", ונגנבו\u0004 המעות מביתו, \u0003או\u0004 ש\u0003נאבדו\u0004 לו — \u0003ר' יוחנן אמר\u0004 שהמקדיש \u0003חייב באחריותן\u0004 של המעות, \u0003עד שיבואו\u0004 בפועל \u0003לידי גזבר,\u0004 ולכן הריהו חייב לשלם להקדש. \u0003ו\u0004אילו \u0003ריש לקיש אמר\u0004 שאינו חייב לשלם להקדש, כיון שאף שלא ניתן המנה לגזבר, מכל מקום נחשב הדבר כמי שניתן למקדש, כי \u0003כל היכא דאיתיה\u0004 \u0005[מקום שנמצא]\u0006 בו הכסף, \u0003בבי גזא דרחמנא איתיה\u0004 \u0005[בבית אוצרו של הקדוש ברוך הוא\u0006 הוא \u0005נמצא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לה' הארץ ומלואה\".\u0004 אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ריש לקיש\u0004 האומר לענין תשלומים למקדש בגניבה או באבידה שבכל מקום בו נמצא הדבר המוקדש הריהו נמצא בבית גנזיו של ההקדש, על דברי \u0003ריש לקיש\u0004 בענין המקדיש תרנגולתו שלא סבר כן. וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יוחנן\u0004 האומר בענין תשלומים למקדש בגניבה או באבידה שכל עוד לא בא הדבר המוקדש לידי הגזבר אין זה נחשב ברשות ההקדש על דברי \u0003ר' יוחנן\u0004","\u0003ריש לקיש\u0004 על דברי \u0003ריש לקיש לא קשיא\u0004 \u0005[אינו קשה],\u0006 שכן אפשר לומר כי \u0003הא\u0004 \u0005[זה]\u0006 שאמר בענין המקדיש תרנגולתו היה \u0003מקמי דשמעיה\u0004 \u0005[לפני ששמע]\u0006 סברה זו \u0003מר' יוחנן רביה\u0004 \u0005[רבו],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר בענין תשלומים למקדש בגניבה ובאבידה היה \u0003לבתר דשמעיה\u0004 \u0005[לאחר ששמע]\u0006 סברה זו \u0003מר' יוחנן רביה\u0004 \u0005[רבו].\u0006","\u0003אלא\u0004 מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן קשיא\u0004 \u0005[קשה]!\u0006 ומשיבים: מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 שכן \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יוחנן בענין חובת התשלומים למקדש בגניבה, הרי זה כש\u0003אמר\u0004 המקדיש \"מנה זה \u0003עלי\u0004 להקדש\", ובאופן זה הריהו חייב על הגניבה והאבידה, כל עוד לא הגיע הכסף לידי הגזבר. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יוחנן בענין שילוח הקן, מדובר כש\u0003אמר\u0004 המקדיש \u0003\"הרי זו\u0004 להקדש לבדק הבית\", באופן זה אמר שלא פקעה הקדושה בבריחת התרנגולת שכן בכל מקום שהיא נמצאת קדושתה עליה.","ותוהים על הסבר זה: אם דברי ר' יוחנן בענין חובת תשלומים למקדש בגניבה נאמרו כשאמר המקדיש \"הרי עלי\", \u0003מכלל\u0004 זה נלמד כי לשיטת \u0003ר' שמעון בן לקיש\u0004 החולק עליו וסבור שאינו חייב בתשלומים, הוא הדין \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר\u0004 \"הרי \u0003עלי\",\u0004 ש\u0003לא מחייב\u0004 \u0005[אינו חייב]\u0006 לשלם אותו?","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו נדר ואיזו היא נדבה?\u0004 ומה ההבדל ביניהם? \u0003נדר\u0004 — כגון \u0003האומר \"הרי עלי עולה\", נדבה\u0004 — \u0003האומר \"הרי זו עולה\". ומה בין נדר לנדבה? נדר\u0004 — אם \u0003מתה\u0004 הבהמה \u0003או נגנבה או שאבדה, חייב באחריותה,\u0004 שהרי קיבל עליו אחריות. ואילו ב\u0003נדבה\u0004 — אם \u0003מתה או נגנבה או שאבדה, אינו חייב באחריותה!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 על כך \u0003ריש לקיש\u0004 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהאומר \"הרי עלי\" חייב באחריות, אמורים דווקא ב\u0003קדשי מזבח,\u0004 שכן נדר להביאו למקדש להקרבה, ועתה הרי זה \u0003מחוסר הקרבה. אבל קדשי בדק הבית, דלאו\u0004 \u0005[שאינו]\u0006 \u0003מחוסר הקרבה, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר\u0004 \"הרי \u0003עלי\"\u0004 — \u0003לא מחייב\u0004 \u0005[אינו חייב]\u0006 באחריותם אם נגנבו או אבדו.","ומקשים על הבחנה זו, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 בדינו של \u0003האומר \"שור זה עולה\"\u0004 או שאמר \u0003\"בית זה קרבן\",\u0004 אם \u0003מת השור\u0004 או \u0003נפל הבית\u0004 — \u0003אינו חייב באחריותן.\u0004 ואם אמר \u0003\"שור זה עלי עולה\"\u0004 או \u0003\"בית זה עלי קרבן\", מת השור\u0004 או ש\u0003נפל הבית\u0004 — \u0003חייב לשלם.\u0004 הרי איפוא שאף בקדשי בדק הבית, האומר \"הרי עלי\" חייב באחריות הדבר המוקדש!","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהאומר \"הרי עלי לבדק הבית\" חייב באחריות, אמורים דווקא \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003מת השור\u0004 או ש\u0003נפל הבית,\u0004 שבמקרים אלה הריהו \u0003חייב לשלם,\u0004 ומדוע? משום \u0003דליתנהו\u0004 \u0005[ש\u0006הם \u0005אינם נמצאים\u0006 עוד\u0005],\u0006 \u0003אבל היכא דאיתנהו\u0004 \u0005[במקום שהם\u0006 עדיין \u0005נמצאים],\u0006 כגון כסף שנגנב או שאבד, בזה אומרים אנו כי \u0003כל היכא דאיתיה, בבי גזא דרחמנא איתיה\u0004 \u0005[בכל מקום ש\u0006הוא \u0005נמצא, בבית אוצרו של הקדוש ברוך הוא\u0006 הוא \u0005נמצא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לה' הארץ ומלואה\".\u0004","למעלה הובאה מחלוקתם של ר' יוחנן וריש לקיש בדינו של האומר \"הרי עלי לבדק הבית\" אם הוא חייב באחריותו של הדבר המוקדש. ובענין זה \u0003אמר רב המנונא\u0004 כי לא נחלקו אלא בהקדש, אבל \u0003הכל מודים בערכין,\u0004 ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר\u0004 \"ערכי \u0003עלי\"\u0004 והפריש את דמי ערכו, ולאחר מכן נגנב או שאבד הכסף — \u0003לא מיחייב\u0004 \u0005[אינו חייב]\u0006 באחריותו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דלא מיתמר ליה\u0004 \u0005[שאין\u0006 הדבר \u0005יכול להיאמר לו]\u0006 באופן שונה. שהרי אין הוא יכול לומר בערכין \"הרי זה\" (שהרי עדיין לא קיבל עליו חובת ערך). כלומר, שאי אפשר לבטא את הערכים \u0003בלא\u0004 לומר את המלה \u0003\"עלי\",\u0004 ואין הכוונה שהוא מקבל עליו אחריות. כי","\u0003היכי לימא\u0004 \u0005[כיצד יאמר]\u0006 בלא \"עלי\"? אם \u0003לימא\u0004 \u0005[יאמר]\u0006 \u0003\"ערכי\"\u0004 בלבד, ובלא \"עלי\" — \u0003אמאן\u0004 \u0005[על מי]\u0006 מוטלת חובת תשלום זה הנדר? ואם \u0003לימא\u0004 \u0005[יאמר]\u0006 \u0003\"ערך פלוני\",\u0004 ובלא שאמר \"עלי\" — גם כן השאלה היא: \u0003אמאן\u0004 \u0005[על מי]\u0006 מוטל החיוב?","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: לימא\u0004 \u0005[שיאמר]\u0006 \u0003\"הריני בערכי\",\u0004 או \u0003\"הריני בערך פלוני\"\u0004 ולא יאמר \"הרי עלי\"! \u0003ועוד,\u0004 הרי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין הפודה שדה מקנה מן ההקדש, ש\u0003ר' נתן אומר\u0004 על הכתוב \"וחשב לו הכהן את מכסת הערכך עד שנת היובל \u0003ונתן את הערכך ביום ההוא קדש לה' \"\u0004(ויקרא כז, כג) — יכול היה הכתוב לומר \"ונתן אותו\" או \"ונתנו\", \u0003מה תלמוד לומר\u0004 (מלמדנו הנאמר) בכתוב החוזר \"ונתן את הערכך\"? \u0003לפי שמצינו\u0004 (שמצאנו) \u0003בהקדשות ומעשרות ש\u0004הריהם \u0003מתחללין על מעות שבחולין.\u0004 ואותן מעות אם \u0003נגנבו או שאבדו\u0004 — הבעלים \u0003אינן חייבין באחריותן,\u0004"],["מעתה \u0003יכול\u0004 יהא הדין ש\u0003אף זה\u0004 הערך \u0003כן\u0004 הוא, שאם נגנב או אבד, אין חייבים באחריותו? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"ונתן את הערכך\"\u0004 (ויקרא כז, כג) — הרי אלה \u0003חולין עד שיבאו לידי\u0004 ה\u0003גזבר,\u0004 ולכן יש עליו התחייבות. הרי איפוא שגם בערכין הריהו חייב באחריותם, ושלא כדברי רב המנונא!","\u0003אלא, אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר],\u0006 בלשון זו \u0003אמר רב המנונא: הכל מודים בערכין, דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא אמר\u0004 \"הרי \u0003עלי\"\u0004 — הריהו \u0003מיחייב\u0004 \u0005[חייב]\u0006 באחריותם, וטעם הדבר: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ונתן את הערכך\"\u0004 — לומר: \u0003חולין הן בידך עד שיבאו לידי גזבר.\u0004","שנינו במשנתנו כי יש \u0003חומר\u0004 (חומרה) \u0003ב\u0004דין \u0003כסוי\u0004 שאינה קיימת בדין שילוח הקן. שהרי כיסוי הדם נוהג בין בחיה ובין בעוף, וכמו כן הריהו נוהג בין בבעל חיים המזומן לפניו ובין בזה שאינו מזומן, ואילו מצות שילוח הקן אינה נוהגת אלא בעוף ולא בחיה, ודווקא בעוף שאינו מזומן לפניו. ובענין זה מביאים עוד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 על הנאמר בשני פסוקי פרשיית שילוח הקן \u0003\"כי יקרא קן צפור לפניך\u0004 בדרך בכל עץ או על הארץ אפרוחים או ביצים והאם רובצת על האפרוחים או על הביצים לא תקח האם על הבנים. שלח תשלח את האם ואת הבנים תקח לך (דברים כב, ו— ז): \u0003מה תלמוד לומר\u0004 (מלמדנו הנאמר) בכתוב זה בפרטיו? ומסבירים:","\u0003לפי שנאמר\u0004 בפסוק השני \u0003\"שלח תשלח את האם ואת הבנים תקח לך\",\u0004 ובא כפל הלשון \"שלח תשלח\" להורות על השתדלותו היתירה של האדם בקיום מצוה זו — \u0003יכול\u0004 יהא הדין שצריך האדם ש\u0003יחזור\u0004 (יסתובב) \u0003בהרים וגבעות\u0004 בחיפושים אחר קן, \u0003כדי שימצא קן\u0004 ויקיים מצוה זו? לכך \u0003תלמוד לומר\u0004 בתחילת הפרשייה \u0003\"כי יקרא\"\u0004 — רק \u0003ב\u0004קן ה\u0003מאורע\u0004 (שהזדמן) \u0003לפניך\u0004 נאמרה המצוה, ואין אדם צריך לחפש אחר קן לקיים מצווה זו.","ומן הכתוב \u0003\"קן\"\u0004 למדים אנו כי המצוה נאמרה בקן \u0003מכל מקום\u0004 (כל שהוא), שאף בזה שיש בו רק אפרוח אחד או ביצה אחת אמורים הדברים. ומן הכתוב \u0003\"צפור\"\u0004 למדים אנו כי המצוה נאמרה דווקא בצפור \u0003טהורה ולא\u0004 ב\u0003טמאה.\u0004 ועוד, מן הכתוב \u0003\"לפניך\"\u0004 יש ללמוד כי נוהגת המצוה בקן המזדמן \u0003ברשות היחיד,\u0004 כגון פרדס ושדה שאינם שמורים (שאין הקן הנמצא בהם נקנה לבעלי הפרדס והשדה). ובא הכתוב \u0003\"בדרך\"\u0004 ללמדנו כי נוהגת המצוה בקן הנמצא \u0003ברשות הרבים.\u0004 ובאשר לדינו של הקן הנמצא \u0003באילנות מנין\u0004 לנו שאף הוא בכלל המצוה? לכך \u0003תלמוד לומר\u0004 \u0003\"בכל עץ\".\u0004 ובדינו של קן הנמצא \u0003בבורות שיחין ומערות מנין\u0004 לנו שאף הוא חייב בשילוח? לכך \u0003תלמוד לומר \"או על הארץ\"\u0004 שחייב הקן בכל האופנים בו הוא נמצא על הארץ.","ושואלים: \u0003וכי מאחר שסופנו לרבות כל דבר,\u0004 שמן הכתוב \"בכל עץ או על הארץ\" למדים שחייבים בשילוח הקן בכל האופנים, מעתה תחילת הכתוב \u0003\"לפניך בדרך\" למה לי?\u0004 ומשיבים: \u0003לומר לך: מה דרך\u0004 מתאפיינת היא בכך \u0003שאין קנו בידך\u0004 (שאינו מזומן ואינו קנוי לך), \u0003אף כל\u0004 אופן אחר הריהו חייב בשילוח הקן דווקא בזמן \u0003שאין קנו בידך, מכאן אמרו\u0004 חכמים כי \u0003יוני שובך ויוני עלייה שקננו בטפיחין\u0004 (בכוכים קטנים בקירות) \u0003ובבירות\u0004 (דירות ומגדלי עיר), \u0003ואווזין ותרנגולין שקננו בפרדס\u0004 — \u0003חייב בשילוח,\u0004 שאין כל אלה בכלל \"קנו בידך\". \u0003אבל\u0004 אם \u0003קננו בתוך הבית, וכן יוני הרדסיאות\u0004 — הריהו \u0003פטור משילוח.\u0004","ומבררים את דברי הברייתא, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003מה דרך שאין קנו בידך, אף כל שאין קנו בידך.\u0004 ושואלים: \u0003הא\u0004 \u0005[\u0006לימוד \u0005זה]\u0006 \u0003למה לי?\u0004 והלוא \u0003מ\"כי יקרא\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד הדבר\u0005],\u0006 שהביטוי \u0003\"כי יקרא\"\u0004 כוונתו \u0003פרט למזומן!\u0004 ומוסיפים: \u0003ועוד, \"לפניך\" למה לי?\u0004","\u0003אלא\u0004 הכתוב \u0003\"לפניך\"\u0004 בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את אלה \u0003שהיו\u0004 בתחילה \u0003לפניך ו\u0004אחר כך \u0003מרדו\u0004 וברחו למקום אחר, ושם קיננו. ומה שנאמר \u0003\"בדרך\"\u0004 — הרי זה בא ללמד \u0003כ\u0004דברי \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003רב,\u0004 שכן \u0003אמר רב יהודה אמר רב: מצא קן בים,\u0004 וכגון ששטף הים את האילן, והיה קן בראש האילן — הריהו \u0003חייב בשילוח,\u0004 וטעם הדבר, \u0003ש\u0004כן \u0003נאמר \"כה אמר ה' הנותן בים דרך\u0004 ובמים עזים נתיבה\" (ישעיה מג, טז), הרי שהלשון \"דרך\" משמשת אף בים.","ושואלים: \u0003אלא מעתה\u0004 אם \u0003מצא קן\u0004 פורח \u0003בשמים,\u0004 וכגון עוף הנושא קן באויר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בעוף \u0003\"דרך\u0004 ה\u0003נשר בשמים\"\u0004 (משלי ל, יט), \u0003הכי נמי דמיחייב\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הוא \u0005חייב]\u0006 \u0003בשילוח הקן!\u0004 ומשיבים: אין זו קושיה, כי באשר לשמים, \u0003\"דרך נשר\" איקרי\u0004 \u0005[נקרא],\u0006 ואילו \u0003\"דרך\" סתמא לא איקרי\u0004 \u0005[סתם אינו נקרא],\u0006 אבל דרך בים נקראת \"דרך\" סתם.","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003פפונאי\u0004 (בני המקום הנקרא פפוניא) \u0003לרב מתנה:\u0004 מי ש\u0003מצא קן בראשו של אדם מהו\u0004 לענין שילוח הקן, האם אף זה בכלל הכתוב \"על הארץ\"? \u0003אמר\u0004 להם בתשובה: הריהו חייב בשילוח, שכן נאמר \u0003\"ואדמה על ראשו\"\u0004 (שמואל ב טו, לב), ולא אמר \"ועפר על ראשו\", ללמד שנחשב הדבר כאדמה, והריהו כאילו אמר על הארץ. ועוד שאלו אותו: \u0003משה\u0004 רבינו \u0003מן התורה\u0004 קודם שנולד, \u0003מנין\u0004 לנו שסופו לבוא לאחר מכן? השיב להם רב מתנה: שכן נרמז בכתוב \"ויאמר ה' לא ידון רוחי באדם לעולם \u0003בשגם הוא בשר\u0004 והיו ימיו מאה ועשרים שנה\" (בראשית ו, ג), והמלה \"בשגם\" היא בגימטריא \"משה\", ואכן משה חי מאה ועשרים שנה, כנאמר בפסוק זה.","ועוד שאלו את רב מתנה: רמז למעשה שאירע ב\u0003המן מן התורה מנין\u0004 לנו? השיב להם: שכן נאמר לאחר חטא עץ הדעת \u0003\"המן העץ\u0004 אשר ציויתיך לבלתי אכל ממנו אכלת\" (שם ג, יא).","ועוד שאלוהו רמז למעשה \u0003אסתר מן התורה מנין\u0004 לנו? השיב להם: שכן נאמר \"וחרה אפי בו ביום ההוא ועזבתים והסתרתי פני מהם והיה לאכול ומצאוהו רעות רבות וצרות ואמר ביום ההוא הלא על כי אין אלהי בקרבי מצאוני הרעות האלה. \u0003ואנכי הסתר אסתיר\u0004 פני ביום ההוא על כל הרעה אשר עשה כי פנה אל אלהים אחרים\" (דברים לא, יז— יח). ועוד שאלו פפונאי את רב מתנה: רמז ל\u0003מרדכי מן התורה מנין\u0004 לנו? השיב להם: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדרך עשיית שמן המשחה \"ואתה קח לך בשמים ראש \u0003מר דרור\"\u0004 (שמות ל, כג), \u0003ומתרגמינן\u0004 \u0005[ואנו מתרגמים]:\u0006 \u0003מירא דכיא,\u0004 והרי זה כשם \"מרדכי\".","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003איזהו\u0004 קן הנחשב כמי \u0003שאינו מזומן?\u0004 כגון אווזים ותרנגולים שקננו בפרדס. אבל אם קננו בבית, וכן יוני הרדסיאות הריהו פטור משילוח. ובענין יוני הרדיסאות מביאים מדברי \u0003ר' חייא ור' שמעון, חד תני\u0004 \u0005[אחד\u0006 מהם \u0005היה שונה]\u0006 במשנתנו את הלשון \"יוני \u0003הדרסיאות\", וחד תני\u0004 \u0005[ואחד\u0006 מהם \u0005היה שונה]\u0006 את הלשון \"יוני \u0003הרדסיאות\".\u0004 ומסבירים: \u0003מאן דתני\u0004 \u0005[מי שהיה שונה]\u0006 \"יוני \u0003הרדסיאות\"\u0004 — \u0003על שם הורדוס,\u0004 המלך, שהתעסק בגידול יונים אלה, ולכך נקראו על שמו. \u0003ומאן דתני\u0004 \u0005[ומי שהיה שונה]\u0006 \"יוני \u0003הדרסיאות\"\u0004 — נקראו כן היונים \u0003על שם מקומן.\u0004","\u0003אמר רב כהנא: לדידי חזיין\u0004 \u0005[אני עצמי ראיתי אותן,\u0006 את היונים הללו\u0005],\u0006 \u0003וקיימן שיתסר דרי בפתי מילא\u0004 \u0005[והיו עומדות\u0006 ב\u0005שש עשרה שורות ברוחב מיל],\u0006 \u0003והוה קרא \"קירי, קירי\"\u0004 \u0005[והיו קוראות \"אדוני, אדוני\"].\u0006 \u0003הוה חד מינייהו דלא הוה קרי \"קירי, קירי\"\u0004 \u0005[היתה אחת מהן שלא היתה קוראת \"אדוני, אדוני\"],\u0006 \u0003אמרה לה חברתה: סומא\u0004 \u0005[עיוורת,\u0006 טיפשה\u0005],\u0006 \u0003אמרי \"קירי, קירי\"\u0004 \u0005[\"אדוני, אדוני\"],\u0006 שלא תיענשי על שאין את מקבלת אדנותו של המלך! \u0003אמרה\u0004 לה האחרת: \u0003סומא\u0004 \u0005[עיוורת,\u0006 טיפשה\u0005],\u0006 \u0003אמרי\u0004 את \u0003\"קירי בירי\"\u0004 \u0005[\"אדוני, עבדי\"],\u0006 שאין זה המלך אלא עבד הוא. \u0003אתיוה\u0004 \u0005[הביאוה]\u0006 \u0003ושחטוה,\u0004 משום שדיברה כנגד המלך.","\u0003אמר רב אשי, אמר לי ר' חנינא:\u0004 אלה \u0003מילין\u0004 \u0005[דברים\u0006 סתם\u0005],\u0006 דברי הבאי, שלא היה כן. ותוהים על דבריו: \u0003מילין סלקא דעתך\u0004 \u0005[דברים\u0006 סתם \u0005יעלה על דעתך]\u0006 לומר על דברי רב כהנא המעיד שכך ראה בעצמו? \u0003אלא\u0004 כך \u0003אימא\u0004 \u0005[אמור]\u0006 את דברי ר' חנינא: \u0003במילין\u0004 \u0005[בכשפים]\u0006 נעשו הדברים על ידי היונים הללו.","ועוד שנינו במשנתנו כי \u0003עוף טמא פטור מלשלח.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' יצחק:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במצות שילוח הקן \u0003\"כי יקרא קן צפור לפניך\",\u0004 ולא נאמר \"כי יקרא קן עוף לפניך\", כי \u0003\"עוף\" משמע לן\u0004 \u0005[משמעו,\u0006 שימוש הלשון \u0005לנו]\u0006 הוא \u0003בין\u0004 זה שהוא \u0003טהור בין\u0004 זה שהוא \u0003טמא.\u0004 בעוד שהמלה \"\u0003צפור\"\u0004 — במובן של עוף \u0003טהור אשכחן דאיקרי\u0004 \u0005[מצאנו שנקרא]\u0006 \u0003\"צפור\",\u0004 אך במובן של עוף \u0003טמא לא אשכחן דאיקרי\u0004 \u0005[לא מצאנו שנקרא]\u0006 \u0003\"צפור\".\u0004","ודנים בקביעה זו, \u0003תא שמע \u0004\u0005[בוא \u0006ו\u0005שמע] \u0006ממה ששנינו על הכתוב באזהרה על עשיית פסל \u0003\"תבנית כל צפור כנף\"\u0004 (דברים ד, יז), \u0003מאי לאו \u0004\u0005[האם לא] \u0006כוונת הפסוק בכפל הלשון \"צפור כנף\" לומר \u0003\"צפור\" \u0004— \u0003בין \u0004עוף \u0003טהור בין \u0004עוף \u0003טמא, \"כנף\" \u0004— בא לרבות גם \u0003חגבים, \u0004ושלא כדברי ר' יצחק! ודוחים: \u0003לא, \u0004כוונת כפל הלשון לומר כי \u0003\"צפור\"\u0004 — הכוונה לעוף \u0003טהור, \"כנף\"\u0004 — הכוונה לעוף \u0003טמא וחגבים.\u0004","ומציעים עוד: \u0003תא שמע \u0004\u0005[בוא \u0006ו\u0005שמע] \u0006ראיה בענין זה מן הכתוב המכריז על ההלל לה' הבא מכל היקום \u0003\"החיה וכל בהמה רמש וצפור כנף\"\u0004 (תהלים קמח, י), \u0003מאי לאו \u0004\u0005[האם אין] \u0006הכוונה בכפל הלשון \"צפור כנף\" לומר כי \u0003\"צפור\" \u0004— עוף \u0003בין טהור בין טמא, ו\"כנף\" \u0004— הכוונה ל\u0003חגבים, \u0004ושלא כדברי ר' יצחק! ודוחים: \u0003לא,\u0004 כוונת כפל הלשון לומר כי \u0003\"צפור\"\u0004 — עוף \u0003טהור, \"כנף\"\u0004 — עוף \u0003טמא וחגבים.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה בענין זה ממה ששנינו על הפסוק הנאמר בבאים לתיבת נח \u0003\"כל צפור כל כנף\"\u0004 (בראשית ז, יד), \u0003מאי לאו כדמקשינן\u0004 \u0005[האם לא כמו שהקשינו\u0006 מקודם\u0005],\u0006 ש\"צפור\" משמעו בין עוף טהור ובין עוף טמא, ו\"כנף\" משמעו חגבים. ומשיבים: \u0003לא,\u0004 כוונת הפסוק \u0003כדמשנינן\u0004 \u0005[כמו שתירצנו\u0006 מקודם\u0005]\u0006 ש\"ציפור\" משמעו דווקא עוף טהור, ו\"כנף\" משמעו עוף טמא וחגבים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה בדבר ממה ששנינו על הכתוב במלחמת גוג ומגוג לעתיד לבוא \u0003\"ואתה בן אדם\u0004 כה אמר ה' אלקים \u0003אמור לצפור כל כנף\u0004 ולכל חית השדה הקבצו ובואו\" (יחזקאל לט, יז), \u0003מאי לאו כדאקשינן\u0004 \u0005[האם לא כמו שהקשינו\u0006 מקודם\u0005],\u0006 ש\"צפור\" משמעו בין עוף טהור ובין עוף טמא, ו\"כנף\" משמעו חגבים. ומשיבים: \u0003לא,\u0004 כוונת הפסוק \u0003כדמשנינן\u0004 \u0005[כמו שתירצנו\u0006 מקודם\u0005]\u0006 ש\"ציפור\" משמעו דווקא עוף טהור, ו\"כנף\" משמעו עוף טמא וחגבים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה בדבר ממה ששנינו על הכתוב"],["\u0003\"ובענפוהי ידורן צפרי שמיא\"\u0004 \u0005[ובענפיו יתגוררו ציפורי שמים]\u0006 (דניאל ד, ט), ולא נאמר בפסוק זה \"ציפור כנף\" אלא \"ציפור\" בלבד, וודאי הוא שאף עוף טמא בכלל זה, שהרי גם עופות טמאים דרים בענפי העץ. ושלא כדברי ר' יצחק! ודוחים: אין בכך לדחות את דברי ר' יצחק, שאמנם עופות טמאים \u0003\"צפרי שמיא\" איקרו\u0004 \u0005[\"ציפורי שמים\"\u0006 הם \u0005נקראים],\u0006 ואולם \u0003\"צפרי\" סתמא לא איקרו\u0004 \u0005[\"ציפורים\" סתם\u0006 הם \u0005אינם נקראים].\u0006","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לענין זה מן הכתוב בפרשת המותרים והאסורים באכילה \u0003\"כל צפור טהורה\"\u0004 (דברים יד, יא) — מתוך שנזקק הכתוב לומר \"ציפור טהורה\" \u0003מכלל\u0004 הדברים נלמד \u0003דאיכא\u0004 \u0005[שיש]\u0006 בכלל \"ציפור\" גם ה\u0003טמאה,\u0004 ושלא כדברי ר' יצחק! ודוחים: \u0003לא,\u0004 אלא כך יש לדייק:","\u0003מכלל\u0004 הדברים נלמד \u0003דאיכא\u0004 \u0005[שיש]\u0006 ציפור שאף שהיא טהורה מכל מקום היא \u0003אסורה\u0004 באכילה. ותוהים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה ציפור טהורה האסורה, שנצרך הכתוב ללמדנו מתוך דיוק לשונו שהיא אסורה? \u0003אי\u0004 \u0005[אם]\u0006 המדובר בציפור \u0003טרפה,\u0004 שנפגעה באופן שעומדת למות — אין צורך לדרשה זו, שכן \u0003בהדיא כתיב\u0004 \u0005[במפורש נאמר]\u0006 הדבר (\"נבלה וטרפה לא יאכל לטמאה בה\". ויקרא כב, ח). \u0003ואי\u0004 \u0005[ואם]\u0006 המדובר \u0003ב\u0004ציפור ה\u0003שחוטה\u0004 של \u0003מצורע,\u0004 שאף שהיא ממין טהור, אבל אסורה באכילה — אף בזו אין צורך לדרשה מיוחדת שתשמיענו כן, שהרי \u0003מסיפא דקרא נפקא\u0004 \u0005[מסופו,\u0006 המשכו \u0005של המקרא\u0006 שבספר דברים \u0005יוצא,\u0006 נלמד\u0005]\u0006 הדבר, שכן נאמר \u0003\"וזה אשר לא תאכלו מהם\"\u0004 (דברים שם יב) — \u0003לרבות\u0004 אף את הציפור \u0003שחוטת\u0004 ה\u0003מצורע\u0004 שאסורה באכילה! ומשיבים: \u0003לעולם\u0004 הכתוב \"כל צפור טהורה תאכלו\" בא ללמדנו \u0003ב\u0004דינה של הציפור ה","\u0003שחוטה\u0004 של \u0003מצורע, ו\u0004להשמיענו שיש באכילת ציפור שחוטה של מצורע \u0003לעבור עליו בעשה\u0004 (איסור אכילה הנלמד ממצות עשה, \"תאכלו\") \u0003ובלא תעשה\u0004 (\"וזה אשר לא תאכלו\"). \u0003ו\u0004מקשים: באותו אופן יכולים אנו \u0003לוקמה\u0004 \u0005[להעמיד אותה,\u0006 את \u0005המיעוט הנלמד מ\"כל צפור טהורה תאכלו\"\u0006\u0005]\u0006 \u0003בטרפה,\u0004 אף שכבר נאמר איסור אכילה זה כאיסור לא תעשה (\"נבלה וטרפה לא יאכל\"), \u0003ולעבור עליו\u0004 באכילת טריפה \u0003בעשה ולא תעשה!\u0004 ומשיבים: יש להעמיד את דרשת הכתוב בציפור השחוטה של מצורע, שכן הוא \u0003דבר הלמד מענינו, ובענינא\u0004 \u0005[ובענין]\u0006 של \u0003שחוטה כתיב\u0004 \u0005[נאמר]\u0006 \"כל צפור טהורה תאכלו\", ואין להעמידה בטריפה, שאינה שחוטה.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת בענין זה מן הכתוב בטהרת המצורע \"ולקח למטהר \u0003שתי צפרים חיות\u0004 טהורות\" (ויקרא יד, ד), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חיות\",\u0004 שהרי ברור שהן חיות בטרם נשחטה האחת והשניה נשלחת? \u0003לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003שחיות בפיך,\u0004 כלומר, שאתה יכול לאכול אותן. ו\u0003מכלל\u0004 הדברים נסיק \u0003דאיכא לאו\u0004 \u0005[שיש\u0006 כאלה ש\u0005אינן]\u0006 \u0003חיות בפיך,\u0004 כלומר, שהן אסורות באכילה, משום שטמאות הן. הרי איפוא שבא הלשון \"ציפורים\" גם בעופות טמאים, ושלא כדברי ר' יצחק! ודוחים: \u0003לא,\u0004 אין פירוש הלשון \"חיות\" אלה המותרות באכילה, אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חיות\"? שחיין ראשי אברים שלהן,\u0004 ולמעט עופות המחוסרים אבר, שאין הם כשרים לשמש למצורע, ובעופות ממין טהור בלבד מדובר.","ומציעים עוד ראיה, \u0003תא שמע מסיפא\u0004 \u0005[בא\u0006 ו\u0005שמע\u0006 ראיה בדבר \u0005מסוף\u0006 הכתוב\u0005],\u0006 שכן נאמר בו \"שתי צפרים חיות טהורות\", ובאה הלשון \u0003\"טהורות\"\u0004 ללמדנו \u0003מכלל\u0004 הדברים \u0003דאיכא\u0004 \u0005[שיש]\u0006 ציפורים אחרות שאין הן טהורות אלא \u0003טמאות,\u0004 ושלא כדברי ר' יצחק! ודוחים: \u0003לא,\u0004 כך הוא דיוקו של הכתוב, \u0003מכלל\u0004 הדברים נלמד \u0003דאיכא\u0004 \u0005[שיש]\u0006 ציפורים אחרות שהן \u0003טרפות,\u0004 ואולם הריהן ממין טהור. שאלמלא כן, לא היו נקראות \"ציפורים\".","ותוהים על הסבר זה: והרי \u0003טרפות\u0004 \u0003מ\u0004הכתוב \u0003\"חיות\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006 \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 כי ה\u0003טרפה חיה\u0004 (יכולה היא שתחיה), ולכן צריך לימוד מיוחד להשמיענו שאין הציפור הטריפה כשרה לשמש כציפור המצורע. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי ה\u0003טרפה אינה חיה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003ועוד\u0004 יש להקשות כי \u0003בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שה\u0003טרפה חיה, בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי טריפה \u0003אינה חיה,\u0004 אין אנו נצרכים לכתוב \"טהורות\" כדי ללמדנו שציפור טריפה פסולה לשמש למצורע, שהרי דבר זה \u0003מדתנא דבי\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 חכם \u0005בית]\u0006 מדרשו של \u0003ר' ישמעאל נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006","\u0003דתנא דבי\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 חכם \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: נאמר\u0004 בתורה במכלול דיני הקרבנות דינו של הקרבן ה\u0003מכשיר\u0004 את האדם לאכול מן הקדשים (כאשם מצורע וחטאות שמביאים הזבים והיולדות לאחר טומאתם כדי להכשירם לאכול בקדשים), \u0003ו\u0004כן נאמר דינו של הקרבן ה\u0003מכפר\u0004 על האדם מעבירות שעבר (כקרבנות החטאות והאשמות השונים), והרי אלה הקרבנות נעשים \u0003בפנים\u0004 המקדש, בעזרה. \u0003ו\u0004כמו כן \u0003נאמר\u0004 בתורה במכלול דיני הקרבנות גם דיניהם של הקרבן ה\u0003מכשיר ו\u0004הקרבן ה\u0003מכפר\u0004 שנעשים \u0003בחוץ\u0004 למקדש, כציפורי מצורע הבאים להשלמת טהרתו וכשעיר המשתלח ביום הכיפורים.","ומעתה נקיש: \u0003מה\u0004 הקרבן ה\u0003מכשיר ו\u0004ה\u0003מכפר האמור בפנים\u0004 — \u0003עשה\u0004 (נקבע) \u0003בו\u0004 שיהא דינו של הקרבן ה\u0003מכשיר כ\u0004דינו של הקרבן ה\u0003מכפר,\u0004 שגם אימורי הקרבנות המכשירים קרבים על המזבח. \u0003אף\u0004 בקרבן \u0003ה\u0004\u0003מכשיר ו\u0004בקרבן ה\u0003מכפר האמור בחוץ\u0004 — \u0003עשה בו מכשיר כמכפר,\u0004 וכשם שבעל מום אינו כשר בשעיר המשתלח, כן אין הוא כשר בציפורי מצורע. ואין אנו צריכים לדרשת הכתוב \"טהורות\" כדי ללמדנו כן!","\u0003אלא אמר רב נחמן בר יצחק:\u0004 הכתוב \"טהורות\" בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003צפורי עיר הנדחת\u0004 שדינה של עיר זו לשריפה, ואין הציפורים שבה כשרות לשמש למצורע. ומבררים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ציפור\u0005]\u0006 משתי ציפורי המצורע כוונת הדברים, שכן \u0003אי\u0004 \u0005[אם]\u0006 הכוונה לציפור הנועדה \u0003לשילוח\u0004 — אין צורך בדרשת הכתוב לכך, שהרי \u0003לא אמרה תורה שלח\u0004 את ציפור המצורע \u0003לתקלה,\u0004 שיכשלו בה בני אדם, שהרי ציפור עיר הנדחת אסורה באכילה, ואם תישלח כציפור מצורע, עלולים בני אדם לצוד אותה לאוכלה ולהיכשל באכילה אסורה. \u0003אלא\u0004 הכוונה לציפור המצורע המיועדת \u0003לשחיטה.\u0004","\u0003רבא אמר\u0004 כי הכתוב \"טהורות\" בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שלא לזווג\u0004 (לצרף) \u0003לה\u0004 לציפור המיועדת להשתלח אחר שנטהר מצורע זה, ציפור \u0003אחרת\u0004 המיועדת לשחיטה לטהרת מצורע אחר, \u0003קודם שלוחיה.\u0004 ומבררים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 היה מקום לומר שיצרפו את הציפור המשתלחת של מצורע זה לציפור של מצורע אחר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003שחיטה,\u0004 שתישחט הציפור של מצורע זה המיועדת להשתלח לציפור המשתלחת של מצורע אחר, והיא תישחט — ברור הדבר שאין לעשות כן, שכן \u0003הא בעיא\u0004 \u0005[הרי\u0006 הא \u0005צריכה]\u0006 \u0003שילוח! אלא\u0004 הכוונה היא \u0003לשילוח,\u0004 לשמש כציפור המשתלחת גם עבור מצורע אחר. ולכך בא הכתוב \"טהורות\" ללמדנו כי לענין אחר הריהי אסורה.","\u0003רב פפא אמר\u0004 הסבר אחר לשאלה מה בא הכתוב \"טהורות\" למעט: \u0003ל\u0004ענין \u0003צפורים שהחליפו\u0004 עם הגוי \u0003ב\u0004תמורה ל\u0003עבודה זרה,\u0004 שמכר היהודי לגוי עבודה זרה, ונתן לו הגוי תמורתה ציפורים אלה. וטעם הדבר שנאסרו לשמש כצפרי מצורע, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 באיסור עבודה זרה \"ולא תביא תועבה אל ביתך \u0003והיית חרם כמוהו\"\u0004 (דברים ז, כו), לומר: \u0003כל מה שאתה מהייה\u0004 (קונה ומקבל) \u0003הימנו,\u0004 הרי הוא \u0003כמוהו,\u0004 ומבררים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 נאמר מיעוט זה בציפורי מצורע, \u0003אי\u0004 \u0005[אם]\u0006 לענין הציפור המיועדת \u0003לשילוח\u0004 — אין צורך בדרשה מיוחדת שתלמדנו שאין להשתמש בציפור שכזו כציפור משתלחת, שהרי \u0003לא אמרה תורה שלח לתקלה! אלא\u0004 הכוונה היא לציפור המיועדת \u0003לשחיטה.\u0004","ו\u0003רבינא אמר\u0004 הסבר אחר לשאלה מה בא הכתוב \"טהורות\" למעט: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בעוף שהרג את הנפש,\u0004 שחייב מיתה, ופסול הוא לשמש כציפור מצורע. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 שכבר \u0003גמר דינא\u0004 \u0005[נגמר הדין]\u0006 שפסקו בו בית דין את דינו — \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא,\u0004 וברור הוא שאין להשתמש בו לצפרי מצורע! \u0003אלא\u0004 מדובר \u0003קודם גמר דינא\u0004 \u0005[הדין],\u0006 \u0003ולמאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 נאמר מיעוט זה בציפורי מצורע, \u0003אי\u0004 \u0005[אם]\u0006 לענין הציפור המיועדת \u0003לשילוח\u0004 — אין צורך בדרשה מיוחדת שתלמדנו שאין להשתמש בציפור שכזו כציפור משתלחת, שהרי \u0003בעי לאתויי לבי דינא וקיומי\u0004 \u0005[צריך להביא אותו לבית הדין ולקיים\u0006 בו\u0005]\u0006 את הכתוב \u0003\"ובערת הרע מקרבך\"\u0004 (שם יג, ו)! \u0003אלא\u0004 הכוונה היא לציפור המיועדת \u0003לשחיטה.\u0004","שנינו במשנתנו ש\u0003עוף טמא\u0004 ה\u0003רובץ על ביצי עוף טהור\u0004 וכן עוף טהור הרובץ על ביצי עוף טמא, שבזה ובזה פטורים מלשלח את האם. ודנים בדבר: \u0003בשלמא\u0004 \u0005[נניח,\u0006 הדבר \u0005מובן\u0006\u0005]\u0006 בדינו של \u0003עוף טמא\u0004 ה\u0003רובץ על ביצי\u0004 עוף \u0003טהור,\u0004 שאין בו מצות שילוח הקן, כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה האם המשתלחת בכלל \u0003\"צפור\",\u0004 ככתוב \"כי יקרא קן צפור לפניך\" (דברים כב, ו), \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי העוף הטמא אינו בכלל \"ציפור\". \u0003אלא עוף טהור\u0004 ה\u0003רובץ על ביצי עוף טמא,\u0004 מדוע אין בו מצות שילוח, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"צפור\" הוא!\u0004","ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב כהנא\u0004 בענין אחר בפירוש הכתוב האמור בשילוח הקן \"ואת הבנים \u0003תקח לך\"\u0004 (שם ז) — כוונתו שתהא לקיחת הבנים ראויה לך, שיכול אתה לאוכלם, \u0003ולא\u0004 אמר הכתוב מצוה בלקיחה שאינה ראויה אלא \u0003לכלביך, הכא נמי\u0004 \u0005[כאן\u0006 בענין עוף טהור הרובץ על ביצי עוף טמא \u0005גם כן]\u0006 יש לדרוש: \u0003\"תקח לך\"\u0004 — \u0003ולא לכלביך,\u0004 ומאחר ואין ביצי העוף הטמא ראויות לאכילת האדם, אין בקן זה מצות שילוח הקן.","\u0003ו\u0004מסבירים: \u0003היכא איתמר\u0004 \u0005[היכן\u0006 בתחילה \u0005נאמרו]\u0006 דבריו אלה של \u0003רב כהנא?\u0004 — \u0003אהא דתניא\u0004 \u0005[על\u0006 הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0005גם\u0006 \u0003אם\u0004 היתה האם \u0003טרפה,\u0004 העומדת למות — \u0003חייב בשילוח\u0004 האם. ואולם אם היו ה\u0003אפרוחים טרפות\u0004 — \u0003פטור משילוח.\u0004 ודנו בהלכה זו שבברייתא: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ו\u0003אמר רב כהנא,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"תקח לך\"\u0004 — \u0003ולא לכלביך.\u0004 ומאחר ואין האפרוחים שהם עצמם טריפה ראויים לאכילת האדם, אלא רק לאכילת הכלבים, לכך אין נוהגת בקן זה מצות שילוח הקן.","ומקשים: \u0003ולהקיש\u0004 \u0005[ונקיש,\u0006 נשווה\u0005]\u0006 את דין ה\u0003אם\u0004 ה\u0003טרפה ל\u0004דין ה\u0003אפרוחים\u0004 הטריפות, ונאמר: \u0003מה\u0004 במקרה של \u0003אפרוחים טרפות\u0004 — הריהו \u0003פטור משילוח, אף\u0004 במקרה של \u0003אם טרפה נמי\u0004 \u0005[גם כן]\u0006 — הריהו \u0003פטור מלשלח!\u0004"],["ומשיבים: \u0003אם כן\u0004 היה הדין, מעתה הכתוב \u0003\"צפור\"\u0004 הבא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003עוף טמא למה לי?\u0004 שהרי אף הלכה זו שעוף טמא פטור משילוח הקן ניתן להסיקה מתוך ההיקש בין אם לאפרוחים, שכשם שאפרוחים טמאים אין נוהגת מצות שילוח הקן, כך אין היא נוהגת באם טמאה. ומעתה שנצרכים אנו ללימוד מיוחד לענין האם שהיא עוף טמא, הרי זה מלמד שאין מקישים אם לאפרוחים. ושואלים על דברי רב כהנא:","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בדינה של \u0003אם אפרוחין טרפה\u0004 שהריהו \u0003חייב בשילוח,\u0004 ונראים דברי הברייתא כמדברים באם של אפרוחים טריפה, שלא כרב כהנא האומר שאין מצות שילוח הקן נוהגת באפרוחים שאינם ראויים לאכילת אדם! \u0003אמר אביי\u0004 בתשובה: אין זו כוונת דברי הברייתא, אלא \u0003הכי קאמר\u0004 \u0005[כך אומרת]\u0006 הברייתא בדינה של \u0003אפרוח שאמן טרפה\u0004 שהריהו \u0003חייב בשילוח.\u0004 וכשיטת רב כהנא, שהרי האפרוחים ראויים לאכילת אדם.","מקודם הובאו דברי רב כהנא בדרשת \"תקח לך\" ולא לכלביך, ובענין זה מביאים מה ש\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הושעיא:\u0004 אדם ש\u0003הושיט\u0004 את \u0003ידו לקן\u0004 שיש בו אם ואפרוחים, \u0003ושחט מיעוט סימנים\u0004 של האפרוחים, \u0003מהו\u0004 הדין לענין מצות שילוח הקן?","וצדדי הספק: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כיון\u0004 ש\u0003אילו שביק להו מטרפי\u0004 \u0005[היה מניח אותם\u0006 את האפרוחים במצב זה של סימנים החתוכים במקצתם, הם \u0005היו נטרפים,\u0006 ואסורים באכילה\u0005]\u0006 — הריהו פטור משילוח הקן, שכן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיתקיים בקן \"תקח \u0003לך\" ולא לכלביך,\u0004 והאפרוחים הללו במצבם עתה אינם ראויים לאכילת אדם. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003בידו למגמר\u0004 \u0005[לגמור]\u0006 את ה\u0003שחיטה,\u0004 ויהיו האפרוחים מותרים באכילה — \u0003\"תקח לך\" קרינא ביה\u0004 \u0005[קוראים אנו בו],\u0006 \u0003וחייב\u0004 הוא \u0003בשילוח?\u0004 שאלה זו לא נפתרה ו\u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 בלא פתרון.","ומתוך שהובאה בעייתו של רב הושעיא מביאים עוד בעיות שהעלו חכמים בדין שילוח הקן. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: מטלית\u0004 הנתונה בקן בין הציפור לבין הביצים \u0003מהו\u0004 דינה לענין \u0003שתחוץ,\u0004 שתיעשה חציצה, שתיחשב הציפור כאילו אינה רובצת על הביצים, ויהיה פטור מן השילוח? וכן שאל לענין נוצות תלושות מן ה\u0003כנפים\u0004 המונחות בין האם לבין הביצים, \u0003מהו\u0004 דינן לענין \u0003שיחוצו,\u0004 ויפטר מן השילוח?","וכן שאל לענין חציצה \u0003של\u0004 \u0003ביצים מוזרות\u0004 (שאין אפרוח יוצא מהן) המונחות בין האם לבין שאר הביצים, \u0003מהו\u0004 דינן לענין חציצה? וכן שאל לענין \u0003שני סדרי ביצים\u0004 המונחות \u0003זו על גב זו מהו\u0004 דינן לענין שסדרת הביצים העליונה תיחשב כחוצצת בין האם לבין סדרת הביצים התחתונה? ועוד שאל ר' ירמיה בענין חציצה במקרה שהיה \u0003זכר\u0004 רובץ ממש \u0003על גבי ביצים ו\u0004ה\u0003נקבה\u0004 רובצת \u0003על גבי\u0004 ה\u0003זכר מהו\u0004 הדין? ומסכמים כי כל השאלות הללו לא נפתרו ו\u0003תיקו\u0004 \u0005[תעמודנה,\u0006 תישארנה\u0005]\u0006 בלתי פתורות.","וכיוצא בדבר \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא\u0004 במקרה של \u0003יונה\u0004 הרובצת \u0003על ביצי\u0004 עוף \u0003תסיל\u0004 (שהוא עוף טהור הדומה ליונה), \u0003מהו\u0004 הדין לענין מצות שילוח הקן. וכן שאל במקרה של \u0003תסיל\u0004 הרובצת \u0003על ביצי יונה מהו\u0004 הדין לענין שילוח הקן.","\u0003אמר אביי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה בדינה של תסיל הרובצת על ביצי יונה, ממה ששנינו במשנתנו כי \u0003עוף טמא\u0004 ה\u0003רובץ על ביצי עוף טהור, ו\u0004כן עוף \u0003טהור\u0004 ה\u0003רובץ על ביצי עוף טמא\u0004 — זה וזה \u0003פטור משילוח.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם הוא היה עוף \u0003טהור\u0004 על ביצי עוף \u0003טהור,\u0004 כדוגמת תסיל הרובצת על ביצי יונה — הריהו \u0003חייב!\u0004 ודוחים: אין זו ראיה, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר פה דווקא \u0003בקורא\u0004 נקבה, שדרכה הוא לרבוץ על ביצי אחרות, ולכך יש בה דין שילוח הקן כשהיא רובצת על ביצי אחרות. ואולם אין אנו יודעים מה הדין בתסיל הרובצת על ביצי יונה או ביונה הרובצת על ביצי תסיל שאין זה דרכם.","שנינו במשנתנו בדינו של \u0003קורא זכר,\u0004 ש\u0003ר' אליעזר מחייב\u0004 בו בשילוח הקן, \u0003וחכמים פוטרין. אמר ר' אבהו: מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטתו של \u0003ר' אליעזר? אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של המלים \u0003\"דגירה\" \"דגירה\".\u0004 שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בענינו של הקורא\u0005]\u0006 \u0003\"קורא דגר ולא ילד\"\u0004 (ירמיה יז, יא), \u0003וכתיב התם\u0004 \u0005[ונאמר שם,\u0006 בענין עשיית קן\u0005]\u0006 בידי עוף ממין הנקבה \"שמה קננה קפוז ותמלט \u0003ובקעה ודגרה בצלה\"\u0004 (ישעיה לד, טו), להורות שכדרך שציפור נקבה דוגרת בקן, כן הוא הקורא הזכר, ולכך חייבים בו בשילוח.","ועוד בהסבר שיטותיהם של ר' אליעזר וחכמים, \u0003אמר ר' אלעזר: מחלוקת\u0004 זו אינה אלא \u0003בקורא זכר, אבל בקורא נקבה\u0004 — \u0003ל\u0004\u0003דברי הכל,\u0004 אף לדברי חכמים, הריהו \u0003חייב\u0004 בשילוח הקן. ותוהים על דברי ר' אלעזר: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שהרי \u0003\"קורא זכר\" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]!\u0006 ומשיבים: יש חידוש בדברי ר' אלעזר, שכן \u0003מהו דתימא\u0004 \u0005[\u0006היה מקום \u0005שתאמר]\u0006 כי \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003אפילו\u0004 ב\u0003קורא נקבה פטרי\u0004 \u0005[פוטרים]\u0006 משילוח, \u0003והא דקתני\u0004 \u0005[וזה ששנה]\u0006 במשנה במחלוקתם \"קורא \u0003זכר\"\u0004 — \u0003להודיעך כחו\u0004 של \u0003ר' אליעזר,\u0004 שלא רק בקורא נקבה הוא מחייב בשילוח הקן, אלא אף בקורא זכר. לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' אלעזר, \u0005משמיע לנו]\u0006 שלדעת חכמים שבקורא נקבה חייבים בשילוח הקן.","\u0003ו\u0004עוד \u0003אמר ר' אלעזר\u0004 בהסבר מחלוקת זו של ר' אליעזר וחכמים: \u0003מחלוקת\u0004 זו אינה אלא \u0003בקורא זכר, אבל בזכר דעלמא\u0004 \u0005[סתם]\u0006 שלא ממין הקורא — ל\u0003דברי הכל,\u0004 ואף לדעת ר' אליעזר, \u0003פטור\u0004 המוצא משילוח הקן. ותוהים על דבריו: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, והלא \u0003\"קורא זכר\" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]!\u0006 ומשיבים: חידוש יש בדברי ר' אלעזר, שכן \u0003מהו דתימא\u0004 \u0005[\u0006היה מקום \u0005שתאמר]\u0006 כי \u0003ר' אליעזר אפילו זכר דעלמא\u0004 \u0005[סתם]\u0006 \u0003מחייב\u0004 בשילוח הקן, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 במשנתנו במחלוקתו עם חכמים \u0003\"קורא זכר\"\u0004 — \u0003להודיעך כחן דרבנן\u0004 \u0005[של חכמים],\u0006 שלא רק בסתם זכר, אלא אפילו בקורא זכר הריהם פוטרים. לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' אלעזר, \u0005משמיע לנו]\u0006 שלדעת ר' אליעזר אין מצות שילוח הקן בסתם זכר.","ומביאים ראיה לדבר, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003זכר דעלמא\u0004 \u0005[סתם]\u0006 — \u0003פטור, קורא זכר\u0004 — \u0003ר' אליעזר מחייב, וחכמים פוטרין.\u0004","\u0003היתה\u0004 האם \u0003מעופפת\u0004 (מרחפת) על האפרוחים או על הביצים שבקן, \u0003בזמן שכנפיה נוגעות\u0004 באפרוחים או בביצים ש\u0003בקן\u0004 — הריהו \u0003חייב לשלח\u0004 את האם, ובזמן ש\u0003אין כנפיה נוגעות בקן\u0004 — \u0003פטור מלשלח.\u0004 אף אם \u0003אין שם\u0004 בקן \u0003אלא אפרוח אחד או ביצה אחת\u0004 — \u0003חייב לשלח, ש\u0004כן \u0003נאמר \"קן\",\u0004 לומר: \u0003קן מכל מקום.\u0004","\u0003היו שם אפרוחים מפריחים\u0004 הגדולים דיים כדי לעוף \u0003או ביצים מוזרות\u0004 מקולקלות, שאין אפרוח עתיד לבקוע מתוכן — \u0003פטור מלשלח, ש\u0004כן \u0003נאמר \"והאם רובצת על האפרוחים או על הביצים\"\u0004 (דברים כב, ו), הושוו אפרוחים לביצים, ללמד: \u0003מה אפרוחים\u0004 הם \u0003בני קיימא, אף ביצים בני קיימא, יצאו\u0004 הביצים ה\u0003מוזרות,\u0004 שאין הן בנות קיימא. \u0003ומה הביצים צריכין לאמן\u0004 לדגירה, \u0003אף האפרוחין\u0004 שחייבים בהם בשילוח הקן, מדובר רק באלה ה\u0003צריכין\u0004 עדיין \u0003לאמן, יצאו\u0004 מכלל מצות שילוח הקן האפרוחים שכבר \u0003מפריחין\u0004 שאין צריכים עוד לאימם.","שנינו במשנתנו דין הקן בזמן שהאם מעופפת, ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על הכתוב \u0003\"רובצת\"\u0004 — דווקא באופן זה הריהו חייב בשילוח, \u0003ולא\u0004 ב\u0003מעופפת. יכול\u0004 יהא פטור משילוח \u0003אפילו\u0004 במעופפת \u0003ש\u0004\u0003כנפיה נוגעות בקן?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"רובצת\",\u0004 שבאופן זה הריהו חייב בשילוח. ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד],\u0006 כיצד למדים אנו כן מהמלה \"רובצת\" לחייב בשילוח בזו שכנפיה נוגעות בקן? ומשיבים: \u0003מדלא כתיב\u0004 \u0005[מתוך שלא נאמר]\u0006 \u0003\"יושבת\"\u0004 אלא \"רובצת\", וכשכנפיה נוגעות בקן הרי זה בכלל \"רובצת\".","ומביאים עוד בענין זה מה ש\u0003אמר רב יהודה אמר רב:\u0004 אם \u0003היתה\u0004 האם \u0003יושבת\u0004 מעל הביצים או האפרוחים כשהיא \u0003בין שני רובדי\u0004 (ענפי) \u0003אילן\u0004 — \u0003רואים, כל\u0004 \u0003שאם תשמט\u0004 הציפור (אם הענפים יפרדו) היא \u0003נופלת עליהם\u0004 (על הביצים או האפרוחים) — \u0003חייב לשלח, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פטור\u0004 מלשלח.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב ממה ששנינו \u0003היתה\u0004 האם \u0003יושבת ביניהן\u0004 בין הביצים או האפרוחים — \u0003פטור מלשלח,\u0004 שכן נאמר במצות שילוח \"והאם רובצת על האפרוחים או על הביצים\", \u0003ולא שיושבת ביניהם. ואולם אם\u0004 היתה יושבת \u0003על גביהן\u0004 — \u0003חייב לשלח,\u0004 שהרי זה בכלל \"רובצת על\". ואם \u0003היתה מעופפת, אפילו כנפיה נוגעות בקן\u0004 — \u0003פטור מלשלח.\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה לומר שיושבת \u0003על גביהן\u0004 הריהו \u0003דומיא\u0004 \u0005[דומה]\u0006 לאופן הישיבה של זו שיושבת \u0003ביניהן, מה\u0004 היושבת \u0003ביניהן\u0004 הרי זה \u0003דנגעה בהו\u0004 \u0005[שנוגעת\u0006 היא \u0005בהם],\u0006 \u0003אף\u0004 זו היושבת \u0003על גביהן\u0004 מדובר \u0003דנגעה בהו\u0004 \u0005[שנוגעת בהם],\u0006 ונלמד מכאן שרק כשהיא נוגעת בהם יש דין שילוח, \u0003אבל\u0004 היושבת בין שני \u0003רובדי אילן,\u0004 ואין היא נוגעת בהם — \u0003פטור\u0004 משילוח, ושלא כדברי רב!","ודוחים: \u0003לא,\u0004 יש לפרש להיפך, ולומר כי אופן הישיבה של זו שיושבת \u0003על גביהן\u0004 הריהו \u0003דומיא\u0004 \u0005[דומה]\u0006 לאופן הישיבה של זו שיושבת \u0003ביניהן, מה\u0004 היושבת \u0003ביניהן\u0004 הרי זה באופן \u0003דלא נגעה עלייהו\u0004 \u0005[שאינה נוגעת בהם]\u0006 מלמעלה אלא מן הצד, \u0003אף\u0004 אופן הישיבה של זו שיושבת \u0003על גביהן\u0004 מדובר באופן \u0003דלא נגעה עלייהו\u0004 \u0005[שאינה נוגעת בהם]\u0006 מלמעלה אלא מן הצד, הרי איפוא שיש חיוב שילוח באם היושבת על בניה אף שאינה נוגעת בהם, \u0003והיינו\u0004 \u0005[וזהו]\u0006 אותו אופן של האם היושבת בין \u0003רובדי אילן,\u0004 שאמר רב שחייב בשילוח.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005]\u0006 שביושבת בין שני רובדי אילן יש חיוב שילוח, \u0003דאי סלקא דעתך\u0004 \u0005[ש\u0006כן \u0005אם עולה על דעתך\u0006 לומר\u0005]\u0006 שביושבת בין שני \u0003רובדי אילן פטור\u0004 משילוח — \u0003אדתני\u0004 \u0005[עד ש\u0006התנא בברייתא \u0005שונה]\u0006 \u0003היתה מעופפת, אפילו כנפיה נוגעות בקן\u0004 — \u0003פטור מלשלח, ליתני\u0004 \u0005[שישנה]\u0006 שביושבת בין שני \u0003רובדי אילן\u0004 פטור משילוח, \u0003וכל שכן\u0004 באופן שהיא \u0003מעופפת!\u0004","ודוחים: לא שנה כן התנא, משום ש\u0003מעופפת איצטריך ליה\u0004 \u0005[הוצרך לו]\u0006 לשנות, ובשל החידוש שיש בה, ש\u0003אפילו כנפיה נוגעות בקן פטור מלשלח.\u0004 ולא היינו למדים כן אילו היה שונה את דינו ביושבת בין שני רובדי אילן, שאין כנפיה של זו נוגעות בקן.","ובענין זה מקשים על דברי הברייתא הפוטרת משילוח בזמן שמעופפת וכנפיה נוגעות בקן: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 בדינה של המעופפת כי \u0003בזמן שכנפיה נוגעות בקן חייב לשלח! אמר ר' ירמיה: כי קתני מתניתא\u0004 \u0005[כאשר שנויה הברייתא]\u0006 הרי זה \u0003בנוגע מן הצד,\u0004 ואין הכנפים נוגעות מלמעלה, שבאופן זה פטורים משילוח, ואילו משנתנו מדברת במעופפת שכנפיה נוגעות בקן מלמעלה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את הסוגיה הזו בלשון שונה: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו],\u0006 ממה ששנינו בברייתא: \u0003היתה יושבת ביניהן\u0004 — \u0003פטור מלשלח,\u0004 ואם יושבת \u0003על גביהן\u0004 — \u0003חייב לשלח. היתה מעופפת, אפילו כנפיה נוגעות בקן\u0004 — \u0003פטור מלשלח.\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה לומר שאופן הישיבה של זו שיושבת \u0003על גביהן\u0004 הריהו \u0003דומיא\u0004 \u0005[דומה]\u0006 לאופן הישיבה של זו שיושבת \u0003ביניהן. מה\u0004 היושבת \u0003ביניהן\u0004 מדובר \u0003דלא נגעה עלייהו\u0004 \u0005[שאינה נוגעת בהם]\u0006 מלמעלה, \u0003אף\u0004 היושבת \u0003על גביהן\u0004 מדובר \u0003דלא נגעה עלייהו\u0004 \u0005[שאינה נוגעת בהם]\u0006 מלמעלה, ושונים אנו כי חייבים באופן זה בשילוח, \u0003והיינו\u0004 \u0005[וזהו]\u0006 כדברי רב באם היושבת בין שני \u0003רובדי אילן,\u0004 שאינה נוגעת בהם מלמעלה.","ודוחים: \u0003לא,\u0004 אפשר לומר בדרך שונה: אופן הישיבה של זו שיושבת \u0003על גביהן דומיא\u0004 \u0005[דומה]\u0006 לאופן הישיבה של זו שיושבת \u0003ביניהן. מה\u0004 ביושבת \u0003ביניהן\u0004 מדובר \u0003דנגעה בהו\u0004 \u0005[שנוגעת בהם],\u0006 \u0003אף\u0004 ביושבת \u0003על גביהן\u0004 מדובר \u0003דנגעה בהו\u0004 \u0005[שנוגעת בהם],\u0006 וללמדנו שרק באופן זה חייבים בשילוח, \u0003אבל\u0004 ביושבת בין שני \u0003רובדי אילן,\u0004 שאין היא נוגעת בהם, \u0003פטור\u0004 משילוח, ושלא כדברי רב. ומקשים על הסבר זה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא הסבר הברייתא, \u0003אדקתני סיפא\u0004 \u0005[עד שהוא,\u0006 התנא \u0005שונה בסוף\u0006 הברייתא\u0005]\u0006 \u0003היתה מעופפת, אפילו כנפיה נוגעות בקן\u0004 — \u0003פטור.\u0004"],["\u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא את דינו ביושבת בין שני \u0003רובדי אילן\u0004 שפטור משילוח, אף שהוא דומה לרביצה, שהרי האם יושבת, \u0003ו\u0004נדע כי \u0003כל שכן\u0004 שכך הדין \u0003ב\u0004\u0003מעופפת,\u0004 שאינה דומה כלל לרובצת, שפטור! ומשיבים: לא שנה כן התנא, משום ש\u0003מעופפת איצטריך ליה\u0004 \u0005[הוצרך לו]\u0006 לשנות, שכן חידוש דין יש בדבר זה, ש\u0003אפילו כנפיה נוגעות בקן\u0004 — \u0003פטור מלשלח.\u0004 ואילו היה משמיענו בזו שיושבת בין רובדי אילן, לא היינו יודעים חידוש זה, שהרי אין כנפיה נוגעות בקן.","ומקשים על דברי הברייתא הפוטרת משילוח באם מעופפת אף שכנפיה נוגעות בקן: \u0003והאנן תנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 בדינה של המעופפת ש\u0003בזמן שכנפיה נוגעות בקן\u0004 — \u0003חייב לשלח! אמר רב יהודה: כי קתני מתניתין\u0004 \u0005[כאשר שנויה הברייתא שלנו]\u0006 הרי זה \u0003ב\u0004אופן שמגע האם עם הקן \u0003נוגע מן הצד,\u0004 ולכך פטור משילוח, ואילו משנתנו מדברת במעופפת שכנפיה נוגעות בקן מלמעלה, ולכך חייב בשילוח.","שנינו במשנתנו כי אף אם \u0003אין שם\u0004 בקן אלא \u0003אפרוח\u0004 אחד או ביצה אחת — חייבים בשילוח, וטעם הדבר: משום שנאמר במצות שילוח הקן \"כי יקרא קן צפור לפניך בדרך בכל עץ או על הארץ אפרוחים או ביצים והאם רובצת על האפרוחים או על הביצים\" (דברים כב, ו), והלשון \"קן\" מלמדת שמדובר בכל קן, גם זה שיש בו אפרוח אחד או ביצה אחת. ועוד אמרה המשנה שקן שיש בו אפרוחים מפריחים או ביצים מוזרות הריהו פטור משילוח, וטעם הדבר: משום שנאמר \"והאם רובצת על האפרוחים או על הביצים\" — באה ההשוואה ביניהם להקישם וללמד שצריך שיהיו הבנים בני קיימא וצריכים לאימם. ובענין זה מביאים מה ש\u0003אמר ליה ההוא מרבנן\u0004 \u0005[אמר לו אחד מהחכמים]\u0006 \u0003לרבא\u0004 בקושיה על דברי המשנה: \u0003אימא איפכא\u0004 \u0005[אמור להיפך],\u0006 \u0003אין שם אפרוח אלא אחד או ביצה אחת\u0004 — \u0003פטור מלשלח,\u0004 וטעם הדבר: משום \u0003דבעינן\u0004 \u0005[ש\u0006כן \u0005צריכים אנו]\u0006 בשביל לקיים את המקרא \u0003\"אפרוחים או ביצים\"\u0004 הנאמר בלשון רבים, להורות שמדובר בכמה אפרוחים או בכמה ביצים, \u0003וליכא\u0004 \u0005[ואין כאן].\u0006","וכן במקרה ש\u0003היו שם אפרוחים מפריחים או ביצים מוזרות\u0004 נאמר שהוא \u0003חייב לשלח,\u0004 וטעם הדבר: משום \u0003שנאמר \"קן\"\u0004 — \u0003קן מכל מקום!\u0004 השיב לו רבא: \u0003אם כן,\u0004 כדעתך, \u0003נכתוב קרא\u0004 \u0005[שיכתוב הפסוק]\u0006 \u0003\"והאם רובצת עליהם\", מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 הרחיב הכתוב ואמר \u0003\"והאם רובצת על האפרוחים או על הביצים\"? לאקושי\u0004 \u0005[להקיש]\u0006 \u0003אפרוחים לביצים, וביצים לאפרוחים,\u0004 וכדי ללמדנו פטור שילוח הקן באפרוחים מפריחים ובביצים מוזרות, ומהמלה \"קן\" נלמד לחייב את \u0003הקן שיש בו אפרוח אחד.\u0004","אם \u0003שלחה\u0004 את האם, \u0003וחזרה\u0004 לקינה לרבוץ על בניה, ו\u0003אפילו\u0004 אירע הדבר \u0003ארבע וחמש פעמים\u0004 — \u0003חייב\u0004 לשלחה, \u0003ש\u0004כן \u0003נאמר: \"שלח תשלח את האם\u0004 ואת הבנים תקח לך\" (שם, ז), וצורת הלשון \"שלח תשלח\" מורה שיש לשלח שוב ושוב. \u0003אמר \"הריני נוטל את האם ומשלח את הבנים\",\u0004 ואמנם שלח את הבנים — עדיין הוא \u0003חייב\u0004 לשלח את האם, \u0003ש\u0004כן \u0003נאמר \"שלח תשלח את האם\".\u0004 אם שלח את האם ולאחר מכן עמד ו\u0003נטל את הבנים והחזירן לה\u0004 לקן, \u0003ואחר כך חזרה האם\u0004 לרבוץ \u0003עליהן\u0004 — \u0003פטור מלשלח.\u0004 שכיון שכבר זכה בבנים, הרי \u0003קן זה נחשב כמזומן לפניו, ואין בזה דין שילוח.\u0004","שנינו במשנתנו שאם חזרה האם לקינה לאחר ששילחה, המצוה היא לחזור ולשלח, ואפילו היה הדבר ארבע וחמש פעמים, ונלמד הדבר מן הכתוב \"שלח תשלח\". ובענין זה \u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד מהחכמים]\u0006 \u0003לרבא\u0004 בשאלה על דברי המשנה: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: נאמר \u0003\"שלח\"\u0004 — הרי זו \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003\"תשלח\"\u0004 — \u0003תרי זימנין\u0004 \u0005[שתי פעמים],\u0006 ומכאן שאין הוא חייב שוב לשלח יותר משתי פעמים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בתשובה: אין הלכה זו נלמדת מהלשון \"שלח תשלח\" אלא מהלשון \u0003\"שלח\"\u0004 כשלעצמה, שמורה \u0003אפילו מאה פעמים,\u0004 שכך פירושה: שלח כל זמן שצריך. ואילו הלשון הנוספת \u0003\"תשלח\"\u0004 באה להורות דבר אחר. שהיה מקום לומר כי \u0003אין לי\u0004 חיוב \u0003זה\u0004 \u0003אלא\u0004 במי שנוטל את הבנים \u0003לדבר הרשות,\u0004 לצרכיו הפרטיים. ואולם זה שנוטל \u0003לדבר מצוה\u0004 (כגון לצורך קן יולדת ולשתי ציפורים לטהרת מצורע) \u0003מנין\u0004 לנו שאף הוא חייב לשלח את האם? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"תשלח\"\u0004 — \u0003מכל מקום.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בר רבא לרב כהנא: אלא טעמא\u0004 \u0005[הטעם]\u0006 לחייב שילוח הקן אף בנוטל לדבר מצוה הינו רק משום \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"תשלח\", הא לאו הכי, הוה אמינא\u0004 \u0005[הרי אילולי כן, הייתי אומר]\u0006 כי הנוטל \u0003לדבר מצוה\u0004 — \u0003לא\u0004 חייב לשלח את האם?! והרי מצות שילוח הקן מצות \u0003עשה\u0004 (\"שלח תשלח את האם\") \u0003ו\u0004מצות \u0003לא תעשה\u0004 (\"לא תקח האם על הבנים\") \u0003הוא, ו\u0004כלל הוא ש\u0003אין\u0004 מצות \u0003עשה דוחה\u0004 מצות \u0003לא תעשה ועשה!\u0004","השיב לו רב כהנא: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 דרשה זו של הכתוב \"תשלח\" אלא במקרה שכבר \u0003עבר\u0004 על איסור \u0003לא תעשה\u0004 \u0003ושקלה\u0004 \u0005[ולקחה]\u0006 \u0003לאם\u0004 עם הבנים, \u0003דלאו עבריה\u0004 \u0005[ש\u0006את \u0005הלאו\u0006 כבר \u0005עבר],\u0006 ועתה רק מצות \u0003עשה הוא דאיכא\u0004 \u0005[שיש],\u0006 לשלח אותה, ובמקרה זה היינו אומרים כי \u0003ליתי\u0004 \u0005[יבוא]\u0006 \u0003עשה\u0004 של מצוה אחרת (כטהרת היולדת והמצורע) \u0003ולידחי\u0004 \u0005[וידחה]\u0006 \u0003עשה\u0004 זה, על כן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 דרשת הכתוב \"תשלח\" \u0005משמיע לנו]\u0006 שאף באופן זה יש עליו מצות עשה לשלח את האם.","ושואלים על הסבר זה: \u0003הניחא למאן דתני\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי ששונה]\u0006 כי בכל מקרה של איסור לא תעשה ואיסור עשה שבעקבותיו (\"לאו הניתק לעשה\"), הדבר הקובע אם אמנם נחשב לו הדבר כאיסור לאו (וילקה על כך) — אם עמד ו\u0003קיימו\u0004 למצות העשה מייד לאחר שעבר על הלאו, \u0003ו\u0004אם \u0003לא קיימו\u0004 למצות העשה מיד לאחר שעבר על הלאו. שאם עמד מיד וקיים את מצות העשה, תיקן בכך את הלאו שנעבר, והריהו נחשב כמי שלא עבר. ואולם אם לא עשה כן מיד, נחשב הלאו כמי שנעשה. ואף בענייננו, כיון שלא שילח את האם מיד לאחר שלקחה, הרי זה נחשב שעבר על הלאו, ומעתה אין עליו אלא מצות עשה בלבד.","\u0003אלא למאן דתני\u0004 \u0005[ל\u0006דעת \u0005מי ששונה]\u0006 שאין עוברים על הלאו אלא אם כן \u0003בטלו\u0004 את האפשרות לקיום העשה, \u0003ו\u0004אולם כל עוד \u0003לא בטלו\u0004 — לא נחשב שהלאו כבר נעשה. אם כן, בענייננו נאמר כי כל \u0003כמה\u0004 ש\u0003לא שחטה\u0004 לאם, עדיין לא ביטל את האפשרות לקיום העשה, שהרי יכול עדיין לשלח אותה, ולכך עדיין גם \u0003לא עבריה ללאו\u0004 \u0005[לא עבר על הלאו],\u0006 ומעתה, גם במקרה שעבר ולקח את האם, עדיין יש לו מצות עשה ומצות לא תעשה, ואין מצות עשה דוחה מצות לא תעשה ועשה, ולכך אין צורך בדרשת פסוק ללמדנו על קיום מצוה זו גם במקרה שכזה!","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול \u0003ל\u0004דעת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 כי הציווי \u0003\"שלח\"\u0004 — \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003משמע,\u0004 שלא אמרה תורה אלא שכשהוא בא אל הקן שישלח את האם בטרם יקח את הבנים. ואולם אם כבר עבר ולקח את האם, בכך עבר על מצות העשה, ושוב אין עליו מצוה לשלחה. ולשיטה זו אם עבר ולקח את האם, לא רק שאין עליו מצות לא תעשה, אלא \u0003אפילו\u0004 מצות \u0003עשה נמי ליכא\u0004 \u0005[גם כן אין כאן]!\u0006","\u0003אלא אמר מר בר רב אשי:\u0004 הכתוב \"תשלח\" המלמד שמצות שילוח הקן נוהגת אף בנוטל את האם לדבר מצוה מדבר באופן מסויים, ו\u0003כגון שנטלה על מנת לשלח\u0004 אותה מייד, שבאופן שכזה איסור \u0003לאו ליכא\u0004 \u0005[אין\u0006 כאן\u0005],\u0006 שהרי עומדת היא לשילוח, ולא עבר בכך על \"לא תקח האם על הבנים\", ורק מצות \u0003עשה הוא דאיכא\u0004 \u0005[שיש\u0006 כאן\u0005]\u0006 במקרה שכזה, \u0003ו\u0004מעתה היה מקום לומר כי \u0003ליתי\u0004 \u0005[תבוא]\u0006 מצות \u0003עשה\u0004 אחרת, כגון לקיחת הציפור לקרבנות המצורע והיולדת, \u0003ולידחי\u0004 \u0005[ותדחה]\u0006 את מצות ה\u0003עשה\u0004 של שילוח האם. ומשום כך בא הכתוב \"תשלח\" ללמדנו שיש מצות שילוח גם במקרה זה.","ושואלים: מדוע היה מקום לומר שתדחה מצות עשה של קרבנות המצורע והיולדת את מצות עשה של שילוח הקן, שהרי \u0003מאי אולמיה דהאי עשה מהאי עשה\u0004 \u0005[מה תוקפו של עשה זה,\u0006 טהרת המצורע והיולדת, \u0005מעשה זה\u0006 של שילוח הקן\u0005]?\u0006 ומשיבים: \u0003סלקא דעתך\u0004 \u0005[יעלה על דעתך],\u0006 לומר \u0003הואיל ואמר מר\u0004 \u0005[החכם]\u0006 כי \u0003גדול\u0004 ה\u0003שלום שבין איש לאשתו, שהרי אמרה תורה: שמו של הקדוש ברוך הוא שנכתב בקדושה, ימחה על המים\u0004 בבדיקת הסוטה, כדי לנקות אשה מחשד בעלה, ולהשיב את השלום שביניהם.","\u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003מצורע כיון דכמה דלא מטהר\u0004 \u0005[שכל עוד שלא נטהר]\u0006 הריהו \u0003אסור בתשמיש המטה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדין המצורע \u0003\"וישב מחוץ לאהלו שבעת ימים\"\u0004 (ויקרא יד, ח), \u0003\"אהלו\"\u0004 — \u0003זו אשתו, מכאן ש\u0004המצורע \u0003אסור בתשמיש המטה. מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון\u0004 שהמצורע \u0003אסור בתשמיש המטה, ליתי\u0004 \u0005[שתבוא]\u0006 מצות \u0003עשה דידיה\u0004 \u0005[שלו],\u0006 להיטהר ובכך לשוב אל ביתו, \u0003ולידחי\u0004 \u0005[ותדחה]\u0006 את מצות \u0003עשה\u0004 של \u0003שלוח הקן,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \u0005משמיע לנו]\u0006 שאפילו לצורך זה אין נוטלים את האם.","אדם \u0003ה\u0004עובר על דין התורה ו\u0003נוטל\u0004 מן הקן \u0003אם\u0004 הרובצת \u0003על הבנים\u0004 — \u0003ר' יהודה אומר: לוקה\u0004 על מה שעשה \u0003ואינו משלח\u0004 עוד, ששוב אין עליו מצות שילוח הקן. \u0003וחכמים אומרים:\u0004 אף שכבר נטל את האם, הריהו \u0003משלח\u0004 אותה \u0003ואינו לוקה. זה הכלל: כל מצות לא תעשה שיש בה קום עשה\u0004 לתקנה \u0003אין לוקין עליה.\u0004","שנינו במשנתנו בדעת ר' יהודה שהנוטל את האם לוקה, ואינו משלח שוב את האם. ובהסבר שיטתו של ר' יהודה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבא בר ממל:\u0004 האם \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יהודה\u0004 בהלכה זו הוא \u0003משום\u0004 ש\u0003סבר\u0004 \u0005[סבור]\u0006 ר' יהודה אף בשאר ענינים כי \u0003לאו שניתק לעשה\u0004 (וכגון זה שהלאו \"לא תקח האם\" הריהו ניתק לעשה \"שלח תשלח את האם\") \u0003לוקין עליו.\u0004","\u0003או דלמא בעלמא סבר\u0004 \u0005[או שמא בכלל\u0006 הוא \u0005סבור]\u0006 ש\u0003לאו שניתק לעשה אין לוקין עליו, והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 שלוקים על נטילת האם, \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 שהכתוב \u0003\"שלח\" מעיקרא\u0004 \u0005[מתחילה]\u0006 כשנקרה לפניו הקן \u0003משמע\u0004 ולא לאחר שלקחה. והלאו אינו בכלל לאו שניתק לעשה, אלא איסור לאו לעצמו, וכשאר איסורי לאו שלוקים עליהם?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו כי ה\u0003גנב\u0004 שעבר במעשה גניבתו על איסור \"לא תגנובו\" (ויקרא יט, יא) (\u0003ו\u0004ה\u0003גזלן\u0004 שעבר במעשה גזילתו על איסור \"לא תגזול\" (שם יג) \u0003ישנן בכלל\u0004 עונש \u0003מלקות\u0004 מן התורה, כדין העובר על איסור לא תעשה, אלו \u0003דברי ר' יהודה. והא הכא\u0004 \u0005[והרי כאן\u0006 בגזילה\u0005],\u0006 \u0003לאו שניתק לעשה הוא,\u0004 שכן \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 מצד אחד \u0003\"לא תגזול\",\u0004 ואמרה גם \u0003\"והשיב את הגזלה\"\u0004 (שם ה, כג), והרי זה עשה הבא בעקבות הלאו ומתקנו. אלא ודאי \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי שיטת ר' יהודה היא שלאו הניתק לעשה לוקים עליו, ולענייננו, \u0003טעמא\u0004 \u0005[טעם]\u0006 שיטתו של \u0003ר' יהודה\u0004 בעונש מלקות לזה ששלח את האם הוא \u0003משום דקסבר\u0004 \u0005[שסבור הוא]\u0006 כי \u0003לאו שניתק לעשה לוקין עליו!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא: לאו אמינא לכו\u0004 \u0005[וכי לא אמרתי לכם]\u0006 כבר פעם כי \u0003כל מתניתא דלא תניא\u0004 \u0005[ברייתא שאינה שנויה]\u0006 ב\u0003בי\u0004 \u0005[בית]\u0006 מדרשם של"],["\u0003ר' חייא ובי\u0004 \u0005[ובית]\u0006 מדרשו של \u0003ר' אושעיא,\u0004 שדקדקו ביותר בברייתות שערכו — ברייתא \u0003משבשתא\u0004 \u0005[משובשת]\u0006 \u0003היא, ולא תותבו מינה בי מדרשא\u0004 \u0005[ואל תקשו ממנו בבית המדרש].\u0006 וכן הברייתא הזו שהבאתם, שאינה מבית מדרשם של ר' חייא ור' אושעיא, אי אפשר ללמוד, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 ההלכה שהגניבה והגזילה \u0003\"אינה בכלל מלקות ארבעים\"\u0004 היא זו ש\u0003תניא\u0004 \u0005[שנויה\u0006 בברייתא\u0005],\u0006 שהבינו שדעת ר' יהודה היא שלאו הניתק לעשה אין לוקים עליו, ואילו הסבר שיטתו במשנתנו הוא משום שסבור הוא כי מצות \"שלח\" אינה אלא בתחילה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעייתו של ר' אבא בר ממל מברייתא \u0003דתני\u0004 \u0005[ששנו]\u0006 \u0003ר' אושעיא ור' חייא\u0004 בדין השכחה שנאמר בו \"כי תקצור קצירך בשדך ושכחת עומר בשדה \u0003לא תשוב\u0004 לקחתו\" (דברים כד, יט), אם \u0003שב\u0004ולקחה מן השדה. וכמו כן בדין הפאה שנאמר בו \"ובקוצרכם את קציר ארצכם \u0003לא תכלה\u0004 פאת שדך לקצור\" (ויקרא יט, ט), אם \u0003כלה\u0004 את תבואת שדהו — \u0003ישנן בכלל מלקות ארבעים,\u0004 אלו \u0003דברי ר' יהודה.\u0004","ומעתה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003טעמיה\u0004 \u0005[טעמו,\u0006 טעם שיטתו\u0005]\u0006 של \u0003ר' יהודה משום דקסבר\u0004 \u0005[שסבור]\u0006 \u0003לאו שניתק לעשה לוקין עליו,\u0004 ש\u0003אף שאיסורי לאו אלה בשכחה ובפאה ניתקים למצות עשה \"לעני ולגר תעזוב אותם\" (שם י), בכל זאת לוקים על הלאו. ומכאן נלמד גם בהסבר דעתו של ר' יהודה במשנתנו לענין הלוקח את האם שהריהו לוקה על כך.\u0004","ודוחים: אין זו ראיה, כי \u0003דלמא התם היינו\u0004 \u0005[שמא שם,\u0006 בשכחה ובפאה \u0005זהו]\u0006 ה\u0003טעם\u0004 שלוקים על כך, משום \u0003דקסבר\u0004 \u0005[שסבור הוא\u0006 ר' יהודה\u0005]\u0006 כי המצוה \"לעני ולגר \u0003תעזוב\u0004 אותם\" אינה מצות עשה הבאה לאחר שכבר עבר את הלאו, שהרי זה לאו הניתק לעשה, אלא \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003משמע,\u0004 ולא לאחר מעשה. ומעתה אין האיסורים \"לא תשוב\" ו\"לא תכלה\" בכלל לאו הניתק לעשה. ובדומה לכך אף במשנתנו טעמו של ר' יהודה הוא משום שמשמע המצוה \"שלח\" הוא מתחילה. ולא נפתרה עדיין בעייתו של ר' אבא בר ממל.","ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא על הנאמר בקרבן פסח \"ו \u0003לא תותירו ממנו עד בקר\u0004 והנותר ממנו עד בוקר \u0003באש תשרופו\"\u0004 (שמות יב, י) — \u0003בא הכתוב ליתן\u0004 מצות \u0003עשה\u0004 (\"באש תשרופו\") \u0003אחר\u0004 מצות \u0003לא תעשה\u0004 (\"ולא תותירו\"), \u0003לומר לך שאין לוקין עליו,\u0004 אלו \u0003דברי ר' יהודה,\u0004","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שסבור ר' יהודה כי לאו הניתק לעשה אין לוקים עליו, ומכאן כי \u0003טעמא\u0004 \u0005[טעם]\u0006 שיטתו של \u0003ר' יהודה\u0004 במשנתנו שזה שלקח את האם לוקה, הריהו \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 כי המצוה \u0003\"שלח\"\u0004 — \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003משמע,\u0004 ואין \"לא תקח האם\" בכלל לאו הניתק לעשה, אלא כשאר לאו שלוקים עליהם. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן],\u0006 שכך הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אידי לרב אשי:\u0004 \u0003מדברי\u0004 \u0003מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן יש לדייק]\u0006 שכך הוא טעם שיטתו של ר' יהודה, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 בה\u0005]:\u0006 \u0003\"הנוטל אם על הבנים\u0004 — \u0003ר' יהודה אומר: לוקה ואין משלח\", ואי סלקא דעתך טעמא\u0004 \u0005[ואם עולה על דעתך\u0006 לומר כי \u0005טעם]\u0006 שיטת \u0003ר' יהודה\u0004 הוא מפני ש\u0003לאו שניתק לעשה לוקין עליו, \"לוקה ומשלח\" מבעי ליה\u0004 \u0005[צריך היה לו לומר]!\u0006","\u0003ו\u0004דוחים: מדברי משנתנו עצמה אין לדייק, שכן \u0003דלמא הכי קאמר במתניתין\u0004 \u0005[שמא כך הוא אומר במשנתנו]\u0006 שאמנם חייב הוא עדיין בשילוח, ואולם \u0003אין\u0004 הוא \u0003נפטר\u0004 מן הלאו \u0003עד דמלקין ליה\u0004 \u0005[שמלקים אותו].\u0006","שנינו במשנתנו בדעת חכמים שאם עבר ונטל את האם הריהו חייב לשלחה, ומבררים: \u0003עד כמה,\u0004 עד איזה מרחק מן הקן הוא \u0003משלחה? אמר רב יהודה:\u0004 מרחק שיש בו \u0003כדי שתצא מתחת ידו\u0004 ולא יוכל לתופסה מיד. ועוד מבררים: \u0003במה\u0004 (באיזה אופן) הוא \u0003משלחה? רב הונא אמר:\u0004 יאחזנה \u0003ברגליה\u0004 וישלחה, ואילו \u0003רב יהודה אמר:\u0004 יאחזנה \u0003באגפיה\u0004 (בכנפיה) וישלחנה. ומסבירים את טעמיהם: \u0003רב הונא אמר\u0004 שהשילוח נעשה באחיזה \u0003ברגליה,\u0004 וראיה לדבר \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"משלחי רגל השור והחמור\"\u0004 (ישעיה לב, כ) — הרי ששילוחם של בעלי חיים מתייחס לרגליהם. ואילו \u0003רב יהודה אמר\u0004 שהשילוח נעשה באחיזה \u0003באגפיה,\u0004 \u0003דהא\u0004 \u0005[שהרי]\u0006 רגליהם של השור והחמור (שבהן הם נעים ממקום למקום), אצל ציפור \u0003כנפיה נינהו\u0004 \u0005[הן],\u0006 שבהן היא נעה ממקום למקום.","ומסופר, \u0003ההוא דגזינהו לגפה\u0004 \u0005[אדם אחד שחתך את כנפה]\u0006 של האם, \u0003ושלחה,\u0004 \u0003ואחר כך\u0004 חזר ו\u0003תפשה,\u0004 מפני שלא יכלה לברוח. \u0003נגדיה\u0004 \u0005[הלקה אותו]\u0006 \u0003רב יהודה\u0004 על שעבר על איסור \"לא תקח האם על הבנים\" (דברים כב, ז). \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה לאותו אדם: \u0003זיל, רבי לה גדפיה\u0004 \u0005[לך, גדל לה,\u0006 המתן עד שיצמחו שוב \u0005כנפיה],\u0006 \u0003ושלחה!\u0004","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 נהג רב יהודה שהלקה על כך וגם הורה לו לשוב ולשלחה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה\u0004 במשנתנו בדינו של זה שעבר ונטל את האם — הרי אמר ש\u0003לוקה ואין משלח! אי כרבנן\u0004 \u0005[אם כ\u0006דעת \u0005חכמים]\u0006 שחלקו על ר' יהודה — הרי אמרו \u0003ש\u0004\u0003משלח ואין לוקה!\u0004 ומשיבים: \u0003לעולם\u0004 סבור רב יהודה \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים],\u0006 \u0003ו\u0004המלקות שלקה זה, \u0003מכת מרדות מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 היא, על שנהג שלא כדין, ולא מלקות כעונש מן התורה.","ועוד בהוראות חכמים בשילוח הקן. \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם לרבא בשאלה: העוף הנקרא \u0003תימה,\u0004 שעוף טהור הוא, \u0003מהו\u0004 דינו לענין מצות שילוח הקן? תמה רבה ו\u0003אמר:\u0004 האם \u0003לא ידע האי גברא\u0004 \u0005[אין אדם זה יודע]\u0006 הלכה פשוטה כי \u0003עוף טהור חייב לשלוחי\u0004 \u0005[בשילוח]?\u0006 אמר לו אותו אדם: אכן יודע אני, ואולם עדיין יש לי שאלה בדבר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003דילמא חדא ביעתא הוא דרמיא\u0004 \u0005[שמא\u0006 רק \u0005ביצה אחת היא המוטלת]\u0006 בקן, ולכך אתה מסופק אם יש בקן זה מצות שילוח, שהרי בתורה נאמר \"אפרוחים או ביצים\". השיב אותו אדם כי אכן כך הוא ספקו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: אף הדין באופן \u0003האי ידעי לך\u0004 \u0005[\u0006\u0005זה\u0006 ידוע\u0005]\u0006 \u0003לך,\u0004 שכן \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא\u0004 זו ששנינו בה כי אם \u0003אין שם אלא אפרוח אחד או ביצה אחת\u0004 — \u0003חייב לשלח.\u0004","עמד אותו אדם ו\u0003שלחה,\u0004 \u0003ואהדר לה\u0004 \u0005[והקיף אותה]\u0006 \u0003רבא פרסתקי\u0004 \u0005[מצודות]\u0006 \u0003ותפסה.\u0004 ושואלים: \u0003וליחוש לחשדא\u0004 \u0005[ונחשוש לחשד]\u0006 שרבא פסק לו לשלח אותה רק כדי שהוא יצוד את הציפור! ומשיבים: אין מקום לחשש זה, שכן הציב רבא את המצודות רחוק מן הקן, \u0003כלאחר יד,\u0004 שלא היה נראה כעושה בכוונה.","ועוד בדיני שילוח הקן, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003יוני שובך ויוני עלייה\u0004 — \u0003חייבות בשלוח,\u0004 שאינן נחשבות כמזומנות לפניו, שהריהן כהפקר, \u0003ו\u0004אולם \u0003אסורות\u0004 לאדם אחר לקחתן משם \u0003משום גזל\u0004 מדברי חכמים, שכך תיקנו חכמים \u0003מפני דרכי שלום. ו\u0004שואלים על דין זה:","\u0003אי איתא להא דאמר\u0004 \u0005[ואם יש\u0006 לקבל להלכה \u0005את זה]\u0006 ש\u0003אמר ר' יוסי בר ר' חנינא\u0004 כי \u0003חצרו של אדם קונה לו\u0004 את הדבר הנמצא בה, אף אם זה \u0003שלא מדעתו,\u0004 אם כן מדוע חייב הוא במצות שילוח ביוני שובך וביוני עלייה, שהרי \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 במקרה הזה את הכתוב במצות שילוח הקן \"כי יקרא קן צפור לפניך... לא תקח האם על הבנים. שלח תשלח את האם ואת הבנים תקח לך\" (דברים כב, ו), ומהלשון \u0003\"כי יקרא\"\u0004 דרשו חכמים: \u0003פרט למזומן\u0004 ויונים אלה הן בתוך חצירו!","\u0003אמר רב\u0004 בתשובה: \u0003ביצה\u0004 של הציפור שבקן — \u0003עם יציאת רובה\u0004 מבטן אמה \u0003הוא\u0004 הזמן \u0003דאחייב\u0004 \u0005[שחייב]\u0006 \u0003בשלוח,\u0004 ואולם \u0003מקנא\u0004 \u0005[לקנות]\u0006 עדיין \u0003לא קני\u0004 \u0005[לא קונה]\u0006 בעל החצר \u0003עד\u0004 ש\u0003תפול\u0004 כל הביצה כולה \u0003לחצרו, וכי קתני\u0004 \u0005[וכאשר שנה]\u0006 ש\u0003חייבות\u0004 היונים הללו \u0003בשלוח\u0004 — בשלב ש\u0003מקמי\u0004 \u0005[לפני]\u0006 ש\u0003תפול\u0004 הביצה \u0003לחצרו.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מסביר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 בשלב זה \u0003אסורות\u0004 הביצים \u0003משום גזל,\u0004 שהרי באותה עת עדיין לא נקנו לבעל החצר? ומשיבים: מוסבים הדברים על \u0003אמם,\u0004 שהיא אסורה משום גזל. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003לעולם\u0004 מדובר על ה\u0003ביצה\u0004 עצמה שאסורה משום גזל מדברי חכמים, \u0003ו\u0004טעם הדבר הוא משום שה\u0003ביצה כיון דנפיק ליה רובא\u0004 \u0005[שיצאה לה רובה]\u0006 מבטן האם — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 של הבעלים \u0003עליה.\u0004","ומוסיפים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב\u0004 כי \u0003אסור לזכות בביצים שהאם רובצת עליהן, ש\u0004כן \u0003נאמר\u0004 בתחילה \u0003\"שלח\u0004 תשלח \u0003את האם\" והדר\u0004 \u0005[ואחר כך]\u0006 נאמר \"ואת \u0003הבנים תקח לך\", אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שמדובר ש\u0003נפל לחצרו\u0004 — הריהו חייב בהן בשילוח, כי כלל הוא: \u0003כל היכא דאיהו מצי זכי\u0004 \u0005[כל מקום שהוא\u0006 עצמו \u0005יכול לזכות]\u0006 בדבר מסויים, \u0003חצרו נמי זכיא\u0004 \u0005[גם כן זוכה]\u0006 באותו הדבר עבורו. \u0003וכל היכא דאיהו לא מצי זכי\u0004 \u0005[וכל מקום שהוא\u0006 עצמו \u0005אינו יכול לזכות]\u0006 בדבר מסויים, \u0003חצרו נמי לא זכיא ליה\u0004 \u0005[גם כן אינה זוכה לו].\u0006 ולכך, בקן שהאם רובצת על אפרוחיה, כיון שהוא עצמו אינו יכול לזכות באפרוחים בזמן שהאם רובצת עליהם ובלא ששילחה מהקן, כך גם חצירו אינה זוכה לו בהם.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא הסבר הדברים, \u0003אמאי\u0004 \u0005[מדוע]\u0006 הביצים \u0003אסורות מפני דרכי שלום,\u0004 שהרי \u0003אי\u0004 \u0005[אם]\u0006 כבר עמד ו\u0003שלחה\u0004 את האם — הרי \u0003גזל מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא!\u0004 ו\u0003אי\u0004 \u0005[אם]\u0006 מדובר כשעדיין \u0003לא שלחה\u0004 לאם — כיצד הוא יכול לקחת את הביצים, והרי תחילה \u0003שלוחי בעי\u0004 \u0005[לשלח\u0006 הוא \u0005צריך]!\u0006","ומשיבים: מדובר פה \u0003בקטן\u0004 הלוקח את הביצים, שאינו חייב במצות שילוח הקן. ותוהים: וכי \u0003קטן בר\u0004 \u0005[בן]\u0006 \u0003דרכי שלום הוא,\u0004 לומר שבו נאמרה הלכה זו בברייתא? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אביו של קטן חייב להחזיר לו\u0004 לבעל השובך את הביצים שנלקחו, \u0003מפני דרכי שלום.\u0004","למעלה הובא דינן של יוני שובך במצות שילוח הקן, ובענין זה מסופר כי \u0003לוי בר סימון אקני\u0004 \u0005[הקנה]\u0006 את \u0003פירות\u0004 (תוצרת) \u0003שובכו,\u0004 הם האפרוחים והביצים שבו, \u0003לרב יהודה. אתא\u0004 \u0005[בא]\u0006 רב יהודה \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל\u0004 וסיפר לו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל, טרוף אקן\u0004 \u0005[לך, הקש על הקן],\u0006 באופן \u0003דליתגבהו\u0004 \u0005[שיתרוממו]\u0006 האפרוחים על ידי הרעש, \u0003וקנינהו\u0004 \u0005[ותקנה אותם]\u0006 בהגבהה זו.","ושואלים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 יעץ לו לנהוג כן? \u0003אי למקנא\u0004 \u0005[אם\u0006 לצורך \u0005קנין]\u0006 — \u0003לקנינהו ליה\u0004 \u0005[שיקנה לו]\u0006 את האפרוחים על ידי קנין \u0003סודר,\u0004 ולמה לו ללכת לשם! \u0003אי\u0004 \u0005[אם]\u0006 לענין \u0003יום טוב\u0004 שהיה הדבר בערב יום טוב, ובא רב יהודה לפני שמואל לשאול איזו הכנה יעשה על מנת שלא יהיו האפרוחים אסורים למחרת משום מוקצה, ויוכל לשוחטם ביום טוב —"],["הרי \u0003בעומד\u0004 בערב יום טוב \u0003ואומר \"זה וזה\u0004 מן האפרוחים או מן הביצים \u0003אני נוטל\u0004 למחרת ביום טוב\", \u0003סגיא\u0004 \u0005[די]\u0006 בכך שלא יהיו אלה בכלל מוקצה, ולא נצרך רב יהודה להקיש על הקן! ומשיבים: \u0003הנהו פירי חדתי הוו\u0004 \u0005[אלה,\u0006 האפרוחים והביצים \u0005פירות חדשים היו],\u0006 ש\u0003לוי בר סימון גופיה\u0004 \u0005[עצמו]\u0006 עדיין \u0003לא הוה קני להו\u0004 \u0005[לא קנה אותם],\u0006 \u0003והכי קאמר ליה\u0004 \u0005[וכך אמר לו]\u0006 שמואל לרב יהודה: \u0003זיל וטריף אקן דליתגבהו\u0004 \u0005[לך והקש על הקן, שיגביהו]\u0006 האפרוחים את עצמם, \u0003ו\u0004בכך \u0003ניקנינהו\u0004 \u0005[יקנה אותם]\u0006 \u0003לוי בר סימון\u0004 לעצמו, \u0003והדר ליקנינהו ניהלך\u0004 \u0005[ואחר כך\u0006 יחזור \u0005ויקנה אותם לך]\u0006 \u0003ב\u0004קנין \u0003סודר.\u0004","\u0003לא יטול אדם אם על בנים אפילו\u0004 כדי שתשמש צפור זו כקרבן הבא \u0003לטהר את המצורע.\u0004 ולגופה של מצוה זו, \u0003ומה אם מצוה\u0004 זו של שילוח הקן, שהיא \u0003קלה\u0004 מאוד לעשייה, \u0003ש\u0004כן \u0003היא\u0004 אין בה חסרון כיס של ממש, שהרי מפסיד בכך רק \u0003ב\u0004\u0003כאיסר,\u0004 שהוא שוויה של האם המשתלחת, \u0003אמרה\u0004 ה\u0003תורה\u0004 במתן שכרה \u0003\"למען ייטב לך והארכת ימים\"\u0004 (דברים כב, ז), \u0003קל וחומר\u0004 כמה מרובה הוא מתן השכר \u0003על\u0004 קיומן של \u0003מצות חמורות שבתורה.\u0004","שנינו במשנתנו מתן שכרה של מצות שילוח הקן הכתוב בצידה, ובענין זה מביאים עוד. \u0003תניא דבי\u0004 \u0005[שנויה\u0006 ברייתא \u0005של בית]\u0006 מדרשו של \u0003ר' יעקב אומר: אין לך כל מצוה ומצוה שבתורה שמתן שכרה\u0004 כתוב \u0003בצדה\u0004 (כמצות כיבוד אב ואם, ושילוח הקן) \u0003שאין\u0004 האמונה ב\u0003תחיית המתים תלויה בה\u0004 (נשמעת ממנה). שכן \u0003בכבוד אב ואם כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"למען יאריכון ימיך ולמען ייטב לך\"\u0004 (דברים ה, טז), ו\u0003בשילוח הקן כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"למען ייטב לך והארכת ימים\".\u0004","ומעתה, \u0003הרי שאמר לו אביו: עלה לבירה\u0004 (לבית) \u0003והבא לי גוזלות! ועלה, ושלח את האם ולקח את הבנים, ובחזרתו\u0004 כשירד משם, אחרי שקיים את המצוה \u0003נפל ומת, היכן אריכות ימיו של זה? והיכן טובתו של זה? אלא\u0004 חייב אתה לפרש כי \u0003\"למען יאריכון ימיך\"\u0004 — כוונתו \u0003בעולם שכולו ארוך, \"ולמען ייטב לך\"\u0004 — \u0003לעולם שכולו טוב.\u0004","ותוהים: \u0003ודלמא לא הוה הכי\u0004 \u0005[ושמא לא היה כך]?\u0006 ור' יעקב מספר רק על אפשרות, ושמא מעולם לא היה דבר כזה? ומשיבים: \u0003ר' יעקב מעשה חזא\u0004 \u0005[ראה]\u0006 שכך היה. ואומרים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מהרהר בעבירה הוה\u0004 \u0005[היה]\u0006 באותה שעה, ולכך נפל ומת? ומשיבים: אף אם הרהר בעבירה באותה שעה, לא היה נענש על כך, כי \u0003מחשבה רעה אין הקדוש ברוך הוא מצרפה למעשה\u0004 ואין מעניש עליה. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מהרהר בעבודה זרה הוה\u0004 \u0005[היה]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בעבודה זרה: \u0003\"למען תפוש את בית ישראל בלבם\"\u0004 (יחזקאל יד, ה), \u0003ואמר רב אחא בר יעקב: זו מחשבת עבודה זרה\u0004 שעליה נענשים!","","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 ר' יעקב, \u0005אמר]\u0006 בעקבות מעשה זה שראה: \u0003אם איתא דאיכא\u0004 \u0005[יש,\u0006 כך הוא, \u0005שיש]\u0006 \u0003שכר מצות בהאי עלמא\u0004 \u0005[בעולם הזה]\u0006 — \u0003תהני ליה\u0004 \u0005[תועיל לו]\u0006 המצוה שקיים, \u0003ותגן עליה\u0004 \u0005[עליו]\u0006 \u0003דלא ליתי\u0004 \u0005[שלא יבוא]\u0006 \u0003לידי הרהור וליתזק\u0004 \u0005[וינזק],\u0006 \u0003אלא\u0004 צריך לומר ש\u0003שכר מצות בהאי עלמא ליכא\u0004 \u0005[בעולם הזה אין].\u0006 ומקשים: כיצד אירע לזה שנפל ומת, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר\u0004 כי \u0003שלוחי מצוה אינן נזוקים!\u0004 ומשיבים: \u0003בחזרתם שאני\u0004 \u0005[שונה],\u0006 שכיון שכבר קיימו את המצוה, עלולים הם להינזק. ותוהים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר\u0004 כי \u0003שלוחי מצוה אינן נזוקים, לא בהליכתן ולא בחזרתן!\u0004 ומשיבים: \u0003סולם רעוע הוה\u0004 \u0005[היה שם],\u0006 \u0003ומקום\u0004 ש\u0003קבוע היזקא שאני\u0004 \u0005[היזק שונה],\u0006 שאף שלוחי מצוה עלולים להינזק בו. \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 לכשנצטוה שמואל הנביא ללכת למשוח את דוד למלך \u0003\"ויאמר שמואל איך אלך ושמע שאול והרגני\"\u0004 (שמואל א טז, ב). שאף שוודאי הלך בשליחות מצוה מפי הקדוש ברוך הוא בכל זאת חשש לשלומו.","","\u0003אמר רב יוסף: אלמלא דרשיה אחר להאי קרא\u0004 \u0005[אילו היה דורש \"אחר\",\u0006 אלישע בן אבויה, \u0005למקרא זה]\u0006 \u0003כ\u0004מו \u0003ר' יעקב בר ברתיה\u0004 \u0005[בן בתו]\u0006 — \u0003לא חטא\u0004 \u0005[לא היה חוטא],\u0006 \u0003מאי חזא\u0004 \u0005[מה ראה]\u0006 אלישע בן אבויה שהביא אותו לכפירה? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003כי האי מעשה חזא\u0004 \u0005[כמו מעשה זה\u0006 שראה ר' יעקב, אף הוא \u0005ראה],\u0006 ומתוך כך בא לכלל כפירה. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 כי את \u0003לישנא\u0004 \u0005[לשונו]\u0006 של \u0003ר' חוצפית המתורגמן\u0004 (מעשרת הרוגי מלכות) \u0003חזא\u0004 \u0005[ראה],\u0006 \u0003דהוה\u0004 \u0005[שהיתה]\u0006 \u0003מוטלת באשפה\u0004 לאחר שהרגוהו. \u0003אמר\u0004 אלישע בן אבויה: \u0003פה שהפיק מרגליות\u0004 הוא \u0003ילחוך עפר?! והוא לא ידע\u0004 לדרוש: \u0003\"למען ייטב לך\"\u0004 — \u0003בעולם שכולו טוב, \"ולמען יאריכון ימיך\"\u0004 — \u0003בעולם שכולו ארוך.\u0004",""]]};
